import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAppeal";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Modify an existing appeal record for a moderation event (admin only).
 *
 * Allows updating status and decision comment for an existing moderation event appeal, as long as it is not already finalized (approved/rejected). Protects audit and compliance by forbidding any updates after outcome is final.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user making the request
 * @param props.appealId - UUID of the appeal record to update
 * @param props.body - Update fields for the appeal: status and decision_comment
 * @returns The updated appeal record after changes
 * @throws {Error} If appeal does not exist or if already finalized
 */
export async function put__shoppingMallAiBackend_admin_appeals_$appealId(
  props: {
    admin: AdminPayload;
    appealId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendAppeal.IUpdate;
  }
): Promise<IShoppingMallAiBackendAppeal> {
  const { admin, appealId, body } = props;
  // 1. Load appeal by id
  const current = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.findUnique({
    where: { id: appealId },
  });
  if (!current) throw new Error("Appeal not found");
  // 2. Block patches to finalized appeals
  if (current.status === "approved" || current.status === "rejected") {
    throw new Error("Cannot update appeal once a final decision has been made");
  }
  // 3. Apply update (patch only allowed fields)
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.update({
    where: { id: appealId },
    data: {
      status: body.status,
      decision_comment: body.decision_comment ?? null,
      updated_at: toISOStringSafe(new Date()),
    },
  });
  // 4. Map/prune return object to API type
  return {
    id: updated.id,
    moderation_event_id: updated.moderation_event_id,
    appellant_id: updated.appellant_id,
    status: updated.status,
    decision_comment: updated.decision_comment ?? null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendOrderSnapshot } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendOrderSnapshot";
import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Fetches the detailed record of a specific order snapshot by parent order ID and snapshot ID.
 *
 * Each snapshot contains a frozen JSON representation of the order for legal and historical purposes. Access is permitted only to the customer who owns the order. Throws an error if the order or snapshot does not exist, has been deleted, or access is forbidden.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.orderId - The unique identifier (UUID) of the parent order
 * @param props.orderSnapshotId - The unique identifier (UUID) of the snapshot record
 * @returns The order snapshot record with archived state
 * @throws {Error} When the order does not exist, does not belong to the customer, has been deleted, or when the snapshot does not exist
 */
export async function get__shoppingMallAiBackend_customer_orders_$orderId_orderSnapshots_$orderSnapshotId(
  props: {
    customer: CustomerPayload;
    orderId: string & tags.Format<'uuid'>;
    orderSnapshotId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendOrderSnapshot> {
  const { customer, orderId, orderSnapshotId } = props;

  // Fetch order and confirm ownership and activity
  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findFirst({
    where: {
      id: orderId,
      customer_id: customer.id,
      deleted_at: null,
    }
  });
  if (!order) {
    throw new Error("Order not found, deleted, or access is forbidden.");
  }

  // Fetch the snapshot for this order
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_order_snapshots.findFirst({
    where: {
      id: orderSnapshotId,
      order_id: orderId,
    },
  });
  if (!snapshot) {
    throw new Error("Order snapshot not found.");
  }

  // Return mapped DTO with correct branding
  return {
    id: snapshot.id,
    order_id: snapshot.order_id,
    snapshot_json: snapshot.snapshot_json,
    snapshot_reason: snapshot.snapshot_reason,
    created_at: toISOStringSafe(snapshot.created_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendArticle";


/**
 * Get article detail by articleId, including all metadata and access checks.
 *
 * Fetch full detail information for a specific article/bbs entry by articleId. Response includes all fields in shopping_mall_ai_backend_articles with author metadata and category linkage resolved. Access permissions ensure that only publicly available or owned drafts are visible to non-admins. Audit logging may be implemented to track sensitive article access (e.g. for draft, admin-only, or deleted content). Used by article detail pages, edit windows, or content preview panels.
 *
 * @param props - Request properties
 * @param props.articleId - Unique identifier of the article to retrieve
 * @returns The detailed IShoppingMallAiBackendArticle record
 * @throws {Error} When article is not found, is a draft, or is deleted/inaccessible
 */
export async function get__shoppingMallAiBackend_articles_$articleId(
  props: { articleId: string & tags.Format<'uuid'> }
): Promise<IShoppingMallAiBackendArticle> {
  const { articleId } = props;
  const article = await MyGlobal.prisma.shopping_mall_ai_backend_articles.findFirst({
    where: {
      id: articleId,
      status: 'published',
      deleted_at: null,
    },
    select: {
      id: true,
      category_id: true,
      author_type: true,
      author_id: true,
      title: true,
      summary: true,
      body: true,
      status: true,
      view_count: true,
      comment_count: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    }
  });
  if (!article) throw new Error('Article not found or inaccessible');
  return {
    id: article.id,
    category_id: article.category_id,
    author_type: article.author_type,
    author_id: article.author_id,
    title: article.title,
    summary: article.summary ?? null,
    body: article.body,
    status: article.status,
    view_count: article.view_count,
    comment_count: article.comment_count,
    created_at: toISOStringSafe(article.created_at),
    updated_at: toISOStringSafe(article.updated_at),
    deleted_at: article.deleted_at ? toISOStringSafe(article.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendMileageWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageWallet";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Update permissible attributes of a mileage wallet entry by mileageWalletId. Only updatable fields (status, label, security_code, etc.) may be changed. Enforcement of business logic and field-level validation is performed, and all updates are audit-logged for compliance.
 *
 * Admins only. Updating non-existent or immutable wallet record yields an error. No soft-deletion is supported in this endpoint.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making this request
 * @param props.mileageWalletId - UUID of the mileage wallet to update
 * @param props.body - Fields to update in the wallet
 * @returns The updated mileage wallet record
 * @throws {Error} If the wallet does not exist or is soft-deleted
 */
export async function put__shoppingMallAiBackend_admin_mileageWallets_$mileageWalletId(
  props: {
    admin: AdminPayload;
    mileageWalletId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendMileageWallet.IUpdate;
  }
): Promise<IShoppingMallAiBackendMileageWallet> {
  const { admin, mileageWalletId, body } = props;

  const wallet = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findFirst({
    where: {
      id: mileageWalletId,
      deleted_at: null,
    },
