/**
 * Soft deletes (unfavorites) a favorite address record identified by favoriteAddressId.
 *
 * Ensures the deletion is only performed by the owner (authenticated customer), and only if the favorite is not already deleted.
 * Performs a soft delete by setting the 'deleted_at' field using the current ISO 8601 time. 
 * Throws an error if the favorite is not found or already deleted, or if the authenticated user is not the owner. 
 * This operation updates only the favorite record and does not affect the underlying address entity.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the unfavorite action
 * @param props.favoriteAddressId - The UUID of the favorite address record to soft delete (unfavorite)
 * @returns void
 * @throws {Error} When the favorite address does not exist or is already unfavorited
 * @throws {Error} When the requester is not the owner of the favorite address
 */
export async function delete__shoppingMallAiBackend_customer_favoriteAddresses_$favoriteAddressId(
  props: { customer: CustomerPayload; favoriteAddressId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { customer, favoriteAddressId } = props;

  // 1. Fetch the favorite address record (must not be already soft deleted)
  const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findFirst({
    where: { id: favoriteAddressId, deleted_at: null },
  });
  if (!favorite) {
    throw new Error('Favorite address not found or already unfavorited');
  }

  // 2. Verify ownership
  if (favorite.customer_id !== customer.id) {
    throw new Error('Forbidden: You are not the owner of this favorite address');
  }

  // 3. Soft delete by updating 'deleted_at'
  await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.update({
    where: { id: favoriteAddressId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });

  // Optionally: trigger audit/notification here (out of scope for provider)
  return;
}

