 *
 * This operation allows an authenticated admin to soft-delete a moderation event by setting its deleted_at timestamp. 
 * The function ensures idempotency: if the record is already deleted or does not exist, an error is thrown. After soft-deletion, a compliance audit log is created for regulatory trace.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user (must be active)
 * @param props.moderationEventId - UUID of the moderation event to erase
 * @returns void (No content returned on completion)
 * @throws {Error} If the moderation event does not exist or is already deleted
 */
export async function delete__shoppingMallAiBackend_admin_moderationEvents_$moderationEventId(
  props: { admin: AdminPayload; moderationEventId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { admin, moderationEventId } = props;
  // Find the moderation event that is not deleted
  const event = await MyGlobal.prisma.shopping_mall_ai_backend_moderation_events.findFirst({
    where: { id: moderationEventId, deleted_at: null },
  });
  if (!event) {
    throw new Error('Moderation event not found or already deleted');
