 * verifies mapping existence and idempotency, and performs a soft delete by setting deleted_at to the current time.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the operation (SellerPayload)
 * @param props.productId - Product's unique identifier (UUID)
 * @param props.productChannelMapId - Product-channel mapping id to be deleted (UUID)
 * @returns void
 * @throws {Error} When mapping is not found or already deleted
 * @throws {Error} When the seller does not own the product
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId_productChannelMap_$productChannelMapId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productChannelMapId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { seller, productId, productChannelMapId } = props;

  // 1. Lookup active mapping; enforce not already soft-deleted
  const mapping = await MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.findFirst({
    where: {
      id: productChannelMapId,
      product_id: productId,
      deleted_at: null,
