 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user (must have active admin access)
 * @param props.productId - UUID of the product for which the tag is updated
 * @param props.productTagId - Tag record ID to update (must belong to the product)
 * @param props.body - Fields for updating the tag (only 'tag' is updatable)
 * @returns The updated product tag details
 * @throws {Error} If the product or tag does not exist, or the tag does not belong to the product
 */
export async function put__shoppingMallAiBackend_admin_products_$productId_productTags_$productTagId(props: {
  admin: AdminPayload;
  productId: string & tags.Format<'uuid'>;
  productTagId: string & tags.Format<'uuid'>;
