/**
 * Unfavorite (soft-delete) a favorite inquiry by ID.
 *
 * Remove a bookmarked inquiry from the user's favorited inquiries list via soft-delete (deleted_at).
 * Ownership is enforced; only the user who bookmarked may remove. If entry is already removed, idempotency ensures graceful success.
 *
 * This also unsubscribes the user from AI-driven notifications about the inquiry thread.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the unfavorite
 * @param props.favoriteInquiryId - The UUID of the favorite inquiry
 * @returns void
 * @throws {Error} If the favorite inquiry does not exist
 * @throws {Error} If the customer does not own this favorite inquiry
 */
export async function delete__shoppingMallAiBackend_customer_favoriteInquiries_$favoriteInquiryId(
  props: {
    customer: CustomerPayload;
    favoriteInquiryId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { customer, favoriteInquiryId } = props;

  // Retrieve the favorite inquiry
  const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findUnique({
    where: { id: favoriteInquiryId },
  });
  if (!favorite) {
    throw new Error('Favorite inquiry not found');
  }
  if (favorite.customer_id !== customer.id) {
    throw new Error('Forbidden: You do not own this favorite inquiry');
  }
  if (favorite.deleted_at !== null && favorite.deleted_at !== undefined) {
    // Already soft deleted, idempotent
    return;
  }
  await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.update({
    where: { id: favoriteInquiryId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

