/**
 * Search, filter, and page through coupon templates (shopping_mall_ai_backend_coupon_templates table).
 *
 * Search and retrieve a filtered, paginated list of coupon templates from the system. This operation queries the 'shopping_mall_ai_backend_coupon_templates' table, allowing search by template name, code, type, validity window, enabled status, and other business attributes. The results are paginated and can be sorted by created_at, valid_from, or custom order. Only admin users can search coupon templates. This endpoint is essential for large-scale management of coupon rules, promotions, or compliance checks. Error cases include invalid search conditions or unauthorized user access.
 *
 * @param props - Provider props
 * @param props.admin - The authenticated admin performing the search
 * @param props.body - Search criteria and pagination for coupon templates retrieval
 * @returns Paginated list of coupon template summaries matching search conditions
 * @throws {Error} When query fails or unauthorized
 */
export async function patch__shoppingMallAiBackend_admin_couponTemplates(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendCouponTemplate.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendCouponTemplate.ISummary> {
  const { body } = props;
  const page: number = body.page ?? 1;
  const limit: number = body.limit ?? 20;
  const skip = (page - 1) * limit;

  const where = {
    deleted_at: null,
    ...(body.code && { code: { contains: body.code, mode: 'insensitive' as const } }),
    ...(body.name && { name: { contains: body.name, mode: 'insensitive' as const } }),
    ...(body.type && { type: body.type }),
    ...(body.is_active !== undefined && { is_active: body.is_active }),
    ...((body.valid_from_min !== undefined || body.valid_from_max !== undefined)
      ? {
        valid_from: {
          ...(body.valid_from_min !== undefined && { gte: body.valid_from_min }),
          ...(body.valid_from_max !== undefined && { lte: body.valid_from_max }),
        }
      }
      : {}),
    ...((body.valid_until_min !== undefined || body.valid_until_max !== undefined)
      ? {
        valid_until: {
          ...(body.valid_until_min !== undefined && { gte: body.valid_until_min }),
          ...(body.valid_until_max !== undefined && { lte: body.valid_until_max }),
        }
      }
      : {}),
  };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_coupon_templates.findMany({
      where,
      orderBy: { created_at: 'desc' },
      skip,
      take: limit,
      select: {
        id: true,
        code: true,
        name: true,
        type: true,
        valid_from: true,
        valid_until: true,
        is_active: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_coupon_templates.count({ where }),
  ]);

  return {
    pagination: {
      current: page as number & tags.Type<'int32'>,
      limit: limit as number & tags.Type<'int32'>,
      records: total as number & tags.Type<'int32'>,
      pages: Math.ceil(total / limit) as number & tags.Type<'int32'>,
    },
    data: data.map(row => ({
      id: row.id,
      code: row.code,
      name: row.name,
      type: row.type,
      valid_from: toISOStringSafe(row.valid_from),
      valid_until: toISOStringSafe(row.valid_until),
      is_active: row.is_active,
    })),
  };
}

