/**
 * Performs a soft delete of a business rule or policy identified by UUID. Entry remains in audit trail/table but is excluded from active use and future audit reports. Only 'admin' users may call this endpoint and all deletions are audit-logged. Any attempt to delete a non-existent or protected rule returns a specific error. Used during policy deprecation, legacy constraint cleanup, or regulatory revision cycles.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the soft deletion
 * @param props.businessRuleId - The UUID of the business rule to soft delete
 * @returns void
 * @throws {Error} When the rule does not exist, or is already retired/obsolete, or is protected
 */
export async function delete__shoppingMallAiBackend_admin_businessRules_$businessRuleId(props: {
  admin: AdminPayload;
  businessRuleId: string & tags.Format<'uuid'>;
}): Promise<void> {
  const { admin, businessRuleId } = props;

  // Fetch current rule for validation
  const rule = await MyGlobal.prisma.shopping_mall_ai_backend_business_rules.findFirst({
    where: { id: businessRuleId },
  });
  if (!rule) {
    throw new Error('Business rule not found');
  }
  if (rule.enforcement_status === 'retired' || rule.enforcement_status === 'obsolete') {
    throw new Error('Cannot delete: protected or already retired/obsolete rule');
