  // Soft delete: update status to 'retired', bump updated_at
  await MyGlobal.prisma.shopping_mall_ai_backend_business_rules.update({
    where: { id: businessRuleId },
    data: {
      enforcement_status: 'retired',
      updated_at: toISOStringSafe(new Date()),
