    data: {
      id: v4() as string & tags.Format<'uuid'>,
      action_type: 'soft_delete',
      actor_id: admin.id,
      actor_type: 'admin',
      target_type: 'business_rule',
      target_id: businessRuleId,
      description: `Business rule soft-deleted (retired) by admin ${admin.id}`,
      occurred_at: toISOStringSafe(new Date()),
      audit_payload: null,
    },
  });
}

