import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendAdmin";
import { IPageIShoppingMallAiBackendAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendAdmin";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * 검색/필터/Pagination을 통해 관리자(쇼핑몰 백엔드 운영자) 계정 목록을 반환합니다.
 *
 * 본 엔드포인트는 관리자 탐색, 감시, 권한 감사 등의 용도에 사용됩니다. 이메일, 이름, 역할, 상태, 가입일 등으로 필터링이 가능하며 페이징이 지원됩니다. 패스워드 해시는 포함하지 않습니다. 오직 활성 상태의 관리자만 접근할 수 있습니다.
 *
 * @param props - 요청 속성
 * @param props.admin - 인증된 관리자 (AdminAuth 데코레이터에 의해 주입됨)
 * @param props.body - 관리자 검색 및 필터 파라미터
 * @returns 필터링된 관리자 요약 목록(페이지네이션 포함)
 * @throws {Error} 인증 실패 또는 접근 권한이 없을 때
 */
export async function patch__shoppingMallAiBackend_admin_admins(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendAdmin.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendAdmin.ISummary> {
  const { admin, body } = props;

  // 인증: 활성 관리자만
  const adminRecord = await MyGlobal.prisma.shopping_mall_ai_backend_admins.findFirst({
    where: { id: admin.id, deleted_at: null, status: 'active' },
  });
  if (!adminRecord) throw new Error('Unauthorized: Only active admins can access this endpoint.');

  // 동적 where 조건 생성
  const where = {
    deleted_at: null,
    ...(body.email !== undefined && body.email !== null && {
      email: { contains: body.email, mode: 'insensitive' as const }
    }),
    ...(body.name !== undefined && body.name !== null && {
      name: { contains: body.name, mode: 'insensitive' as const }
    }),
    ...(body.role !== undefined && body.role !== null && { role: body.role }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...((body.joined_from !== undefined && body.joined_from !== null) ||
       (body.joined_to !== undefined && body.joined_to !== null)
      ? {
          joined_at: {
            ...(body.joined_from !== undefined && body.joined_from !== null && { gte: body.joined_from }),
            ...(body.joined_to !== undefined && body.joined_to !== null && { lte: body.joined_to })
          }
        }
      : {}),
  };

  // Pagination Default
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 실제 DB 조회 및 전체 개수 조회
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_admins.findMany({
      where,
      orderBy: { created_at: 'desc' },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_admins.count({ where })
  ]);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: records.map((r) => ({
      id: r.id,
      email: r.email,
      name: r.name,
      role: r.role,
      status: r.status,
      joined_at: toISOStringSafe(r.joined_at),
      created_at: toISOStringSafe(r.created_at),
      updated_at: toISOStringSafe(r.updated_at),
      deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
    })),
  };
}

