/**
 * Advanced list and search order groups with filter, pagination, sorting.
 *
 * Allows sellers to search and list order groups that contain their orders/products. Only sellers with legitimate access will see results. Supports filter by group name, external reference, creation date range, and sort. Returns paginated result.
 *
 * @param props - The operation props.
 * @param props.seller - Authenticated seller's payload (access is required and checked).
 * @param props.body - The advanced filter/search parameters for order groups.
 * @returns Paginated set of order groups matching the seller's access and search parameters.
 * @throws {Error} If seller is not authorized or no records are found (empty data is returned, not error).
 */
export async function patch__shoppingMallAiBackend_seller_orderGroups(
  props: { seller: SellerPayload; body: IShoppingMallAiBackendOrderGroup.IRequest }
): Promise<IPageIShoppingMallAiBackendOrderGroup> {
  const { seller, body } = props;
  const page = body.page && body.page > 0 ? body.page : 1;
  const pageSize = body.pageSize && body.pageSize > 0 && body.pageSize <= 100 ? body.pageSize : 20;

  // Find relevant order group IDs by traversing orders and their items with this seller's products
  const relevantOrderGroupsRaw = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findMany({
    where: {
      deleted_at: null,
      shopping_mall_ai_backend_order_items: {
        some: {
          product: {
            seller_id: seller.id,
          },
        },
      },
    },
    select: {
      order_group_id: true,
    },
    distinct: ['order_group_id'],
  });

  // Extract unique, non-null group IDs
  const groupIdList = relevantOrderGroupsRaw
    .map(r => r.order_group_id)
    .filter((id): id is string & tags.Format<'uuid'> => !!id);

  // Build order group filters
  const filters = {
    deleted_at: null,
    ...(body.group_name && { group_name: { contains: body.group_name, mode: 'insensitive' as const } }),
    ...(body.external_reference && { external_reference: body.external_reference }),
    ...((body.created_at_gte || body.created_at_lte) && {
      created_at: {
        ...(body.created_at_gte && { gte: body.created_at_gte }),
        ...(body.created_at_lte && { lte: body.created_at_lte }),
      },
    }),
    ...(groupIdList.length > 0 && { id: { in: groupIdList } }),
  };

  // Determine sorting field and direction
  let sortField = 'created_at';
  let sortOrder: 'asc' | 'desc' = 'desc';
  if (body.sort && typeof body.sort === 'string' && body.sort.length > 0) {
    if (body.sort.startsWith('-')) {
      sortField = body.sort.slice(1);
      sortOrder = 'desc';
    } else {
      sortField = body.sort;
      sortOrder = 'asc';
    }
  }

  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_order_groups.findMany({
      where: filters,
      orderBy: { [sortField]: sortOrder },
      skip: (page - 1) * pageSize,
      take: pageSize,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_order_groups.count({
      where: filters,
    }),
  ]);

  // Normalize date fields to string & tags.Format<'date-time'>
  const data: IShoppingMallAiBackendOrderGroup[] = rows.map(r => ({
    id: r.id,
    group_name: r.group_name,
    external_reference: r.external_reference ?? null,
    meta_info: r.meta_info ?? null,
    created_at: toISOStringSafe(r.created_at),
    updated_at: toISOStringSafe(r.updated_at),
    deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data,
  };
}

