  body: IShoppingMallAiBackendChannel.IRequest;
}): Promise<IPageIShoppingMallAiBackendChannel.ISummary> {
  const { admin, body } = props;

  // RBAC: Presence of admin param (payload) implies authorization is enforced by controller/decorator.
  // Additional compliance checks could be implemented here if needed.

  // Pagination config with safe defaults
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit = typeof body.limit === "number" && body.limit > 0 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Flexible filter construction (exclude soft-deleted by default)
  const where = {
    deleted_at: null,
    ...(body.code !== undefined && body.code !== null && {
      code: { contains: body.code, mode: "insensitive" as const },
