/**
 * Retrieves a paginated, filtered list of product bundles for a given product (admin only).
 *
 * Only system administrators are allowed to access this endpoint, as enforced by the AdminAuth decorator.
 * Returns paged and filtered bundle summaries using various search criteria, supporting catalog management use cases.
 *
 * @param props -
 *   @field admin: The authenticated AdminPayload user for authorization
 *   @field productId: The parent product UUID to search bundles for
 *   @field body: Filter/search options for product bundles, including substring/code/name/status/policy/date filters, paging, and sorting
 * @returns Paginated summary ({ pagination, data[] }) of product bundles matching filters and productId
 * @throws {Error} If the product is not found or has been deleted
 */
export async function patch__shoppingMallAiBackend_admin_products_$productId_productBundles(props: {
  admin: AdminPayload;
  productId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendProductBundle.IRequest;
}): Promise<IPageIShoppingMallAiBackendProductBundle.ISummary> {
  const { admin, productId, body } = props;

  // 1. Check product exists (throw if not found/deleted)
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: { id: productId, deleted_at: null },
    select: { id: true },
  });
  if (!product) throw new Error('Product not found');

  // 2. Build dynamic where clause
  const where = {
    main_product_id: productId,
    deleted_at: null,
    ...(body.code && { code: { contains: body.code, mode: "insensitive" as const } }),
    ...(body.name && { name: { contains: body.name, mode: "insensitive" as const } }),
    ...(body.status && { status: body.status }),
    ...(body.bundle_policy && { bundle_policy: body.bundle_policy }),
    ...((body.created_at_min || body.created_at_max) && {
      created_at: {
        ...(body.created_at_min && { gte: body.created_at_min }),
        ...(body.created_at_max && { lte: body.created_at_max }),
      },
    }),
  };
  // 3. Page, limit, sorting
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;
  const order_by = body.order_by ?? "created_at";
  const order_direction = body.order_direction === "asc" ? "asc" : "desc";

  // 4. Query bundles and count
  const [bundles, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_bundles.findMany({
      where,
      orderBy: { [order_by]: order_direction },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_bundles.count({ where }),
  ]);

  // 5. Build paginated summary response
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: bundles.map((b) => ({
      id: b.id,
      main_product_id: b.main_product_id,
      name: b.name,
      status: b.status,
      created_at: toISOStringSafe(b.created_at),
      updated_at: toISOStringSafe(b.updated_at),
    })),
  };
}

