import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Update an existing order in the order table (customer-owned).
 *
 * Update order properties for an existing order using its identifier. Only fields permitted by business logic and schema (such as status, note, or custom fields) are updated. Provides full audit trail and verification of actor identity.
 *
 * This endpoint is used for workflow changes (e.g., status update from pending to paid, or marking as canceled), and updates are strictly validated. Unauthorized or invalid updates result in standardized error messages. Order modifications are evidenced in history logs and flag potential conflicts or rejected changes when business constraints are violated.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer payload (must match order owner)
 * @param props.orderId - The UUID of the order to update (path parameter)
 * @param props.body - The allowed update fields; currently only status and note
 * @returns The updated order entity, fully populated
 * @throws {Error} When the order does not exist, does not belong to the customer, or has been soft-deleted
 */
export async function put__shoppingMallAiBackend_customer_orders_$orderId(
  props: {
    customer: CustomerPayload,
    orderId: string & tags.Format<'uuid'>,
    body: IShoppingMallAiBackendOrder.IUpdate
  }
): Promise<IShoppingMallAiBackendOrder> {
  const { customer, orderId, body } = props;

  // 1. Fetch the order belonging to this customer and that is not deleted
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findFirst({
    where: {
      id: orderId,
      customer_id: customer.id,
      deleted_at: null,
    },
  });
  if (!existing) {
    throw new Error("Order not found, forbidden, or has been deleted");
  }

  // 2. Update only permitted fields + updated_at
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_orders.update({
    where: { id: orderId },
    data: {
      current_status: body.current_status ?? undefined,
      note: body.note ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // 3. Return all fields, date fields converted properly, optionals handled
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    order_group_id: updated.order_group_id ?? null,
    order_number: updated.order_number,
    current_status: updated.current_status,
    total_amount: updated.total_amount,
    currency_code: updated.currency_code,
    note: updated.note ?? null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProduct";
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Register a new product in the platform (shopping_mall_ai_backend_products).
 *
 * Creates a new product for an authenticated seller in the B2B shopping mall backend. Enforces proper seller authentication, enforces unique product code (SKU) at business and DB level, and handles all required and optional fields with correct types. Returns the newly created product with all business fields. Throws errors for duplicate code, seller mismatch, or dependency issues.
 *
 * @param props - Request properties
 * @param props.seller - SellerPayload (authenticated seller, must match seller_id in body)
 * @param props.body - Product registration details (see IShoppingMallAiBackendProduct.ICreate)
 * @returns Newly registered product in canonical business DTO structure
 * @throws {Error} When seller_id does not match authenticated user
 * @throws {Error} When product code is duplicated for an active product
 */
export async function post__shoppingMallAiBackend_seller_products(
  props: {
    seller: SellerPayload;
    body: IShoppingMallAiBackendProduct.ICreate;
  }
): Promise<IShoppingMallAiBackendProduct> {
  const { seller, body } = props;

  // 권한 확인: 본인 seller만 등록 가능
  if (body.seller_id !== seller.id) {
    throw new Error("Unauthorized: You can only register products for your own seller account.");
  }

  // 상품 코드 중복 확인 (deleted_at == null인 경우만 중복 취급)
  const found = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      code: body.code,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (found) {
    throw new Error("Duplicate product code: The provided code is already in use by an active product.");
  }

  // 타임스탬프 생성 (ISO8601)
  const now = toISOStringSafe(new Date());

  // 상품 등록
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_products.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      seller_id: seller.id,
      code: body.code,
      name: body.name,
      description: body.description ?? null,
      main_image_uri: body.main_image_uri ?? null,
      status: body.status,
      created_at: now,
      updated_at: now,
      // deleted_at omitted (null)
    },
  });

  // 결과 매핑 (날짜 및 UUID 브랜드 적용)
  return {
    id: created.id as string & tags.Format<'uuid'>,
    seller_id: created.seller_id as string & tags.Format<'uuid'>,
    code: created.code,
    name: created.name,
    description: created.description ?? null,
    main_image_uri: created.main_image_uri ?? null,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

