/**
 * Retrieves a single customer history event by customer ID and history ID, enforcing authorization rules.
 *
 * Access is restricted to the owner customer. Only history records matching the authenticated customer's ID are accessible.
 * Hard-deleted (soft-deleted) records are not a concern for the history entity (no deleted_at on this model),
 * but parent customer must exist and must not be deleted (checked by global authentication).
 *
 * @param props -
 *   - customer: Authenticated CustomerPayload.
 *   - customerId: UUID of the customer whose history is being accessed.
 *   - historyId: UUID of the target history event.
 * @returns Full details of the requested customer history event (IShoppingMallAiBackendCustomerHistory)
 * @throws {Error} When unauthorized or if no such history record exists.
 */
export async function get__shoppingMallAiBackend_customer_customers_$customerId_histories_$historyId(
  props: {
    customer: CustomerPayload;
    customerId: string & tags.Format<'uuid'>;
    historyId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendCustomerHistory> {
  const { customer, customerId, historyId } = props;

  // Authorization: Only allow the owner customer
  if (customerId !== customer.id) {
    throw new Error('Unauthorized: You may only access your own history events.');
  }

  // Lookup the history record
  const history = await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.findFirst({
