    old_value_json: history.old_value_json ?? null,
    new_value_json: history.new_value_json ?? null,
    triggered_by: history.triggered_by,
    meta_json: history.meta_json ?? null,
    occurred_at: toISOStringSafe(history.occurred_at),
    created_at: toISOStringSafe(history.created_at),
  };
}

