 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user performing this operation
 * @param props.appealId - UUID of the appeal record to erase
 * @returns void
 * @throws {Error} When the appeal does not exist, is already deleted, or admin lacks authorization
 */
export async function delete__shoppingMallAiBackend_admin_appeals_$appealId(
  props: { admin: AdminPayload; appealId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { admin, appealId } = props;

