/**
 * Soft-delete a channel by its UUID (admin only, compliance retention).
 *
 * Soft-deletes a channel record by setting deleted_at to the current timestamp for compliance traceability. Only admins may perform this action.
 * Logically deleted channels are hidden from standard searches, while audit operations may still access them.
 * Calls to erase an already-deleted or non-existent channel return appropriate errors.
 * Deletion is RBAC controlled and logged for business regulatory compliance.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user (must have type 'admin')
 * @param props.channelId - Channel UUID to soft-delete
 * @returns void
 * @throws {Error} If channel does not exist or is already deleted
 */
export async function delete__shoppingMallAiBackend_admin_channels_$channelId(
  props: {
    admin: AdminPayload;
    channelId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { admin, channelId } = props;

  // RBAC: Admin authentication is already enforced by the decorator/middleware
  if (!admin || admin.type !== 'admin') {
    throw new Error('Unauthorized: admin privileges required');
  }

  // Fetch channel (must exist and not be already deleted)
  const channel = await MyGlobal.prisma.shopping_mall_ai_backend_channels.findFirst({
    where: { id: channelId, deleted_at: null },
    select: { id: true },
  });
  if (!channel) {
    throw new Error('Channel not found or already deleted');
  }

  // Soft-delete: set deleted_at to now
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_channels.update({
    where: { id: channelId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });
  // No return value (void)
}

