/**
 * Retrieve a specific product-to-channel mapping for a product as an authenticated seller.
 *
 * Ensures the current seller is the owner of the mapped product. Returns the product-channel mapping record including status, and compliance info. Throws 404 if mapping not found or soft-deleted, 403 if the authenticated seller is not owner.
 *
 * @param props - The request properties
 * @param props.seller - The authenticated seller's payload
 * @param props.productId - UUID of the target product whose channel mapping is being retrieved
 * @param props.productChannelMapId - UUID of the productChannelMap mapping record to fetch
 * @returns The product-channel mapping record as per DTO
 * @throws {Error} 404 if not found, 403 if forbidden (not owner)
 */
export async function get__shoppingMallAiBackend_seller_products_$productId_productChannelMap_$productChannelMapId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productChannelMapId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendProductChannelMap> {
  const { seller, productId, productChannelMapId } = props;

  const mapping = await MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.findFirst({
    where: {
      id: productChannelMapId,
      product_id: productId,
      deleted_at: null,
    },
  });
  if (!mapping) throw new Error("Not found");

  // Authorization: Ownership check
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: mapping.product_id,
    },
  });
  if (!product) throw new Error("Product missing");
  if (product.seller_id !== seller.id) throw new Error("Forbidden");

  return {
    id: mapping.id,
    product_id: mapping.product_id,
    channel_id: mapping.channel_id,
    status: mapping.status,
    created_at: toISOStringSafe(mapping.created_at),
    updated_at: toISOStringSafe(mapping.updated_at),
  };
}

