 *
 * Create a new immutable product snapshot associated with a given product. Used for forensic, rollback, compliance, or analytical restoration scenarios. Captures the business-relevant fields for the product as of the current change, and persists this as an evidence record in the product's lifecycle. Only sellers who own the product or system admins can create product snapshots. Fails with 400 on invalid data, 404 if product not found, 403 if unauthorized.
 *
 * @param props - Request parameters
 * @param props.seller - The authenticated seller attempting to create the product snapshot.
 * @param props.productId - UUID of the product to be snapshotted.
 * @param props.body - The payload with snapshot code, type, and product evidence fields.
 * @returns The created product snapshot with all compliance fields.
 * @throws {Error} 403 if unauthorized or ownership validation fails
 * @throws {Error} 404 if the product does not exist
 */
export async function post__shoppingMallAiBackend_seller_products_$productId_productSnapshots(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductSnapshot.ICreate;
  }
): Promise<IShoppingMallAiBackendProductSnapshot> {
  const { seller, productId, body } = props;

  // Step 1: Ensure the product exists and is owned by the seller (and not deleted)
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
