      snapshot_type: body.snapshot_type,
      name: body.name,
      description: body.description ?? null,
      main_image_uri: body.main_image_uri ?? null,
      status: body.status,
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Step 3: Return DTO-conformant result (brand created_at)
  return {
    id: created.id,
    product_id: created.product_id,
    snapshot_code: created.snapshot_code,
    snapshot_type: created.snapshot_type,
    name: created.name,
    description: created.description,
    main_image_uri: created.main_image_uri,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
  };
}

