/**
 * Creates a new shopping cart record for an authenticated customer.
 *
 * This endpoint creates and returns a new shopping cart for the authenticated customer. It guarantees that only one active cart exists for any customer at a time. Attempts to create a duplicate active cart result in an error. All created cart fields are fully typed and generated with proper UUID and ISO date-time branding, with no use of the native Date type anywhere.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer user, providing the customer ID for cart linkage
 * @param props.body - Cart creation data (status and optional session_token)
 * @returns The complete cart record, matching IShoppingMallAiBackendCart type
 * @throws {Error} If this customer already has an active cart
 */
export async function post__shoppingMallAiBackend_customer_carts(
  props: { customer: CustomerPayload; body: IShoppingMallAiBackendCart.ICreate }
): Promise<IShoppingMallAiBackendCart> {
  const { customer, body } = props;

  // 1. Check for existing active (undeleted) cart for this customer
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_carts.findFirst({
    where: {
      customer_id: customer.id,
      deleted_at: null,
      status: 'active',
    },
  });
  if (existing) {
    throw new Error('Active cart already exists for this customer');
  }

  // 2. Generate a new cart ID and timestamps
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_carts.create({
    data: {
      id: v4(),
      customer_id: customer.id,
      session_token: body.session_token ?? null,
      status: body.status,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 3. Return the newly created cart, mapping all fields as required by the DTO and types
  return {
    id: created.id,
    session_token: created.session_token ?? null,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

