 * Admin authentication is enforced by the controller.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin payload
 * @param props.body - Search and pagination criteria for coupon snapshots
 * @returns Paginated result set of coupon snapshot summaries
 * @throws {Error} When database access fails or invalid filters are provided
 */
export async function patch__shoppingMallAiBackend_admin_couponSnapshots(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendCouponSnapshot.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendCouponSnapshot.ISummary> {
  const { body } = props;
  // Defensive guarantees for pagination
  const page = body.page >= 1 ? body.page : 1;
  const limit = body.limit >= 1 ? body.limit : 20;
  // Build Prisma filter object using only allowed fields, handling undefined/null
  const where = {
    ...(body.issued_coupon_id !== undefined && body.issued_coupon_id !== null && {
      issued_coupon_id: body.issued_coupon_id,
    }),
    ...(body.customer_id !== undefined && body.customer_id !== null && {
      customer_id: body.customer_id,
    }),
    ...(body.status !== undefined && body.status !== null && {
      status: body.status,
    }),
    ...(body.coupon_template_code !== undefined && body.coupon_template_code !== null && {
      coupon_template_code: body.coupon_template_code,
    }),
    ...((body.created_at_from || body.created_at_to)
      ? {
          created_at: {
            ...(body.created_at_from && { gte: body.created_at_from }),
            ...(body.created_at_to && { lte: body.created_at_to }),
          },
        }
      : {}),
  };
  // Query for data and count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_coupon_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_coupon_snapshots.count({ where }),
  ]);
  // Map results and convert all date fields
  const data = rows.map((row) => ({
    id: row.id,
    issued_coupon_id: row.issued_coupon_id,
    coupon_template_code: row.coupon_template_code,
    issued_coupon_code: row.issued_coupon_code,
    customer_id: row.customer_id,
    status: row.status,
    valid_from: toISOStringSafe(row.valid_from),
    valid_until: toISOStringSafe(row.valid_until),
    action: row.action,
    created_at: toISOStringSafe(row.created_at),
  }));
  // Compose correct pagination info
  const pages = Math.max(1, Math.ceil(total / limit));
  const pagination = {
    current: page,
    limit,
    records: total,
    pages,
  };
  return { pagination, data };
}

