 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing this operation
 * @param props.body - Product business data/attributes for registration (IShoppingMallAiBackendProduct.ICreate)
 * @returns The newly created product as it will appear in the business catalog (IShoppingMallAiBackendProduct)
 * @throws {Error} If the product code is not unique, or the seller does not exist or has been deleted.
 */
export async function post__shoppingMallAiBackend_admin_products(props: {
  admin: AdminPayload;
  body: IShoppingMallAiBackendProduct.ICreate;
}): Promise<IShoppingMallAiBackendProduct> {
