/**
 * Creates a new status history for an order (OrderStatusHistories table).
 *
 * This function allows a seller to record a workflow status change event for one of their orders. It verifies the seller's ownership over at least one product in the target order, ensures the order exists and is not deleted, and writes a compliance/audit history record with all required context.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the action
 * @param props.orderId - The UUID of the order for which a status history is being created
 * @param props.body - Information for creating a new order status history event
 * @returns The created IShoppingMallAiBackendOrderStatusHistory record (id, order_id, previous_status, new_status, actor_type, actor_id, event_context, occurred_at)
 * @throws {Error} If the order does not exist, is deleted, or the seller does not own any of its products
 */
export async function post__shoppingMallAiBackend_seller_orders_$orderId_orderStatusHistories(props: {
  seller: SellerPayload;
  orderId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendOrderStatusHistory.ICreate;
}): Promise<IShoppingMallAiBackendOrderStatusHistory> {
  const { seller, orderId, body } = props;

  // 1. Fetch order by id and make sure it's not deleted
  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findFirst({
    where: { id: orderId, deleted_at: null },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found or already deleted");

  // 2. Confirm the seller owns at least one product in this order (multi-seller allowed)
  const orderItems = await MyGlobal.prisma.shopping_mall_ai_backend_order_items.findMany({
    where: { order_id: orderId },
    select: { product: { select: { seller_id: true } } },
  });
  if (
    orderItems.length === 0 ||
    !orderItems.some(item => item.product.seller_id === seller.id)
  ) {
    throw new Error("Unauthorized: Seller does not own any items in this order");
  }

  // 3. Create the status history entry for this order
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_order_status_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      order_id: orderId,
      previous_status: body.previous_status,
      new_status: body.new_status,
      actor_type: body.actor_type,
      actor_id: body.actor_id,
      event_context: body.event_context ?? null,
      occurred_at: body.occurred_at,
    },
  });

  return {
    id: created.id,
    order_id: created.order_id,
    previous_status: created.previous_status,
    new_status: created.new_status,
    actor_type: created.actor_type,
    actor_id: created.actor_id,
    event_context: created.event_context ?? null,
    occurred_at: toISOStringSafe(created.occurred_at),
  };
}

