 *
 * @param props - Encapsulates seller authentication, product ID, and tag creation data
 * @param props.seller - The authenticated seller (SellerPayload)
 * @param props.productId - The UUID of the product to tag
 * @param props.body - IShoppingMallAiBackendProductTag.ICreate input DTO
 * @returns IShoppingMallAiBackendProductTag - The newly created product tag
 * @throws {Error} If:
 *   - The path productId does not match the body.product_id
 *   - The product does not exist, is soft-deleted, or is not owned by this seller
 *   - The tag already exists for the product (duplicate not allowed)
 */
export async function post__shoppingMallAiBackend_seller_products_$productId_productTags(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductTag.ICreate;
  }
): Promise<IShoppingMallAiBackendProductTag> {
  const { seller, productId, body } = props;
  // Ensure productId matches body.product_id
  if (productId !== body.product_id) {
    throw new Error("Path productId does not match body.product_id");
  }
  // Check product existence, ownership, and non-deleted status
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: productId,
      seller_id: seller.id,
      deleted_at: null,
