  }
  // Create tag
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_product_tags.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      product_id: productId,
      tag: body.tag,
    },
  });
  return {
