import { IShoppingMallAiBackendProductOption } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductOption";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Creates a new product option associated with an existing product.
 *
 * This endpoint enables admins to add a product option (variant) such as size or color to a 
 * specific product. The parent product must exist and not be soft deleted. If the SKU is not unique
 * to this product, the request will fail. All business fields and timestamps are populated automatically.
 *
 * @param props - The request object
 * @param props.admin - Authenticated admin payload (must be a valid, active admin)
 * @param props.productId - UUID of the parent product (must exist and not be soft-deleted)
 * @param props.body - The creation input for the new product option
 * @returns The newly created product option (all data fields populated)
 * @throws {Error} If parent product does not exist or is deleted
 * @throws {Error} If SKU is not unique or other database constraint is violated
 */
export async function post__shoppingMallAiBackend_admin_products_$productId_productOptions(props: {
    admin: AdminPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductOption.ICreate;
}): Promise<IShoppingMallAiBackendProductOption> {
    const { admin, productId, body } = props;

    // 1. Ensure parent product exists and is not soft-deleted
    const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
        where: {
            id: productId,
            deleted_at: null
        }
    });
    if (!product) {
        throw new Error("Parent product does not exist or is deleted");
    }

    // 2. Create and insert new option row
    let created;
    try {
        created = await MyGlobal.prisma.shopping_mall_ai_backend_product_options.create({
            data: {
                id: v4() as string & tags.Format<'uuid'>,
                product_id: productId,
                sku: body.sku,
                option_name: body.option_name,
                option_values: body.option_values ?? null,
                extra_price: body.extra_price ?? null,
                main_image_uri: body.main_image_uri ?? null,
                status: body.status,
                created_at: toISOStringSafe(new Date()),
                updated_at: toISOStringSafe(new Date())
            }
        });
    } catch (error) {
        // Unique constraint on SKU will fail here, provide meaningful error
        if (
            error instanceof Prisma.PrismaClientKnownRequestError &&
            error.code === 'P2002' &&
            (error.meta?.target as string[] | undefined)?.includes('sku')
        ) {
            throw new Error('A product option with this SKU already exists');
        }
        throw error;
    }
    return {
        id: created.id,
        product_id: created.product_id,
        sku: created.sku,
        option_name: created.option_name,
        option_values: created.option_values,
        extra_price: created.extra_price,
        main_image_uri: created.main_image_uri,
        status: created.status,
        created_at: toISOStringSafe(created.created_at),
        updated_at: toISOStringSafe(created.updated_at),
        deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
    };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Soft-delete a product (mark as deleted) belonging to the authenticated seller.
 *
 * Sets deleted_at and updated_at fields, enforcing that only the owner seller can delete their product.
 * Throws if product does not exist, is already deleted, or ownership fails.
 *
 * @param props - Request parameters
 * @param props.seller - The authenticated seller performing the soft-delete
 * @param props.productId - UUID of the product to soft-delete
 * @returns void
 * @throws {Error} When the product does not exist or is already deleted
 * @throws {Error} When the seller does not own the product (forbidden)
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId(props: {
  seller: SellerPayload;
  productId: string & tags.Format<'uuid'>;
}): Promise<void> {
  const { seller, productId } = props;

  // 1. Fetch the product, ensure it's not deleted
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: productId,
      deleted_at: null,
    },
    select: {
      seller_id: true,
      id: true,
    },
  });
  if (!product)
    throw new Error("Product not found or already deleted");
  if (product.seller_id !== seller.id)
    throw new Error("Forbidden: Only the owner seller can delete this product");

  // 2. Soft-delete: set deleted_at and updated_at to now (ISO string)
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_products.update({
    where: { id: productId },
    data: {
      deleted_at: now,
      updated_at: now,
    },
  });
}

