/**
 * Creates a new appeal (objection) for a moderation event by a seller.
 *
 * This operation allows a seller to submit a formal objection ('appeal') to a prior moderation event. The seller must match the appellant_id in the request body. Duplicate appeals for the same moderation_event_id and appellant_id are prohibited—an error will be thrown if one exists. All timestamps are formatted as ISO8601 strings with format branding; no Date type is used anywhere. The appeal record is returned in full, with all metadata suitable for immediate retrieval and audit.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller submitting the appeal
 * @param props.body - The appeal creation data matching IShoppingMallAiBackendAppeal.ICreate
 * @returns The newly created appeal record
 * @throws {Error} If the seller does not match the appellant, or if a duplicate appeal exists
 */
export async function post__shoppingMallAiBackend_seller_appeals(
  props: {
    seller: SellerPayload;
    body: IShoppingMallAiBackendAppeal.ICreate;
  }
): Promise<IShoppingMallAiBackendAppeal> {
  const { seller, body } = props;

  // Authorization: Only the authenticated seller may appeal for themself
  if (seller.id !== body.appellant_id) {
    throw new Error("Unauthorized: You may only file appeals as yourself (seller).");
  }

  // Prevent duplicate appeals for the same moderation event by this seller
  const exists = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.findFirst({
    where: {
      moderation_event_id: body.moderation_event_id,
      appellant_id: body.appellant_id,
    }
  });
  if (exists) {
    throw new Error("Conflict: You've already submitted an appeal for this moderation event.");
  }

  // Prepare audit fields
  const now = toISOStringSafe(new Date());

  // Create the appeal
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      moderation_event_id: body.moderation_event_id,
      appellant_id: body.appellant_id,
      status: body.status,
      decision_comment: body.decision_comment ?? null,
      created_at: now,
      updated_at: now,
    }
  });

  // Map result to API type
  return {
    id: created.id,
    moderation_event_id: created.moderation_event_id,
    appellant_id: created.appellant_id,
    status: created.status,
    decision_comment: created.decision_comment,
    created_at: now,
    updated_at: now,
  };
}

