      description: body.description ?? undefined,
      display_order: body.display_order ?? undefined,
      visible: body.visible ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    }
  });

  // 5. Return updated object with strict typing and ISO string dates
  return {
    id: updated.id,
    parent_id: updated.parent_id ?? null,
    created_by_admin_id: updated.created_by_admin_id,
    code: updated.code,
    name: updated.name,
    description: updated.description ?? null,
    display_order: updated.display_order,
    visible: updated.visible,
