      wallet_label: body.wallet_label ?? undefined,
      security_code: body.security_code ?? undefined,
      snapshot_reason: body.snapshot_reason ?? undefined,
    },
  });

  // 5. Return the complete, updated snapshot, converting date fields to ISO string
  return {
    id: updated.id,
    wallet_id: updated.wallet_id,
    owner_customer_id:
      updated.owner_customer_id !== undefined ? updated.owner_customer_id : null,
    owner_seller_id:
