    owner_admin_id:
      updated.owner_admin_id !== undefined ? updated.owner_admin_id : null,
    wallet_type: updated.wallet_type,
    wallet_status: updated.wallet_status,
    wallet_address: updated.wallet_address,
    wallet_label: updated.wallet_label !== undefined ? updated.wallet_label : null,
    security_code: updated.security_code !== undefined ? updated.security_code : null,
    snapshot_balance: updated.snapshot_balance,
