 *
 * @param props - Properties containing authentication (customer), path param (customerId), and request body (filter/search/pagination)
 * @param props.customer - Authenticated customer performing the request (must match path param)
 * @param props.customerId - ID of the customer whose addresses are to be listed (must match authenticated customer)
 * @param props.body - Search and pagination parameters
 * @returns Paginated list of addresses for the customer
 * @throws {Error} If customerId does not match the authenticated customer
 */
export async function patch__shoppingMallAiBackend_customer_customers_$customerId_addresses(
  props: {
    customer: CustomerPayload;
    customerId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendCustomerAddress.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendCustomerAddress> {
  const { customer, customerId, body } = props;

  // Authorization: Only the customer themselves may access their addresses
  if (customer.id !== customerId) {
    throw new Error('Unauthorized: You can only list your own addresses');
  }

  // Pagination defaults (page: 1, limit: 20)
  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;

  // Allowed sort fields
  const allowedSortFields = [
    'created_at', 'updated_at', 'alias', 'receiver_name',
    'receiver_phone', 'postal_code', 'city', 'state', 'country', 'is_primary',
  ];
  const sort_by = body.sort_field && allowedSortFields.includes(body.sort_field)
    ? body.sort_field : 'created_at';
  const sort_dir = body.sort_dir === 'asc' ? 'asc' : 'desc';

  // Build WHERE conditions
  const where = {
    deleted_at: null,
    customer_id: customerId,
    ...(body.alias ? { alias: { contains: body.alias, mode: 'insensitive' as const } } : {}),
    ...(body.receiver_name ? { receiver_name: { contains: body.receiver_name, mode: 'insensitive' as const } } : {}),
    ...(body.receiver_phone ? { receiver_phone: { contains: body.receiver_phone, mode: 'insensitive' as const } } : {}),
    ...(body.postal_code ? { postal_code: { contains: body.postal_code, mode: 'insensitive' as const } } : {}),
    ...(body.address_line1 ? { address_line1: { contains: body.address_line1, mode: 'insensitive' as const } } : {}),
    ...(body.address_line2 ? { address_line2: { contains: body.address_line2, mode: 'insensitive' as const } } : {}),
    ...(body.city ? { city: { contains: body.city, mode: 'insensitive' as const } } : {}),
    ...(body.state ? { state: { contains: body.state, mode: 'insensitive' as const } } : {}),
    ...(body.country ? { country: { contains: body.country, mode: 'insensitive' as const } } : {}),
    ...(body.is_primary !== undefined && body.is_primary !== null ? { is_primary: body.is_primary } : {}),
  };

  // Fetch addresses and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_customer_addresses.findMany({
      where,
      orderBy: { [sort_by]: sort_dir },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_customer_addresses.count({ where }),
  ]);

  // Transform date fields and optional/null handling
  const data = rows.map(addr => ({
    id: addr.id,
    customer_id: addr.customer_id,
    alias: addr.alias ?? null,
    receiver_name: addr.receiver_name,
    receiver_phone: addr.receiver_phone,
    postal_code: addr.postal_code,
