    updated_at: toISOStringSafe(addr.updated_at),
    deleted_at: addr.deleted_at ? toISOStringSafe(addr.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
