/**
 * Delete a favorite notification (hard delete) by favoriteNotificationId.
 *
 * This operation permanently deletes a favorite notification event identified by favoriteNotificationId from the shopping_mall_ai_backend_favorite_notifications table. Only the notification's owner (customer) can perform this action. Ownership is validated by traversing the notification's parent favorite record (product, inquiry, or address). If the notification or favorite parent is not found, or if the authenticated customer does not own the parent favorite, an error is thrown. This performs a hard delete (no soft-delete field exists).
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the deletion (CustomerPayload).
 * @param props.favoriteNotificationId - The UUID of the favorite notification to delete.
 * @returns void
 * @throws {Error} When the notification does not exist.
 * @throws {Error} When the notification is orphaned or not referencing a favorite.
 * @throws {Error} When the authenticated customer does not own the notification.
 */
export async function delete__shoppingMallAiBackend_customer_favoriteNotifications_$favoriteNotificationId(
  props: {
    customer: CustomerPayload;
    favoriteNotificationId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { customer, favoriteNotificationId } = props;

  // 1. Fetch the notification record
  const notification = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.findUnique({
    where: { id: favoriteNotificationId },
    select: {
      favorite_product_id: true,
      favorite_inquiry_id: true,
      favorite_address_id: true,
    },
  });
  if (!notification) {
    throw new Error("Favorite notification not found");
  }

  // 2. Determine favorite type and fetch parent favorite record
  let favoriteRecord: { customer_id: string & tags.Format<'uuid'> } | null = null;
  if (notification.favorite_product_id) {
    favoriteRecord = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findUnique({
      where: { id: notification.favorite_product_id },
      select: { customer_id: true },
    });
  } else if (notification.favorite_inquiry_id) {
    favoriteRecord = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findUnique({
      where: { id: notification.favorite_inquiry_id },
      select: { customer_id: true },
    });
  } else if (notification.favorite_address_id) {
    favoriteRecord = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findUnique({
      where: { id: notification.favorite_address_id },
      select: { customer_id: true },
    });
  } else {
    throw new Error("Notification is orphaned: no parent favorite reference");
  }
  if (!favoriteRecord) {
    throw new Error("Favorite parent record not found");
  }
  if (favoriteRecord.customer_id !== customer.id) {
    throw new Error("Forbidden: customer does not own this notification");
  }

  // 3. Hard delete the notification
  await MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.delete({
    where: { id: favoriteNotificationId },
  });
}

