/**
 * Get a specific review snapshot for a product review (IShoppingMallAiBackendReviewSnapshot).
 *
 * Fetches the full details of a specific snapshot resource for a product review, including ratings, statuses, actors, AI scores, and all review content as it existed at that snapshot event. Access is security-controlled by role and review ownership.
 *
 * This operation is essential for forensic trace, business continuity, and full compliance evidence practices. Related to temporal audit, dispute management, and major site history features. Errors include not found, unauthorized, or compliance-locked snapshot access.
 *
 * @param props - The request parameters
 * @param props.seller - The authenticated seller performing this operation; will only succeed if the seller owns the product of the review being queried.
 * @param props.productReviewId - The UUID of the product review that owns this snapshot.
 * @param props.reviewSnapshotId - The UUID of the review snapshot to fetch.
 * @returns The complete immutable review snapshot as it existed at the saved event.
 * @throws {Error} When the review snapshot is not found, linkage is invalid, the product does not exist, or the seller does not own that product.
 */
export async function get__shoppingMallAiBackend_seller_productReviews_$productReviewId_reviewSnapshots_$reviewSnapshotId(props: {
  seller: SellerPayload;
  productReviewId: string & tags.Format<'uuid'>;
  reviewSnapshotId: string & tags.Format<'uuid'>;
}): Promise<IShoppingMallAiBackendReviewSnapshot> {
  const { seller, productReviewId, reviewSnapshotId } = props;

  // 1. Fetch the review snapshot by id
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_review_snapshots.findUnique({
    where: { id: reviewSnapshotId },
  });
  if (!snapshot) throw new Error("Review snapshot not found");

  // 2. Validate the snapshot links to the correct review
  if (snapshot.review_id !== productReviewId) {
    throw new Error("Snapshot does not belong to the specified product review");
  }

  // 3. Fetch parent review and confirm it exists
  const review = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findUnique({
    where: { id: snapshot.review_id },
  });
  if (!review) throw new Error("Parent review not found");

  // 4. Fetch product for ownership check
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: review.product_id },
  });
  if (!product) throw new Error("Product not found");

  // 5. Check seller ownership
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: Seller does not own the product for this review snapshot");
  }

  // 6. Return API DTO with proper Date conversion
  return {
    id: snapshot.id,
    review_id: snapshot.review_id,
    body: snapshot.body,
    rating: snapshot.rating,
    status: snapshot.status,
    actor_id: snapshot.actor_id,
    ai_sentiment_score: snapshot.ai_sentiment_score ?? null,
    ai_spam_score: snapshot.ai_spam_score ?? null,
    changed_at: toISOStringSafe(snapshot.changed_at),
  };
}

