    state: body.state ?? undefined,
    country: body.country ?? undefined,
    is_primary: body.is_primary ?? undefined,
    alias: body.alias ?? undefined,
    updated_at: now,
  };

  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_customer_addresses.update({
    where: { id: body.id },
    data: updateData,
  });

  return {
    id: updated.id,
    customer_id: updated.customer_id,
    alias: updated.alias ?? null,
    receiver_name: updated.receiver_name,
