/**
 * Search/list appeals to moderation events, filterable and paginated.
 *
 * Search appeals against moderation events by various criteria including status, appellant_id, decision_comment, date created, etc. Applies policy for privacy, result visibility, and audit-trail completeness. Supports paginated result sets and compliance export if needed. Only authorized staff may list appeals with full details.
 *
 * @param props - The function parameter object
 * @param props.admin - Authenticated admin payload injected via AdminAuth decorator. Must be validated and active.
 * @param props.body - Search and filter criteria for appeals, conforming to IShoppingMallAiBackendAppeal.IRequest.
 * @returns Paginated list of appeals matching the search criteria, as IPageIShoppingMallAiBackendAppeal.ISummary
 * @throws {Error} If database or access errors occur, or admin is not authorized (handled by decorator)
 */
export async function patch__shoppingMallAiBackend_admin_appeals(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendAppeal.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendAppeal.ISummary> {
  const { admin, body } = props;

  // Only admins allowed - admin is validated by decorator; enforced at controller

  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  const where = {
    deleted_at: null,
    ...(body.moderation_event_id !== undefined && body.moderation_event_id !== null && {
      moderation_event_id: body.moderation_event_id,
    }),
    ...(body.appellant_id !== undefined && body.appellant_id !== null && {
      appellant_id: body.appellant_id,
    }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.decision_comment !== undefined && body.decision_comment !== null && {
      decision_comment: { contains: body.decision_comment, mode: "insensitive" as const },
    }),
    ...((body.from_date !== undefined && body.from_date !== null) ||
      (body.to_date !== undefined && body.to_date !== null)
      ? {
          created_at: {
            ...(body.from_date !== undefined && body.from_date !== null && { gte: body.from_date }),
            ...(body.to_date !== undefined && body.to_date !== null && { lte: body.to_date }),
          },
        }
      : {}),
  };

  const [data, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_appeals.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_appeals.count({ where }),
  ]);

  const items: IShoppingMallAiBackendAppeal[] = data.map((row) => ({
    id: row.id,
    moderation_event_id: row.moderation_event_id,
    appellant_id: row.appellant_id,
    status: row.status,
    decision_comment: row.decision_comment ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: items,
  };
}

