 * 지정된 주문/결제/결제 로그 ID에 대해, 주문 결제 로그의 log_context만을 수정합니다. 이 작업은 결제 시도, 결제 결과, 기타 비즈니스 이벤트와 연관된 로그의 부가 설명(운영/감사 목적 주석, 사후 조치 등)만 업데이트할 수 있습니다. 
 * 주문 소유 고객만이 결제 로그의 메타데이터(설명) 필드를 수정할 수 있으며, 기타 로그 필드(예: 로그 유형, 발생 시각 등)는 불변입니다. 
 * 모든 경로, 소유권, 권한, 무결성 검사를 엄격히 준수합니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 사용자 페이로드
 * @param props.orderId - 대상 주문 ID
 * @param props.orderPaymentId - 대상 결제 ID
 * @param props.orderPaymentLogId - 업데이트할 결제 로그 ID
 * @param props.body - 로그 주석/감사 목적 정보를 담은 객체 (log_context)
 * @returns 업데이트된 결제 로그 레코드 (불변 필드는 변경 불가)
 * @throws {Error} 결제 로그, 결제, 주문 매핑 오류 또는 접근 권한 없음
 */
export async function put__shoppingMallAiBackend_customer_orders_$orderId_orderPayments_$orderPaymentId_orderPaymentLogs_$orderPaymentLogId(
  props: {
    customer: CustomerPayload;
    orderId: string & tags.Format<'uuid'>;
    orderPaymentId: string & tags.Format<'uuid'>;
    orderPaymentLogId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendOrderPaymentLog.IUpdate;
  }
): Promise<IShoppingMallAiBackendOrderPaymentLog> {
  const { customer, orderId, orderPaymentId, orderPaymentLogId, body } = props;

  // 1. 결제 로그 조회 및 전체 계층(결제, 주문) 포함하여 검증
  const log = await MyGlobal.prisma.shopping_mall_ai_backend_order_payment_logs.findUnique({
    where: { id: orderPaymentLogId },
    include: {
      orderPayment: {
        include: {
          order: true,
        },
      },
    },
  });
  if (!log)
    throw new Error("해당 결제 로그가 존재하지 않습니다.");

  // 2. 결제 로그와 결제 ID 일치성 검증
  if (log.order_payment_id !== orderPaymentId)
    throw new Error("결제 로그가 지정된 결제에 속하지 않습니다.");

  // 3. 결제와 주문 ID 일치성 검증
  if (!log.orderPayment || log.orderPayment.order_id !== orderId)
    throw new Error("결제가 지정된 주문에 속하지 않습니다.");

  // 4. 주문 소유권 검증 (customer.id)
  if (!log.orderPayment.order || log.orderPayment.order.customer_id !== customer.id)
    throw new Error("결제 로그를 수정할 권한이 없습니다 (주문 소유 고객만 가능)");

  // 5. 오직 log_context 필드만 업데이트 (불변 필드 보호)
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_order_payment_logs.update({
    where: { id: orderPaymentLogId },
    data: {
      log_context: body.log_context,
    },
  });

  // 6. 변환: occurred_at은 ISO 8601 문자열로 변환 후 반환
  return {
    id: updated.id,
    order_payment_id: updated.order_payment_id,
    log_type: updated.log_type,
    log_context: updated.log_context,
    occurred_at: toISOStringSafe(updated.occurred_at),
  };
}

