/**
 * Create a new order group (batch process context).
 *
 * Create an order group by providing all necessary parameters in the request body (DTO: IShoppingMallAiBackendOrderGroup.ICreate). This is used for business batch processes, partner order tracking, or scheduled integrations, linking multiple orders under a group context.
 *
 * Process enforces validation logic and privilege checks. On creation, the new group entity is returned, and an audit event is created. Any validation, duplication, or privilege error is reported via structured response.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user performing the creation
 * @param props.body - The order group creation data (group_name required; external_reference, meta_info optional)
 * @returns The newly created order group entity
 * @throws {Error} When creation fails or privilege violation occurs
 */
export async function post__shoppingMallAiBackend_admin_orderGroups(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendOrderGroup.ICreate;
  }
): Promise<IShoppingMallAiBackendOrderGroup> {
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  const id: string & tags.Format<'uuid'> = v4();

  // Create the order group
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_order_groups.create({
    data: {
      id,
      group_name: props.body.group_name,
      external_reference: props.body.external_reference ?? undefined,
      meta_info: props.body.meta_info ?? undefined,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    }
  });

  // Create audit log event
  await MyGlobal.prisma.shopping_mall_ai_backend_audit_logs.create({
    data: {
      id: v4(),
      action_type: 'create_order_group',
      actor_id: props.admin.id,
      actor_type: 'admin',
      target_type: 'order_group',
      target_id: id,
      description: `Order group [${props.body.group_name}] has been created by admin.`,
      audit_payload: JSON.stringify({ group_name: props.body.group_name }),
      occurred_at: now,
    }
  });

  return {
    id: created.id,
    group_name: created.group_name,
    external_reference: created.external_reference ?? null,
    meta_info: created.meta_info ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
