import { IPageIShoppingMallAiBackendArticle } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendArticle";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";


/**
 * Get a paginated, filterable list of articles for content listing pages.
 *
 * This endpoint fetches a paginated list of articles from the shopping_mall_ai_backend_articles table. Each article may be a BBS post, FAQ, or news item, authored by users, sellers, or admins. This implementation returns only published, non-deleted articles to the public, sorted by most recent creation. Paging is fixed at the first page (20 items per page) since filtering options are not exposed in this function. Returned fields include article id, title, summary, category, status, author info, and engagement metrics. All date fields are output as ISO strings in compliance with API/DTO contracts. For each article, only required and allowed fields are exposed. Pagination info is calculated per IPage.IPagination. This endpoint is public (no authentication required).
 *
 * @returns Paged summary list of published, non-deleted articles with pagination metadata.
 * @throws {Error} When database access fails
 */
export async function get__shoppingMallAiBackend_articles(): Promise<IPageIShoppingMallAiBackendArticle.ISummary> {
  const page = 1;
  const limit = 20;

  const [articles, totalRecords] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_articles.findMany({
      where: {
        status: "published",
        deleted_at: null,
      },
      orderBy: {
        created_at: "desc",
      },
      skip: 0,
      take: limit,
      select: {
        id: true,
        title: true,
        summary: true,
        category_id: true,
        author_type: true,
        author_id: true,
        status: true,
        view_count: true,
        comment_count: true,
        created_at: true,
        updated_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_articles.count({
      where: {
        status: "published",
        deleted_at: null,
      },
    }),
  ]);

  const pages = Math.ceil(totalRecords / limit);
  const data: IPageIShoppingMallAiBackendArticle.ISummary["data"] = articles.map(article => ({
    id: article.id,
    title: article.title,
    summary: article.summary ?? null,
    category_id: article.category_id,
    author_type: article.author_type,
    author_id: article.author_id,
    status: article.status,
    view_count: article.view_count as number & tags.Type<'int32'>,
    comment_count: article.comment_count as number & tags.Type<'int32'>,
    created_at: toISOStringSafe(article.created_at),
    updated_at: toISOStringSafe(article.updated_at),
  }));

  const pagination: IPageIShoppingMallAiBackendArticle.ISummary["pagination"] = {
    current: page as number & tags.Type<"int32">,
    limit: limit as number & tags.Type<"int32">,
    records: totalRecords as number & tags.Type<"int32">,
    pages: pages as number & tags.Type<"int32">,
  };

  return { pagination, data };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
