import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Update section details for an existing section (shopping_mall_ai_backend_sections).
 *
 * Updates details of an existing section under a business channel. Only admins can perform updates. Requires the channelId to maintain referential integrity and sectionId to ensure exact target. Permits modifications of code, name, description, order, and visibility fields. Maintains an audit trail (timestamps, updating admin). Unique constraints for section codes within the channel are strictly enforced. Soft delete applies: deleted_at field set for removal. Authorization limited to users with admin privileges.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the update
 * @param props.channelId - Target channel's unique ID (UUID) to which the section belongs
 * @param props.sectionId - Unique UUID of the section to update
 * @param props.body - Section fields to update (partial or full)
 * @returns The updated section entity
 * @throws {Error} If not found, unauthorized, or code duplication
 */
export async function put__shoppingMallAiBackend_admin_channels_$channelId_sections_$sectionId(
  props: {
    admin: AdminPayload;
    channelId: string & tags.Format<'uuid'>;
    sectionId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendSection.IUpdate;
  }
): Promise<IShoppingMallAiBackendSection> {
  const { admin, channelId, sectionId, body } = props;
  // Step 1: Find the target section
  const section = await MyGlobal.prisma.shopping_mall_ai_backend_sections.findFirst({
    where: { id: sectionId, channel_id: channelId, deleted_at: null },
  });
  if (!section) throw new Error('Section not found');

  // Only admins with an active account (already checked in auth decorator) can update
  // If code is being changed, check uniqueness in this channel
  if (body.code !== undefined && body.code !== section.code) {
    const duplicate = await MyGlobal.prisma.shopping_mall_ai_backend_sections.findFirst({
      where: { channel_id: channelId, code: body.code, id: { not: sectionId }, deleted_at: null },
    });
    if (duplicate) {
      throw new Error('Another section with this code already exists in the channel');
    }
  }
  // Prepare new timestamp as ISO string
  const now = toISOStringSafe(new Date());
  // Update fields directly
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_sections.update({
    where: { id: sectionId },
    data: {
      code: body.code ?? undefined,
      name: body.name ?? undefined,
      description: body.description ?? undefined,
      display_order: body.display_order ?? undefined,
      visible: body.visible ?? undefined,
      updated_at: now,
    },
  });
  return {
    id: updated.id as string & tags.Format<'uuid'>,
    channel_id: updated.channel_id as string & tags.Format<'uuid'>,
    created_by_admin_id: updated.created_by_admin_id as string & tags.Format<'uuid'>,
    code: updated.code,
    name: updated.name,
    description: updated.description ?? null,
    display_order: updated.display_order,
    visible: updated.visible,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

