import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Advanced list and search order groups with filter, pagination, sorting.
 *
 * Search and filter through order groups by providing criteria in the request body (DTO: IShoppingMallAiBackendOrderGroup.IRequest).
 * Only returns groups with at least one order for the current customer, using secure relational filtering.
 *
 * @param props - Request parameter object
 * @param props.customer - Authenticated customer payload (must be active, validated in decorator)
 * @param props.body - The advanced filter/search parameters (IShoppingMallAiBackendOrderGroup.IRequest)
 * @returns A paginated result object containing order groups matching the filter, only including groups the customer may legitimately view
 * @throws {Error} If invalid filters or underlying query errors occur
 */
export async function patch__shoppingMallAiBackend_customer_orderGroups(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendOrderGroup.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendOrderGroup> {
  const { customer, body } = props;
  // Pagination defaults (always positive ints)
  const page = body.page && body.page > 0 ? body.page : 1;
  const pageSize = body.pageSize && body.pageSize > 0 ? body.pageSize : 20;
  // Build relational filter: only order groups for which the current customer owns at least one order
  const where = {
    deleted_at: null,
    shopping_mall_ai_backend_orders: {
      some: {
        customer_id: customer.id,
        deleted_at: null,
      },
    },
    ...(body.group_name !== undefined && body.group_name !== null && body.group_name.length > 0 && {
      group_name: { contains: body.group_name, mode: "insensitive" as const },
    }),
    ...(body.external_reference !== undefined && body.external_reference !== null && body.external_reference.length > 0 && {
      external_reference: body.external_reference,
    }),
    ...((body.created_at_gte !== undefined && body.created_at_gte !== null) || (body.created_at_lte !== undefined && body.created_at_lte !== null)
      ? {
          created_at: {
            ...(body.created_at_gte !== undefined && body.created_at_gte !== null && { gte: body.created_at_gte }),
            ...(body.created_at_lte !== undefined && body.created_at_lte !== null && { lte: body.created_at_lte }),
          },
        }
      : {}),
  };
  // Sorting (default is created_at desc if not specified)
  const orderBy =
    body.sort && body.sort.length > 0
      ? body.sort.startsWith("-")
        ? { [body.sort.substring(1)]: "desc" as const }
        : { [body.sort]: "asc" as const }
      : { created_at: "desc" as const };
  // Query concurrently for pagination
  const [groups, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_order_groups.findMany({
      where,
      orderBy,
      skip: (page - 1) * pageSize,
      take: pageSize,
      select: {
        id: true,
        group_name: true,
        external_reference: true,
        meta_info: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_order_groups.count({ where }),
  ]);
  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data: groups.map((g) => ({
      id: g.id,
      group_name: g.group_name,
      external_reference: g.external_reference ?? null,
      meta_info: g.meta_info ?? null,
      created_at: g.created_at,
      updated_at: g.updated_at,
      deleted_at: g.deleted_at ?? null,
    })),
  };
}

