/**
 * Create a new audit/compliance log record for a file event.
 *
 * Creates an audit or operational log record for a given attachmentId, representing a specific event/action taken on a file. Required fields include the event_type (such as upload/download/access), ip_address, and event_at timestamp; optional fields provide context (event_context) or link to the operating admin. Used for tracking who did what, when, and why regarding file management.
 *
 * Calls to this endpoint are security-critical: logs may be entered by trusted system actors (automation, backend services) or privileged humans (admins). Entries are immutable after insert, and must be comprehensive for audit/proof. Any invalid references, missing fields, or security violations are returned as errors, and all additions are themselves logged in the compliance subsystem.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the log operation
 * @param props.attachmentId - ID of the attachment file to add the event log for
 * @param props.body - The file event metadata to log
 * @returns The newly created log entry as full metadata
 * @throws {Error} When the attachment does not exist or is soft-deleted
 */
export async function post__shoppingMallAiBackend_admin_attachments_$attachmentId_logs(props: {
  admin: AdminPayload;
  attachmentId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendAttachmentLog.ICreate;
}): Promise<IShoppingMallAiBackendAttachmentLog> {
  const { admin, attachmentId, body } = props;

  // Step 1: Enforce attachment existence (not deleted)
  const attachment = await MyGlobal.prisma.shopping_mall_ai_backend_attachments.findFirst({
    where: {
      id: attachmentId,
      deleted_at: null,
    },
  });
  if (!attachment) {
    throw new Error('Attachment not found or has been deleted');
  }

  // Step 2: Prepare the created log's id
  const logId = v4() as string & tags.Format<'uuid'>;

  // Step 3: Create log row (no Date objects; convert event_at if needed)
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_attachment_logs.create({
    data: {
      id: logId,
      attachment_id: attachmentId,
      event_type: body.event_type,
      event_context: body.event_context ?? null,
      ip_address: body.ip_address,
      operated_by_admin_id:
        body.operated_by_admin_id !== undefined && body.operated_by_admin_id !== null
          ? body.operated_by_admin_id
          : admin.id,
      event_at: toISOStringSafe(body.event_at),
    }
  });

  // Step 4: Return mapped, branded log record (no Date objects)
  return {
    id: created.id,
    attachment_id: created.attachment_id,
    event_type: created.event_type,
    event_context: created.event_context,
    ip_address: created.ip_address,
    operated_by_admin_id: created.operated_by_admin_id,
    event_at: toISOStringSafe(created.event_at),
  };
}

