import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Delete a specific search keyword from a product (shopping_mall_ai_backend_product_search_keywords).
 *
 * This operation removes a product search keyword mapping from a product in the shopping mall AI backend. It enforces referential integrity by confirming that the provided productId and productSearchKeywordId represent a valid relationship in the shopping_mall_ai_backend_product_search_keywords table. Only sellers associated with the product can perform this deletion. The mapping is deleted permanently (hard delete, not soft), and the operation returns no content on success. Error responses are thrown for missing mapping, mismatched product, or unauthorized user.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the operation
 * @param props.productId - The UUID of the target product
 * @param props.productSearchKeywordId - The UUID of the product search keyword mapping to remove
 * @returns void
 * @throws {Error} If the mapping does not exist, doesn't match product, or the seller does not own the product
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId_productSearchKeywords_$productSearchKeywordId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productSearchKeywordId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { seller, productId, productSearchKeywordId } = props;

  // 1. Lookup the keyword mapping by id
  const mapping = await MyGlobal.prisma.shopping_mall_ai_backend_product_search_keywords.findUnique({
    where: { id: productSearchKeywordId }
  });
  if (!mapping) {
    throw new Error("Product search keyword mapping not found");
  }
  if (mapping.product_id !== productId) {
    throw new Error("Specified keyword does not belong to the given product");
  }

  // 2. Authorization: Ensure current seller owns the product
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: productId }
  });
  if (!product) {
    throw new Error("Product not found");
  }
  if (product.seller_id !== seller.id) {
    throw new Error("Unauthorized: Only the product owner seller may perform this operation");
  }

  // 3. Execute hard delete
  await MyGlobal.prisma.shopping_mall_ai_backend_product_search_keywords.delete({
    where: { id: productSearchKeywordId }
  });
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Deletes an article category (soft delete) given its categoryId.
 *
 * - Fails if category does not exist or already deleted.
 * - Fails if there are non-deleted children or referenced articles (integrity enforcement).
 * - Sets deleted_at timestamp to now for soft delete (record retained for audit).
 * - Only admin may execute.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user performing the deletion
 * @param props.categoryId - ID of the article category to delete
 * @returns void
 * @throws {Error} When the category does not exist
 * @throws {Error} When the category has non-deleted children
 * @throws {Error} When the category has non-deleted articles
 */
export async function delete__shoppingMallAiBackend_admin_articleCategories_$categoryId(
  props: { admin: AdminPayload; categoryId: string & tags.Format<'uuid'> }
): Promise<void> {
  const { admin, categoryId } = props;

  // Ensure category exists and is not already deleted
  const category = await MyGlobal.prisma.shopping_mall_ai_backend_article_categories.findFirst({
    where: { id: categoryId, deleted_at: null }
  });
  if (!category) throw new Error('Article category not found or already deleted');

  // Ensure no non-deleted child categories
  const childCount = await MyGlobal.prisma.shopping_mall_ai_backend_article_categories.count({
    where: { parent_id: categoryId, deleted_at: null }
  });
  if (childCount > 0)
    throw new Error('Cannot delete: There are non-deleted child categories. Delete children first.');

  // Ensure no articles exist in this category (not soft deleted)
  const articleCount = await MyGlobal.prisma.shopping_mall_ai_backend_articles.count({
    where: { category_id: categoryId, deleted_at: null }
  });
  if (articleCount > 0)
    throw new Error('Cannot delete: There are articles in this category. Delete articles first.');

  // Soft delete: set deleted_at
  await MyGlobal.prisma.shopping_mall_ai_backend_article_categories.update({
    where: { id: categoryId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
  // No return value for void
}

