import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Creates a new product-category mapping for a seller's product.
 *
 * This function maps a product to a new or existing category as either its primary or secondary grouping.
 * It validates ownership, existence, and uniqueness constraints. Soft-deleted (or missing) products or categories are forbidden, as are duplicate or multiple-primary assignments.
 *
 * @param props - The operation props
 * @param props.seller - Seller authentication payload (must own the product)
 * @param props.productId - The product UUID to be mapped
 * @param props.body - Creation data including the target category and primary flag
 * @returns The created mapping record
 * @throws {Error} 404 if product or category does not exist or is soft-deleted
 * @throws {Error} 403 if the product is not owned by the seller
 * @throws {Error} 400 if a duplicate or illegal mapping is attempted
 */
export async function post__shoppingMallAiBackend_seller_products_$productId_productCategoryMap(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductCategoryMap.ICreate;
  }
): Promise<IShoppingMallAiBackendProductCategoryMap> {
  const { seller, productId, body } = props;

  // 1. Validate product: exists, not deleted, owned by seller
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: productId,
      deleted_at: null,
    },
  });
  if (!product) throw new Error("Product not found");
  if (product.seller_id !== seller.id) throw new Error("Forbidden: not your product");

  // 2. Validate category: exists, not deleted
  const category = await MyGlobal.prisma.shopping_mall_ai_backend_categories.findFirst({
    where: {
      id: body.category_id,
      deleted_at: null,
    },
  });
  if (!category) throw new Error("Category not found");

  // 3. Enforce uniqueness of (product, category) mapping
  const exists = await MyGlobal.prisma.shopping_mall_ai_backend_product_category_map.findFirst({
    where: {
      product_id: productId,
      category_id: body.category_id,
    },
  });
  if (exists) throw new Error("Duplicate mapping");

  // 4. Enforce only one 'primary' per product
  if (body.primary) {
    const hasPrimary = await MyGlobal.prisma.shopping_mall_ai_backend_product_category_map.findFirst({
      where: { product_id: productId, primary: true },
    });
    if (hasPrimary) throw new Error("Primary category mapping already exists for this product");
  }

  // 5. Insert the new mapping
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_product_category_map.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      product_id: productId,
      category_id: body.category_id,
      primary: body.primary,
    },
  });

  return {
    id: created.id,
    product_id: created.product_id,
    category_id: created.category_id,
    primary: created.primary,
  };
}

