/**
 * List order payment records for a specific order with filtering and pagination (shopping_mall_ai_backend_order_payments).
 *
 * Retrieve a filtered, paginated list of payment records for a specific order. The list includes all payment attempts, their methods, providers, transaction results, statuses, and relevant metadata needed for transaction history, customer self-service history, finance audits, or compliance investigations. Advanced search supports filtering by method, time window, or specific result. Only customers associated with the order, system administrators, or finance operators can perform this operation. If no payments are found, the result is an empty paginated list. Records with soft deletes are omitted from default queries unless specifically requested via compliance/audit context.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user (authorization required)
 * @param props.orderId - The unique identifier of the order for which payment records are being listed
 * @param props.body - Advanced filtering, pagination, and search criteria for retrieving order payments
 * @returns Paginated, filtered list of order payment records for the specified order
 * @throws {Error} If the order does not exist
 */
export async function patch__shoppingMallAiBackend_admin_orders_$orderId_orderPayments(props: {
  admin: AdminPayload;
  orderId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendOrderPayment.IRequest;
}): Promise<IPageIShoppingMallAiBackendOrderPayment> {
  const { admin, orderId, body } = props;
  // AdminAuth decorator ensures admin is authorized

  // Validate and normalize pagination params
  const page: number = body.page != null && body.page >= 1 ? body.page : 1;
  const limit: number = body.limit != null && body.limit >= 1 && body.limit <= 200 ? body.limit : 20;

  // Construct Prisma where clause for filters
  const where = {
    order_id: orderId,
    deleted_at: null,
    ...(body.payment_method !== undefined && body.payment_method !== null && {
      payment_method: body.payment_method,
    }),
    ...(body.payment_result !== undefined && body.payment_result !== null && {
      payment_result: body.payment_result,
    }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) || (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined && body.created_at_from !== null && {
              gte: body.created_at_from,
            }),
            ...(body.created_at_to !== undefined && body.created_at_to !== null && {
              lte: body.created_at_to,
            }),
          },
        }
      : {}),
  };

  // Query total count for pagination
  const total = await MyGlobal.prisma.shopping_mall_ai_backend_order_payments.count({ where });

  // Query paginated records, sorted by created_at desc
  const results = await MyGlobal.prisma.shopping_mall_ai_backend_order_payments.findMany({
    where,
    orderBy: { created_at: "desc" },
    skip: (page - 1) * limit,
    take: limit,
  });

  // Map results to API DTO, convert all Date fields to string & tags.Format<'date-time'>
  const data = results.map((item) => ({
    id: item.id as string & tags.Format<'uuid'>,
    order_id: item.order_id as string & tags.Format<'uuid'>,
    payment_provider_id: item.payment_provider_id as string & tags.Format<'uuid'>,
    payment_method: item.payment_method,
    transaction_id: item.transaction_id,
    amount: item.amount,
    currency_code: item.currency_code,
    payment_result: item.payment_result,
    payment_context: item.payment_context ?? null,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
    deleted_at: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
  }));

  const pages = Math.ceil(total / limit);

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages,
    },
    data,
  };
}

