    ? [
        { name: { contains: search, mode: "insensitive" as const } },
        { code: { contains: search, mode: "insensitive" as const } },
        { description: { contains: search, mode: "insensitive" as const } },
      ]
    : undefined;
  if (searchConditions) {
    // WHERE에 OR 추가
    (where as any).OR = searchConditions;
  }

  // --- 정렬 순서(orderBy) ---
  const allowedFields = ["created_at", "updated_at", "name", "status", "code"];
  const orderBy =
    Array.isArray(sort) && sort.length > 0
      ? sort
          .filter((s) => allowedFields.includes(s.field))
          .map((s) => ({ [s.field]: s.direction === "asc" ? "asc" : "desc" }))
      : [{ created_at: "desc" }];

  // --- 데이터/카운트 동시 조회 ---
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_products.findMany({
      where,
      skip,
      take,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_products.count({ where }),
  ]);

  // --- 결과 DTO 변환 (날짜 변환 및 brand 보정) ---
  const data: IShoppingMallAiBackendProduct[] = records.map((rec) => ({
    id: rec.id,
    seller_id: rec.seller_id,
    code: rec.code,
    name: rec.name,
    description: rec.description ?? null,
    main_image_uri: rec.main_image_uri ?? null,
    status: rec.status,
    created_at: toISOStringSafe(rec.created_at),
    updated_at: toISOStringSafe(rec.updated_at),
    deleted_at:
      rec.deleted_at !== undefined && rec.deleted_at !== null
        ? toISOStringSafe(rec.deleted_at)
        : null,
  }));

  // --- 페이지네이션 정보 ---
  const pagination = {
    current: pageNum,
    limit: take,
    records: total,
    pages: Math.ceil(total / take),
  };

  return {
    pagination,
    data,
  };
}

