export async function patch__shoppingMallAiBackend_seller_products(
  props: { seller: SellerPayload; body: IShoppingMallAiBackendProduct.IRequest }
): Promise<IPageIShoppingMallAiBackendProduct> {
  const { seller, body } = props;

  // 필터링 조건
  const filter = body.filter ?? {};
  const where = {
    seller_id: seller.id,
    ...(filter.productId !== undefined && filter.productId !== null && { id: filter.productId }),
    ...(filter.code && { code: { contains: filter.code, mode: 'insensitive' as const } }),
    ...(filter.name && { name: { contains: filter.name, mode: 'insensitive' as const } }),
    ...(filter.status && { status: filter.status }),
    ...((filter.deleted === true) && { deleted_at: { not: null } }),
    ...((filter.deleted === false) && { deleted_at: null }),
    ...((filter.createdFrom || filter.createdTo) && {
      created_at: {
        ...(filter.createdFrom && { gte: filter.createdFrom }),
        ...(filter.createdTo && { lt: filter.createdTo })
      }
    })
  };

  // 정렬 허용 필드 제한
  const allowedFields = ['created_at', 'name', 'status', 'code'];
  let orderBy: Record<string, 'asc' | 'desc'>[] = [{ created_at: 'desc' }];
  if (Array.isArray(body.sort) && body.sort.length > 0) {
    orderBy = body.sort
      .filter(s => allowedFields.includes(s.field))
      .map(s => ({ [s.field]: s.direction === 'asc' ? 'asc' : 'desc' }));
  }

  // 페이징 (디폴트 1페이지, 20개, 최대 1000개)
  const page = typeof body.page === 'number' && body.page > 0 ? body.page : 1;
  const pageSize = (typeof body.pageSize === 'number' && body.pageSize > 0 && body.pageSize <= 1000) ? body.pageSize : 20;
  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // 병렬 조회
  const [rows, totalCount] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_products.findMany({
      where,
      orderBy,
      skip,
      take,
      select: {
        id: true,
        seller_id: true,
        code: true,
        name: true,
        description: true,
        main_image_uri: true,
        status: true,
        created_at: true,
        updated_at: true,
        deleted_at: true
