  // 결과 매핑 (날짜 문자열 변환)
  const result: IPageIShoppingMallAiBackendProduct = {
    pagination: {
      current: page,
      limit: pageSize,
      records: totalCount,
      pages: Math.ceil(totalCount / pageSize)
    },
    data: rows.map(row => ({
      id: row.id,
      seller_id: row.seller_id,
      code: row.code,
      name: row.name,
      description: row.description ?? null,
      main_image_uri: row.main_image_uri ?? null,
