  customer: CustomerPayload;
  body: IShoppingMallAiBackendFavoriteAddress.IRequest;
}): Promise<IPageIShoppingMallAiBackendFavoriteAddress> {
  const { customer, body } = props;

  // Pagination with defaults (page>=1, limit>=1, <=100)
  const page = typeof body.page === "number" && body.page >= 1 ? body.page : 1;
  const limit = typeof body.limit === "number" && body.limit >= 1 && body.limit <= 100 ? body.limit : 20;

  // Build created_at filter properly with gte/lte
