    deleted_at: null,
    order_id: orderId,
    ...(body.product_id !== undefined && body.product_id !== null && { product_id: body.product_id }),
    ...(body.product_snapshot_id !== undefined && body.product_snapshot_id !== null && { product_snapshot_id: body.product_snapshot_id }),
