  // Query - parallel fetch of rows and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_order_items.findMany({ where, skip, take, orderBy }),
    MyGlobal.prisma.shopping_mall_ai_backend_order_items.count({ where }),
  ]);

  const data = rows.map(row => ({
    id: row.id,
    order_id: row.order_id,
    product_id: row.product_id,
    product_snapshot_id: row.product_snapshot_id,
    quantity: row.quantity,
    unit_price: row.unit_price,
    currency_code: row.currency_code,
    note: row.note ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data,
  };
}

