 *
 * This endpoint allows an authenticated admin to permanently delete (hard delete) an order snapshot archive for compliance, audit, or business reasons. The operation fails if the order or the snapshot does not exist, or if the snapshot does not belong to the provided order. Only admins with valid credentials may perform this operation.
 *
 * @param props - Request parameters
 * @param props.admin - Authenticated admin payload as enforced by AdminAuth
 * @param props.orderId - The unique identifier of the target order (parent)
 * @param props.orderSnapshotId - The unique identifier of the order snapshot (child)
 * @returns void (no content)
 * @throws {Error} If the order does not exist
 * @throws {Error} If the snapshot does not exist
 * @throws {Error} If the snapshot does not belong to the specified order
 */
export async function delete__shoppingMallAiBackend_admin_orders_$orderId_orderSnapshots_$orderSnapshotId(
  props: {
    admin: AdminPayload;
    orderId: string & tags.Format<'uuid'>;
    orderSnapshotId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { admin, orderId, orderSnapshotId } = props;

  // 1. Ensure the order exists
  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findUnique({
    where: { id: orderId }
  });
  if (!order) throw new Error('Order not found');

  // 2. Ensure the snapshot exists
