/**
 * Create a favorite notification event for a favorite object update, state, or action.
 *
 * This endpoint creates a notification event for a favorite object (product, inquiry, or address) belonging to the authenticated customer.
 * Validates that the favorite object exists, is not deleted, and belongs to the customer, rejects duplicates, and creates the event.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request
 * @param props.body - Notification creation details: favorite object reference, event type, channel, and delivery state
 * @returns The newly created favorite notification event record
 * @throws {Error} If the favorite object does not exist, is not owned by the customer, or a duplicate notification exists
 */
export async function post__shoppingMallAiBackend_customer_favoriteNotifications(
  props: { customer: CustomerPayload; body: IShoppingMallAiBackendFavoriteNotification.ICreate }
): Promise<IShoppingMallAiBackendFavoriteNotification> {
  const { customer, body } = props;

  // Extract favorite type and validate exclusivity
  const favoriteTypes = [
    { type: 'favorite_product_id', value: body.favorite_product_id },
    { type: 'favorite_inquiry_id', value: body.favorite_inquiry_id },
    { type: 'favorite_address_id', value: body.favorite_address_id }
  ].filter(i => i.value !== undefined && i.value !== null);
  if (favoriteTypes.length !== 1) {
    throw new Error('Exactly one favorite object id must be provided (product, inquiry, or address)');
  }

  // Ownership & existence
  let favorite;
  if (favoriteTypes[0].type === 'favorite_product_id') {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findFirst({
      where: { id: body.favorite_product_id!, deleted_at: null }, select: { customer_id: true }
    });
  } else if (favoriteTypes[0].type === 'favorite_inquiry_id') {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findFirst({
      where: { id: body.favorite_inquiry_id!, deleted_at: null }, select: { customer_id: true }
    });
  } else if (favoriteTypes[0].type === 'favorite_address_id') {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findFirst({
      where: { id: body.favorite_address_id!, deleted_at: null }, select: { customer_id: true }
    });
  }
  if (!favorite || favorite.customer_id !== customer.id) {
    throw new Error('Favorite object does not exist, is deleted, or does not belong to this customer');
  }

  // Check for duplicate
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.findFirst({
    where: {
      [favoriteTypes[0].type]: favoriteTypes[0].value,
      notification_type: body.notification_type,
      notification_channel: body.notification_channel,
      read: body.read,
    }
  });
  if (duplicate) {
    throw new Error('Notification already exists for this favorite object and event type/channel');
  }

  // System timestamp for created_at
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      favorite_product_id: body.favorite_product_id ?? null,
      favorite_inquiry_id: body.favorite_inquiry_id ?? null,
      favorite_address_id: body.favorite_address_id ?? null,
      notification_type: body.notification_type,
      notification_channel: body.notification_channel,
      read: body.read,
      delivery_metadata: body.delivery_metadata ?? null,
      created_at: now
    }
  });

  return {
    id: created.id,
    favorite_product_id: created.favorite_product_id ?? null,
    favorite_inquiry_id: created.favorite_inquiry_id ?? null,
    favorite_address_id: created.favorite_address_id ?? null,
    notification_type: created.notification_type,
    notification_channel: created.notification_channel,
    read: created.read,
    delivery_metadata: created.delivery_metadata ?? null,
    created_at: now
  };
}

