  const skip = (page - 1) * limit;
  const sortBy = (body.sort_by ?? 'occurred_at') as string;
  const sortDirection = (body.sort_direction ?? 'desc') === 'asc' ? 'asc' : 'desc';
  // 4. Query and count in parallel
