    MyGlobal.prisma.shopping_mall_ai_backend_order_status_histories.findMany({
      where,
      orderBy: { [sortBy]: sortDirection },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_order_status_histories.count({ where })
  ]);
  // 5. Map output, converting occurred_at with toISOStringSafe
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: total === 0 ? 0 : Math.ceil(total / limit)
    },
    data: records.map(r => ({
      id: r.id,
      order_id: r.order_id,
      previous_status: r.previous_status,
      new_status: r.new_status,
      actor_type: r.actor_type,
