/**
 * Soft deletes a customer's profile record by setting the deleted_at timestamp.
 * No physical data is destroyed, but the profile is hidden from business processes,
 * cannot be used for login, and is excluded from customer listings. Used for regulatory
 * compliance or at the request of customers/admins. Attempting to delete an already
 * soft-deleted or non-existent customer returns an error. This action is recorded in
 * customer_histories for audit and compliance. All related addresses or subresources
 * remain unaffected by this operation unless explicit secondary cleanup occurs.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin performing the soft delete
 * @param props.customerId - UUID of the customer to soft delete (shopping_mall_ai_backend_customers.id)
 * @returns void
 * @throws {Error} When the customer does not exist or is already soft deleted
 */
export async function delete__shoppingMallAiBackend_admin_customers_$customerId(props: {
  admin: AdminPayload;
  customerId: string & tags.Format<'uuid'>;
}): Promise<void> {
  const { admin, customerId } = props;

  // Validate customerId format at runtime
  typia.assert<typeof customerId>(customerId);

  // Find the not-deleted customer
  const customer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: { id: customerId, deleted_at: null },
  });
  if (!customer) {
    throw new Error('Customer not found or already soft deleted');
  }

  // Prepare ISO8601 timestamp for soft delete
  const deleted_at: string & tags.Format<'date-time'> = toISOStringSafe(new Date());

  // Update customer (soft delete)
  await MyGlobal.prisma.shopping_mall_ai_backend_customers.update({
    where: { id: customerId },
    data: { deleted_at },
  });

  // Prepare full audit trail (convert Date objects to ISO string)
  const oldValue = {
    ...customer,
    joined_at: toISOStringSafe(customer.joined_at),
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    last_login_at: customer.last_login_at ? toISOStringSafe(customer.last_login_at) : null,
    deleted_at: null,
  };
  const newValue = {
    ...oldValue,
    deleted_at,
  };

  // Write audit trail in customer_histories
  const historyId: string & tags.Format<'uuid'> = v4();
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: historyId,
      customer_id: customerId,
      event_type: 'deleted',
      old_value_json: JSON.stringify(oldValue),
      new_value_json: JSON.stringify(newValue),
      triggered_by: admin.id,
      meta_json: null,
      occurred_at: deleted_at,
      created_at: deleted_at,
    },
  });
}

