 * - Ownership of the order item and product.
 * - Maximum one review per (customer, product, order item).
 * - Optional AI moderation results.
 * - All compliance and audit trail info.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request (CustomerPayload, JWT)
 * @param props.body - Details required for creating the review (product_id, order_item_id, title, body, rating, status, AI fields)
 * @returns The created product review as an IShoppingMallAiBackendProductReview
 * @throws {Error} If a duplicate review exists for this (customer, product, order item)
 * @throws {Error} If the provided order item does not belong to the customer or does not match product
 */
export async function post__shoppingMallAiBackend_customer_productReviews(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendProductReview.ICreate;
  }
): Promise<IShoppingMallAiBackendProductReview> {
  const { customer, body } = props;

  // Check for duplicate review (enforce only one per customer/product/orderItem)
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findFirst({
    where: {
      customer_id: customer.id,
      product_id: body.product_id,
      order_item_id: body.order_item_id,
      deleted_at: null,
    },
  });
  if (existing) {
    throw new Error("Duplicate review for this product and order item is not allowed.");
