  });
  if (!orderItem || orderItem.customer_id !== customer.id) {
    throw new Error("Order item does not belong to this customer or does not match product.");
  }

  // Timestamp for creation/audit
  const now = toISOStringSafe(new Date());

  // Create the review
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.create({
