/**
 * List and search order items within an order (for customers).
 *
 * Retrieves a paginated and filtered list of items for a given order, ensuring the requesting customer owns the order and applying provided filters.
 *
 * @param props - Includes authenticated customer, target orderId, and filter body (IRequest).
 * @param props.customer - The authenticated customer making the request (must own the order)
 * @param props.orderId - The UUID of the order to retrieve items for
 * @param props.body - Filter and pagination parameters
 * @returns A page of order items and pagination meta.
 * @throws {Error} If the order does not exist or is not owned by customer.
 */
export async function patch__shoppingMallAiBackend_customer_orders_$orderId_orderItems(props: {
  customer: CustomerPayload;
  orderId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendOrderItem.IRequest;
}): Promise<IPageIShoppingMallAiBackendOrderItem> {
  const { customer, orderId, body } = props;

  // 1. Authorization: Only allow if order belongs to customer (and not soft-deleted)
  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findFirst({
    where: {
      id: orderId,
      customer_id: customer.id,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (!order) throw new Error("Order not found or not authorized");

  // 2. Pagination (defaults)
  const page = body.page != null && body.page > 0 ? body.page : 1;
  const limit = body.pageSize != null && body.pageSize > 0 ? body.pageSize : 20;

  // 3. Filter - only allowed fields
  const where = {
    order_id: orderId,
    deleted_at: null,
    ...(body.product_id !== undefined && body.product_id !== null && {
      product_id: body.product_id,
    }),
    ...(body.product_snapshot_id !== undefined && body.product_snapshot_id !== null && {
      product_snapshot_id: body.product_snapshot_id,
    }),
    ...(body.currency_code !== undefined && body.currency_code !== null && {
      currency_code: body.currency_code,
    }),
    ...((body.created_at_gte !== undefined && body.created_at_gte !== null) ||
      (body.created_at_lte !== undefined && body.created_at_lte !== null)
      ? {
          created_at: {
            ...(body.created_at_gte !== undefined && body.created_at_gte !== null && { gte: body.created_at_gte }),
            ...(body.created_at_lte !== undefined && body.created_at_lte !== null && { lte: body.created_at_lte }),
          },
        }
      : {}),
  };

  // 4. Order - only allowed fields, default desc on created_at
  let orderBy = { created_at: "desc" as const };
  if (body.sort && typeof body.sort === "string" && body.sort.trim().length > 0) {
    const sort = body.sort.trim();
    if (sort.startsWith("-")) {
      const f = sort.slice(1);
      if (["created_at", "quantity", "unit_price", "updated_at"].includes(f)) orderBy = { [f]: "desc" };
    } else {
      if (["created_at", "quantity", "unit_price", "updated_at"].includes(sort)) orderBy = { [sort]: "asc" };
    }
  }

  // 5. Query DB: fetch paged list and count in parallel
  const [items, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_order_items.findMany({
      where,
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_order_items.count({ where }),
  ]);

  // 6. Map Prisma results to DTO with correct date/time formatting
  const data = items.map((item) => ({
    id: item.id,
    order_id: item.order_id,
    product_id: item.product_id,
    product_snapshot_id: item.product_snapshot_id,
    quantity: item.quantity,
    unit_price: item.unit_price,
    currency_code: item.currency_code,
    note: item.note ?? null,
    created_at: toISOStringSafe(item.created_at),
    updated_at: toISOStringSafe(item.updated_at),
    deleted_at: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
  }));

  // 7. Return page response
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

