 *
 * Deletes a specific comment for an article, using both the commentId and articleId. Soft delete by setting deleted_at (instead of hard delete) as per schema. Blocks deletion if replies exist (parent_id == commentId and not deleted). Only authorized admin may delete. Throws error if comment not found or replies exist.
 *
 * @param props - Function props structure
 * @param props.admin - Authenticated admin performing the deletion (AdminPayload)
 * @param props.articleId - UUID of the parent article
 * @param props.commentId - UUID of the comment to delete
 * @returns Promise<void>
 * @throws {Error} If comment not found, not authorized, or replies exist
 */
export async function delete__shoppingMallAiBackend_admin_articles_$articleId_comments_$commentId(
  props: {
    admin: AdminPayload;
    articleId: string & tags.Format<'uuid'>;
    commentId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { admin, articleId, commentId } = props;

  // 1. Check that the comment exists and is for the given article, and is not already deleted
  const comment = await MyGlobal.prisma.shopping_mall_ai_backend_article_comments.findFirst({
    where: {
      id: commentId,
      article_id: articleId,
      deleted_at: null,
    },
  });
