    throw new Error('Comment not found');
  }

  // 2. Check for existence of child replies that are not deleted
  const replyCount = await MyGlobal.prisma.shopping_mall_ai_backend_article_comments.count({
    where: {
      parent_id: commentId,
      deleted_at: null,
    },
  });
  if (replyCount > 0) {
    throw new Error('Cannot delete: comment has replies. Delete replies first.');
  }

  // 3. Soft-delete the comment by setting deleted_at
  await MyGlobal.prisma.shopping_mall_ai_backend_article_comments.update({
    where: { id: commentId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
  // No return required as return type is void
}

