/**
 * Retrieve a favorite notification event by its unique ID.
 *
 * Get a specific favorite notification record by unique ID. Only notification owners may access complete details. Enables workflow for marking as read, auditing, or reviewing notification delivery status. Useful for read receipts, delivery troubleshooting, and legal access reviews. Updates audit and event systems to reflect access where applicable.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.favoriteNotificationId - UUID of the favorite notification event record to retrieve
 * @returns The requested favorite notification event record, including delivery status and references
 * @throws {Error} When the notification is not found, not linked to a favorite object, not owned by the customer, or the favorite is deleted
 */
export async function get__shoppingMallAiBackend_customer_favoriteNotifications_$favoriteNotificationId(
  props: {
    customer: CustomerPayload;
    favoriteNotificationId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendFavoriteNotification> {
  const { customer, favoriteNotificationId } = props;

  // Find the notification by ID
  const notification = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.findFirst({
    where: { id: favoriteNotificationId },
  });
  if (!notification) throw new Error("Favorite notification not found");

  // Determine ownership via favorite FK (must not be soft-deleted)
  let ownerCustomerId: string | null = null;
  let favoriteDeletedAt: Date | string | null | undefined = undefined;
  if (notification.favorite_product_id) {
    const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findUnique({
      where: { id: notification.favorite_product_id },
    });
    if (!favorite) throw new Error("Linked favorite product not found");
    ownerCustomerId = favorite.customer_id;
    favoriteDeletedAt = favorite.deleted_at;
  } else if (notification.favorite_inquiry_id) {
    const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findUnique({
      where: { id: notification.favorite_inquiry_id },
    });
    if (!favorite) throw new Error("Linked favorite inquiry not found");
    ownerCustomerId = favorite.customer_id;
    favoriteDeletedAt = favorite.deleted_at;
  } else if (notification.favorite_address_id) {
    const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findUnique({
      where: { id: notification.favorite_address_id },
    });
    if (!favorite) throw new Error("Linked favorite address not found");
    ownerCustomerId = favorite.customer_id;
    favoriteDeletedAt = favorite.deleted_at;
  } else {
    throw new Error("Notification does not reference a valid favorite object");
  }

  // Only the owner may fetch
  if (ownerCustomerId !== customer.id) throw new Error("Forbidden: You are not the owner of this notification");
  // If the favorite is soft-deleted, treat as not found
  if (favoriteDeletedAt) throw new Error("Favorite object was deleted");

  // Return the notification per API DTO, converting date format
  return {
    id: notification.id,
    favorite_product_id: notification.favorite_product_id ?? null,
    favorite_inquiry_id: notification.favorite_inquiry_id ?? null,
    favorite_address_id: notification.favorite_address_id ?? null,
    notification_type: notification.notification_type,
    notification_channel: notification.notification_channel,
    read: notification.read,
    delivery_metadata: notification.delivery_metadata ?? null,
    created_at: toISOStringSafe(notification.created_at),
  };
}

