/**
 * Soft-delete a coupon usage record by couponUsageId (shopping_mall_ai_backend_coupon_usages table).
 *
 * Soft-deletes a coupon usage record identified by couponUsageId from the shopping mall AI backend database.
 * Updates the 'deleted_at' field for the specified coupon usage to preserve audit trail and regulatory compliance.
 * Only coupon usages not attached to locked or reconciled orders are eligible for deletion.
 * All delete operations are logged for auditing. Access is restricted to the 'admin' role.
 *
 * @param props - The request properties
 * @param props.admin - The authenticated admin performing the deletion (must be active)
 * @param props.couponUsageId - Unique identifier of the coupon usage record to be deleted
 * @returns void
 * @throws {Error} If the coupon usage is attached to a locked or reconciled order
 * @throws {Error} If the database operation fails
 */
export async function delete__shoppingMallAiBackend_admin_couponUsages_$couponUsageId(props: {
  admin: AdminPayload;
  couponUsageId: string & tags.Format<'uuid'>;
}): Promise<void> {
  const { admin, couponUsageId } = props;

  // 1. Find coupon usage not already soft-deleted
  const usage = await MyGlobal.prisma.shopping_mall_ai_backend_coupon_usages.findFirst({
    where: {
      id: couponUsageId,
      deleted_at: null,
    },
  });
  if (!usage) return; // already deleted or does not exist (idempotent)

  // 2. Check for attached orders and their status
  const attachedUsages = await MyGlobal.prisma.shopping_mall_ai_backend_coupon_usages_orders.findMany({
    where: { coupon_usage_id: couponUsageId },
    select: { order_id: true },
  });
  if (attachedUsages.length > 0) {
    const orderIds = attachedUsages.map(x => x.order_id);
    const orders = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findMany({
      where: {
        id: { in: orderIds },
        current_status: { in: [
          "locked",
          "reconciled",
        ] },
      },
      select: { id: true, current_status: true },
    });
    if (orders.length > 0) {
      throw new Error("Cannot delete: Coupon usage is attached to a locked or reconciled order");
    }
  }

  // 3. Soft delete the coupon usage
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_coupon_usages.update({
    where: { id: couponUsageId },
    data: { deleted_at: now },
  });

  // 4. Log to compliance events
  await MyGlobal.prisma.shopping_mall_ai_backend_compliance_events.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      event_type: "coupon_usage.soft_delete",
      actor_id: admin.id,
      actor_type: "admin",
      target_type: "coupon_usage",
      target_id: couponUsageId,
      event_payload: null,
      created_at: now,
    },
  });
}

