  });
  if (!cart) throw new Error("Cart not found");

  // 2. Pagination defaults and constraints
  const page = body.page !== undefined && body.page !== null && body.page >= 1 ? body.page : 1;
  const limit = body.limit !== undefined && body.limit !== null && body.limit >= 1 && body.limit <= 100 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // 3. Supported sorting only for valid fields
  const allowedSorts = ["created_at", "quantity"] as const;
  const sortField: "created_at" | "quantity" = allowedSorts.includes(body.sort_field as any) ? (body.sort_field as "created_at" | "quantity") : "created_at";
  const sortDir: "asc" | "desc" = body.sort_dir === "asc" ? "asc" : "desc";

  // 4. Build where clause inline without intermediate variable
  const where = {
    cart_id: cartId,
    deleted_at: null,
    ...(body.product_id !== undefined && body.product_id !== null && { product_id: body.product_id }),
    ...(body.product_option_id !== undefined && body.product_option_id !== null && { product_option_id: body.product_option_id }),
