      created_at: {
        ...(body.created_at_from !== undefined && body.created_at_from !== null && { gte: body.created_at_from }),
        ...(body.created_at_to !== undefined && body.created_at_to !== null && { lte: body.created_at_to }),
      },
    }),
  };

  // 5. Query rows and total count concurrently; direct parameters inline
  const [rows, records] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_cart_items.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [sortField]: sortDir },
