      deleted_at: body.deleted_at ? toISOStringSafe(body.deleted_at) : undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Return the DTO in precise DTO format, branding dates and UUIDs as required
  return {
    id: updated.id,
    customer_id: updated.customer_id,
    provider: updated.provider,
    external_id: updated.external_id,
