import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Updates a product tag for a seller-owned product.
 *
 * Updates the tag string or other mutable properties (currently only "tag") for a tag entry associated with a product,
 * strictly enforcing that the tag and product exist and are owned by the authenticated seller.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller performing the update
 * @param props.productId - Target product UUID for which the tag is being updated
 * @param props.productTagId - Specific tag record (UUID) to update
 * @param props.body - Update data (fields for updating a product tag)
 * @returns Updated tag details, including id, product_id, and tag
 * @throws {Error} If the tag does not exist
 * @throws {Error} If the tag does not belong to the specified product
 * @throws {Error} If the product does not exist or is soft-deleted
 * @throws {Error} If the seller does not own the product (forbidden)
 */
export async function put__shoppingMallAiBackend_seller_products_$productId_productTags_$productTagId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productTagId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductTag.IUpdate;
  }
): Promise<IShoppingMallAiBackendProductTag> {
  const { seller, productId, productTagId, body } = props;

  // Fetch the tag record by its ID
  const tag = await MyGlobal.prisma.shopping_mall_ai_backend_product_tags.findUnique({
    where: { id: productTagId },
    select: { id: true, product_id: true, tag: true },
  });
  if (!tag) {
    throw new Error('Tag not found');
  }

  // Ensure tag is linked to the passed productId
  if (tag.product_id !== productId) {
    throw new Error('Tag not found');
  }

  // Fetch the product (checks for soft deletion)
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: productId },
    select: { id: true, seller_id: true, deleted_at: true },
  });
  if (!product || product.deleted_at !== null) {
    throw new Error('Product not found');
  }

  // Authorization: seller must own product
  if (product.seller_id !== seller.id) {
    throw new Error('Forbidden: Not allowed to update tag for a product you do not own');
  }

  // Update (only allow tag string update)
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_product_tags.update({
    where: { id: productTagId },
    data: {
      tag: body.tag ?? undefined,
    },
    select: { id: true, product_id: true, tag: true },
  });

  return updated;
}

