/**
 * Creates a new order status history record for an order.
 *
 * This endpoint is used to record workflow status changes (e.g. paid, shipped, delivered) for an order.
 * Only the customer that owns the order may create history records, and only allowed status transitions are permitted per business rules.
 * All history records are immutable, fully audited state changes, recording the actor and context for compliance.
 *
 * @param props - Function parameters object
 * @param props.customer - Authenticated customer performing the action
 * @param props.orderId - UUID of the target order
 * @param props.body - Details of the status change event to be recorded (as per API interface)
 * @returns The created order status history record with all fields populated
 * @throws {Error} If the order does not exist, is not owned by the customer, or a disallowed status transition is attempted
 */
export async function post__shoppingMallAiBackend_customer_orders_$orderId_orderStatusHistories(props: {
  customer: CustomerPayload,
  orderId: string & tags.Format<'uuid'>,
  body: IShoppingMallAiBackendOrderStatusHistory.ICreate
}): Promise<IShoppingMallAiBackendOrderStatusHistory> {
  const { customer, orderId, body } = props;

  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findFirst({
    where: {
      id: orderId,
      customer_id: customer.id,
      deleted_at: null,
    },
  });
  if (!order) throw new Error('Order not found or not owned by customer');

  // Allowable status transitions (expand as needed for business rules)
  const allowedTransitions: Record<string, string[]> = {
    'created': ['paid'],
    'paid': ['shipped'],
    'shipped': ['delivered'],
  };

  const isTransitionAllowed = allowedTransitions[body.previous_status]?.includes(body.new_status);
  if (!isTransitionAllowed) {
    throw new Error(`Illegal status transition: ${body.previous_status} → ${body.new_status}`);
  }

  // Insert new status history
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_order_status_histories.create({
    data: {
      id: v4(),
      order_id: orderId,
      previous_status: body.previous_status,
      new_status: body.new_status,
      actor_type: body.actor_type,
      actor_id: body.actor_id,
      event_context: body.event_context ?? null,
      occurred_at: body.occurred_at,
    },
  });

  return {
    id: created.id,
    order_id: created.order_id,
    previous_status: created.previous_status,
    new_status: created.new_status,
    actor_type: created.actor_type,
    actor_id: created.actor_id,
    event_context: created.event_context,
    occurred_at: created.occurred_at,
  };
}

