 *
 * 인증된 고객 사용자의 즐겨찾기 문의 목록을 필터링, 페이징하여 제공합니다. inquiry_id, 기간, 제목/본문 키워드, 페이지네이션 등 다양한 조건 검색이 가능합니다. 반환되는 데이터는 해당 고객의 즐겨찾기만이며, 삭제(해제)된 항목이나 타 고객의 데이터는 제외됩니다. 문의 제목/본문 검색은 관련 inquiry 테이블을 조인하여 처리합니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 정보(JWT 기반)
 * @param props.body - 검색, 필터, 페이지네이션 조건 DTO
 * @returns 페이징 정보를 포함한 즐겨찾기 문의 목록
 * @throws {Error} 인증/권한 문제가 있거나 파라미터 유효성 오류 시
 */
export async function patch__shoppingMallAiBackend_customer_favoriteInquiries(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendFavoriteInquiry.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendFavoriteInquiry> {
  const { customer, body } = props;
  const page: number = body.page ?? 1;
  const limit: number = body.limit ?? 20;

  // WHERE 조건 구성: 기본 필터
  const where: Record<string, any> = {
    customer_id: customer.id,
    deleted_at: null,
    ...(body.inquiry_id !== undefined && body.inquiry_id !== null && {
      inquiry_id: body.inquiry_id,
    }),
    // 날짜 조건은 아래에서 별도 처리
  };

  // created_at 범위 처리
  if (
    (body.from_date !== undefined && body.from_date !== null) ||
    (body.to_date !== undefined && body.to_date !== null)
  ) {
    where.created_at = {
      ...(body.from_date !== undefined && body.from_date !== null && {
        gte: body.from_date,
      }),
      ...(body.to_date !== undefined && body.to_date !== null && {
        lte: body.to_date,
      }),
    };
  }

  // 키워드 검색: 해당하는 inquiry의 id 목록 도출
  let inquiryIdFilter: string[] | undefined = undefined;
  if (body.query && body.query.trim().length > 0) {
    const inquired = await MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.findMany({
      where: {
        OR: [
          { title: { contains: body.query, mode: 'insensitive' as const } },
          { body: { contains: body.query, mode: 'insensitive' as const } },
        ],
      },
      select: { id: true },
    });
    inquiryIdFilter = inquired.map((i) => i.id);
  }

  // 전체 카운트/데이터 조회
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.count({
      where: {
        ...where,
        ...(inquiryIdFilter && inquiryIdFilter.length > 0 && {
          inquiry_id: { in: inquiryIdFilter },
        }),
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findMany({
      where: {
        ...where,
        ...(inquiryIdFilter && inquiryIdFilter.length > 0 && {
          inquiry_id: { in: inquiryIdFilter },
        }),
      },
      orderBy: { created_at: 'desc' },
      skip: (page - 1) * limit,
      take: limit,
    }),
  ]);

  return {
    pagination: {
      current: page as number & tags.Type<'int32'>,
      limit: limit as number & tags.Type<'int32'>,
      records: total as number & tags.Type<'int32'>,
      pages: (total === 0 ? 1 : Math.ceil(total / limit)) as number & tags.Type<'int32'>,
    },
    data: rows.map((row) => ({
      id: row.id,
      customer_id: row.customer_id,
      inquiry_id: row.inquiry_id,
      created_at: toISOStringSafe(row.created_at),
      deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    })),
  };
}

