/**
 * Records a new mileage transaction for a specified mileage wallet owned by any customer.
 *
 * This function performs all required business validations: ensures wallet existence (and not soft-deleted), prevents duplicate reference_id,
 * ensures no negative balances, and enforces admin authentication. The new transaction is created atomically, with all DateTime values handled
 * as ISO strings (`string & tags.Format<'date-time'>`).
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin payload (must be type "admin")
 * @param props.mileageWalletId - Mileage wallet UUID to associate with the transaction
 * @param props.body - Mileage transaction creation parameters (must include wallet_id, type, amount, optional reference and reason)
 * @returns The newly created transaction record (with audit-compliant fields)
 * @throws {Error} If mileage wallet does not exist, reference_id is duplicate for this wallet, or transaction would result in negative balance
 */
export async function post__shoppingMallAiBackend_admin_mileageWallets_$mileageWalletId_mileageTransactions(
  props: {
    admin: AdminPayload;
    mileageWalletId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendMileageTransaction.ICreate;
  },
): Promise<IShoppingMallAiBackendMileageTransaction> {
  const { admin, mileageWalletId, body } = props;
  // 1. Validate mileage wallet existence and not soft-deleted
  const wallet = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findFirst({
    where: { id: mileageWalletId, deleted_at: null },
  });
  if (!wallet) {
    throw new Error('Mileage wallet not found');
  }

  // 2. If reference_id is provided (not null), ensure no duplicate for this wallet
  if (body.reference_id !== undefined && body.reference_id !== null) {
    const refDup = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.findFirst({
      where: {
        wallet_id: mileageWalletId,
        reference_id: body.reference_id,
      },
    });
    if (refDup) {
      throw new Error('Duplicate reference_id for this wallet');
    }
  }

  // 3. Get previous balance (from the newest transaction) for this wallet
  const prevTx = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.findFirst({
    where: { wallet_id: mileageWalletId },
    orderBy: { created_at: 'desc' },
  });
  const prevBalance = prevTx ? prevTx.balance_after_transaction : 0;

  // 4. Compute the next balance
  const nextBalance = prevBalance + body.mileage_amount;
  if (nextBalance < 0) {
    throw new Error('Insufficient mileage balance');
  }

  // 5. Insert new transaction
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.create({
    data: {
      id: v4(), // v4() returns correct uuid type
      wallet_id: mileageWalletId,
      transaction_type: body.transaction_type,
      mileage_amount: body.mileage_amount,
      balance_after_transaction: nextBalance,
      reference_id: body.reference_id ?? null,
      transaction_reason: body.transaction_reason ?? null,
      created_at: now,
    },
  });
  // 6. Return response in DTO format
  return {
    id: created.id,
    wallet_id: created.wallet_id,
    transaction_type: created.transaction_type,
    mileage_amount: created.mileage_amount,
    balance_after_transaction: created.balance_after_transaction,
    reference_id: created.reference_id ?? null,
    transaction_reason: created.transaction_reason ?? null,
    created_at: now,
  };
}

