import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * 검색 및 필터를 통해 셀러 소유 주문의 요약 목록을 페이징 반환합니다.
 *
 * Advanced search and paginated order listing for seller's orders.
 * Returns only orders that have at least one item of a product owned by the authenticated seller.
 * Supports advanced filtering, sorting, and pagination as defined by the API spec.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller; only orders for products this seller owns will be returned
 * @param props.body - Search, filter, and paging request for customer orders
 * @returns Paginated summary of matching orders belonging to the seller
 * @throws {Error} When unauthorized access or query issue occurs
 */
export async function patch__shoppingMallAiBackend_seller_orders(
  props: {
    seller: SellerPayload;
    body: IShoppingMallAiBackendOrder.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendOrder.ISummary> {
  const { seller, body } = props;

  // Step 1: Find all relevant order IDs - the orders that contain at least one ordered item with a product owned by the seller
  const relevantOrderItems = await MyGlobal.prisma.shopping_mall_ai_backend_order_items.findMany({
    where: {
      product: {
        seller_id: seller.id,
      },
    },
    select: {
      order_id: true,
    },
  });
  const orderIds = Array.from(new Set(relevantOrderItems.map((x) => x.order_id)));
  if (orderIds.length === 0) {
    return {
      pagination: {
        current: body.page && body.page > 0 ? body.page : 1,
        limit: body.pageSize && body.pageSize > 0 ? body.pageSize : 20,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // Step 2: Build filters from request body
  const filters = {
    id: { in: orderIds },
    deleted_at: null,
    ...(body.order_number ? { order_number: { contains: body.order_number } } : {}),
    ...(body.customer_id ? { customer_id: body.customer_id } : {}),
    ...(body.current_status ? { current_status: body.current_status } : {}),
    ...(body.status_in && body.status_in.length > 0 ? { current_status: { in: body.status_in } } : {}),
    ...(body.total_amount_gte != null ? { total_amount: { gte: body.total_amount_gte } } : {}),
    ...(body.total_amount_lte != null ? { total_amount: { lte: body.total_amount_lte } } : {}),
    ...(body.currency_code ? { currency_code: body.currency_code } : {}),
    ...((body.created_at_gte || body.created_at_lte)
      ? {
          created_at: {
            ...(body.created_at_gte ? { gte: body.created_at_gte } : {}),
            ...(body.created_at_lte ? { lte: body.created_at_lte } : {}),
          },
        }
      : {}),
  };

  // Step 3: Pagination
  const page = body.page && body.page > 0 ? body.page : 1;
  const pageSize = body.pageSize && body.pageSize > 0 ? body.pageSize : 20;
  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // Step 4: Sorting
  let orderBy: Record<string, 'asc' | 'desc'> = { created_at: 'desc' };
  if (body.sort) {
    if (body.sort === '-created_at') orderBy = { created_at: 'desc' };
    else if (body.sort === 'created_at') orderBy = { created_at: 'asc' };
    else if (body.sort === 'total_amount') orderBy = { total_amount: 'asc' };
    else if (body.sort === '-total_amount') orderBy = { total_amount: 'desc' };
  }

  // Step 5: Query total and paginated rows
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_orders.count({ where: filters }),
    MyGlobal.prisma.shopping_mall_ai_backend_orders.findMany({
      where: filters,
      orderBy,
      skip,
      take,
      select: {
        id: true,
        order_number: true,
        current_status: true,
        total_amount: true,
        currency_code: true,
        customer_id: true,
        created_at: true,
      },
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data: rows.map((row) => ({
      id: row.id,
      order_number: row.order_number,
      current_status: row.current_status,
      total_amount: row.total_amount,
      currency_code: row.currency_code,
      customer_id: row.customer_id,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

