/**
 * Search and paginate through seller onboarding event records for regulatory, compliance, and operational visibility on the path to seller activation.
 *
 * Only the seller themselves (matching sellerId) can query their onboarding history.
 * Supports filtering, sorting, and pagination. Compliance with all type branding and date conversion rules.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller making the request (must match sellerId)
 * @param props.sellerId - Seller account UUID to retrieve onboarding history for
 * @param props.body - Search/filter/paging criteria for the onboarding history
 * @returns Paginated onboarding milestone summaries for the seller
 * @throws {Error} When the authenticated seller does not match sellerId (authorization failure)
 */
export async function patch__shoppingMallAiBackend_seller_sellers_$sellerId_onboardings(props: {
  seller: SellerPayload;
  sellerId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendSellerOnboarding.IRequest;
}): Promise<IPageIShoppingMallAiBackendSellerOnboarding.ISummary> {
  const { seller, sellerId, body } = props;

  if (seller.id !== sellerId) {
    throw new Error("Unauthorized: Cannot access another seller's onboarding history");
  }

  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Prisma where clause (inline)
  const where = {
    seller_id: sellerId,
    deleted_at: null,
    ...(body.step_code !== undefined && body.step_code !== null && {
      step_code: body.step_code,
    }),
    ...(body.step_status !== undefined && body.step_status !== null && {
      step_status: body.step_status,
    }),
    ...(body.approved_by !== undefined && body.approved_by !== null && {
      approved_by: body.approved_by,
    }),
    ...((body.occurred_from !== undefined && body.occurred_from !== null) ||
    (body.occurred_to !== undefined && body.occurred_to !== null)
      ? {
          occurred_at: {
            ...(body.occurred_from !== undefined && body.occurred_from !== null && {
              gte: body.occurred_from,
            }),
            ...(body.occurred_to !== undefined && body.occurred_to !== null && {
              lte: body.occurred_to,
            }),
          },
        }
      : {}),
  };

  // Allowed order fields only
  const allowedOrderFields = [
    "occurred_at",
    "step_code",
    "step_status",
    "approved_by",
  ];
  const orderByField =
    body.orderBy && allowedOrderFields.includes(body.orderBy) ? body.orderBy : "occurred_at";
  const orderDir = body.orderDir === "asc" ? "asc" : "desc";

  // Parallel queries for total and data
  const [total, rows] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_seller_onboardings.count({ where }),
    MyGlobal.prisma.shopping_mall_ai_backend_seller_onboardings.findMany({
      where,
      orderBy: { [orderByField]: orderDir },
      skip,
      take: limit,
    }),
  ]);

  const data = rows.map(
    (row): IShoppingMallAiBackendSellerOnboarding.ISummary => ({
      id: row.id,
      seller_id: row.seller_id,
      step_code: row.step_code,
      step_status: row.step_status,
      approved_by: row.approved_by ?? null,
      occurred_at: toISOStringSafe(row.occurred_at),
      note: row.note ?? null,
      created_at: toISOStringSafe(row.created_at),
      updated_at: toISOStringSafe(row.updated_at),
    })
  );

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

