/**
 * Retrieve the details of a specific order item by both the parent order's and the item's identifiers.
 *
 * Returns comprehensive information pertaining to the selected item including product reference, snapshot, quantity, price, and audit fields.
 *
 * This enables full traceability for review, refund/return processes, product delivery, or dispute resolution. All accesses are audited for security and business compliance. Errors are returned if the item or order context is not found or access is denied.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller performing the lookup
 * @param props.orderId - Unique identifier (UUID) of the parent order
 * @param props.orderItemId - Unique identifier (UUID) of the order item to retrieve
 * @returns The comprehensive order item details including product ref, quantity, pricing, and audit fields.
 * @throws {Error} When the order item is not found, not in the specified order, or seller does not own the product
 */
export async function get__shoppingMallAiBackend_seller_orders_$orderId_orderItems_$orderItemId(
  props: {
    seller: SellerPayload;
    orderId: string & tags.Format<'uuid'>;
    orderItemId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendOrderItem> {
  const { seller, orderId, orderItemId } = props;
  const orderItem = await MyGlobal.prisma.shopping_mall_ai_backend_order_items.findUnique({
    where: { id: orderItemId },
  });
  if (!orderItem || orderItem.order_id !== orderId)
    throw new Error("Order item not found in specified order");

  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: orderItem.product_id },
  });
  if (!product || product.seller_id !== seller.id)
    throw new Error("Forbidden: seller does not own this order item");

  return {
    id: orderItem.id,
    order_id: orderItem.order_id,
    product_id: orderItem.product_id,
    product_snapshot_id: orderItem.product_snapshot_id,
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    currency_code: orderItem.currency_code,
    note: orderItem.note ?? null,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
    deleted_at: orderItem.deleted_at ? toISOStringSafe(orderItem.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
