/**
 * Register a new seller account and issue JWT (shopping_mall_ai_backend_sellers).
 *
 * This registration endpoint allows a new seller to create an account by providing essential credentials: email (unique identifier), password (stored as password_hash), company profile (company_name, business_number, representative_name), address, and phone. Upon successful registration, the system issues JWT tokens (embedded in the setHeaders field in the response) for session management.
 *
 * Uniqueness is enforced for email and business_number fields. The password is securely hashed using the Web Crypto API (SHA-256). If an existing seller is found with the same email or business_number, an error is thrown. JWT is simulated in this implementation—replace with actual JWT logic in production.
 *
 * @param props - Sign up payload with credential and company profile fields
 * @returns Seller auth registration response including JWT (setHeaders) and registered seller profile
 * @throws {Error} 이미 사용중인 이메일입니다. (When the email is already registered)
 * @throws {Error} 이미 등록된 사업자등록번호입니다. (When the business number is already registered)
 */
export async function post__auth_seller_register(
  props: { body: ISellerAuth.SignUp }
): Promise<ISellerAuth.AuthResponseWithHeaders> {
  const { body } = props;

  // 1. Email uniqueness check
  const existingEmail = await MyGlobal.prisma.shopping_mall_ai_backend_sellers.findFirst({
    where: { email: body.email, deleted_at: null }
  });
  if (existingEmail) throw new Error('이미 사용중인 이메일입니다.');

  // 2. Business number uniqueness check
  const existingBizNum = await MyGlobal.prisma.shopping_mall_ai_backend_sellers.findFirst({
    where: { business_number: body.businessNumber, deleted_at: null }
  });
  if (existingBizNum) throw new Error('이미 등록된 사업자등록번호입니다.');

  // 3. Secure password hash (WebCrypto SHA-256)
  const passwordHash = await hashPasswordWebCrypto(body.password);

  // 4. Prepare IDs and timestamps
  const now = toISOStringSafe(new Date());
  const id = v4() as string & tags.Format<'uuid'>;

  // 5. Insert seller record
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_sellers.create({
    data: {
      id: id,
      email: body.email,
      password_hash: passwordHash,
      company_name: body.companyName,
      business_number: body.businessNumber,
      representative_name: body.representativeName,
      address: body.address,
      phone: body.phone,
      status: 'active',
      email_verified: false,
      joined_at: now,
      created_at: now,
      updated_at: now
    }
  });

  // 6. Simulate JWT issuance (replace with actual JWT code in production)
  const jwt = await simulateGenerateJwt({ id, email: created.email });
  const setHeaders = { Authorization: `Bearer ${jwt}` };

  // 7. Return API contract response (no secrets exposed)
  return {
    jwt,
    sellerId: id,
    email: created.email,
    companyName: created.company_name,
    businessNumber: created.business_number,
    status: created.status,
    emailVerified: created.email_verified,
    setHeaders
  };
}

// Secure browser-compatible SHA-256 password hash
async function hashPasswordWebCrypto(password: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hashBuffer))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

// Simulated JWT issuance (replace with production implementation)
async function simulateGenerateJwt(claims: { id: string; email: string }): Promise<string> {
  return typia.random<string>();
}

