  const page = body.page && body.page > 0 ? body.page : 1;
  const limit = body.limit && body.limit > 0 ? body.limit : 20;
  const skip = (page - 1) * limit;

  // Query data and count in parallel
  const [data, records] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_category_map.findMany({
      where,
      skip,
      take: limit,
      orderBy: { id: 'asc' },
      select: { id: true, product_id: true, category_id: true, primary: true }
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_category_map.count({ where })
  ]);

  const pages = records === 0 ? 1 : Math.ceil(records / limit);
  return {
    pagination: {
