 * @param props.body - Current and new password for the password change operation
 * @returns ISellerAuth.ChangePasswordResponse indicating success and optional message
 * @throws {Error} When seller is not active/deleted, current password mismatches, or new password fails validation
 */
export async function put__auth_seller_password(
  props: {
    seller: SellerPayload;
    body: ISellerAuth.ChangePassword;
  }
): Promise<ISellerAuth.ChangePasswordResponse> {
  const { seller, body } = props;

  // 1. Fetch seller with status active and not deleted
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_sellers.findFirst({
    where: {
      id: seller.id,
      status: "active",
      deleted_at: null,
    }
  });
  if (!existing) throw new Error("Seller not found or not active.");

  // 2. Validate currentPassword
  const validCurrent = await verifyPassword(body.currentPassword, existing.password_hash);
  if (!validCurrent) throw new Error("Current password is incorrect.");

  // 3. Password policy enforcement
  if (!validatePasswordPolicy(body.newPassword)) {
    throw new Error("New password does not meet security requirements (min 8 chars, letter/number/special).");
  }
  if (body.newPassword === body.currentPassword) {
    throw new Error("New password cannot be the same as current password.");
  }

  // 4. Hash new password, update password_hash
  const newPasswordHash = await hashPassword(body.newPassword);
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_sellers.update({
    where: { id: seller.id },
    data: {
      password_hash: newPasswordHash,
      updated_at: now,
    },
  });

  // 5. Insert audit log in seller_histories
  await MyGlobal.prisma.shopping_mall_ai_backend_seller_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      seller_id: seller.id,
      event_type: "password_changed",
      old_value_json: JSON.stringify({ password_hash: existing.password_hash }),
      new_value_json: JSON.stringify({ password_hash: newPasswordHash }),
      triggered_by: seller.id,
      occurred_at: now,
      created_at: now,
    }
  });

  return {
    success: true,
    message: "Password updated successfully.",
  };
}

/**
 * Hash a password using Web Crypto API (browser-native, PBKDF2, SHA-256, 100,000 iterations)
 * @param password Plaintext password
 * @returns The password hash string (base64 encoded salt + hash)
 */
async function hashPassword(password: string): Promise<string> {
  const encoder = new TextEncoder();
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const passwordKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"]
  );
  const hashBuffer = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    passwordKey,
    256
  );
  // Base64-salt + ":" + Base64-hash
  const base64Salt = btoa(String.fromCharCode(...salt));
  const base64Hash = btoa(String.fromCharCode(...new Uint8Array(hashBuffer)));
  return `${base64Salt}:${base64Hash}`;
}

/**
 * Verify a password against salted hash
 * @param password Plaintext password
 * @param hash Hash string from database (base64salt:base64hash)
 * @returns True if passwords match
 */
async function verifyPassword(password: string, hash: string): Promise<boolean> {
  if (!hash.includes(":")) return false;
  const [base64Salt, base64Hash] = hash.split(":");
  const salt = Uint8Array.from(atob(base64Salt), c => c.charCodeAt(0));
  const targetHash = Uint8Array.from(atob(base64Hash), c => c.charCodeAt(0));
  const encoder = new TextEncoder();
  const passwordKey = await crypto.subtle.importKey(
    "raw",
    encoder.encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"]
  );
  const hashBuffer = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    passwordKey,
    256
  );
  const computed = new Uint8Array(hashBuffer);
  // Constant-time comparison
  return computed.length === targetHash.length && computed.every((b, i) => b === targetHash[i]);
}

/**
 * Checks password meets policy (min 8 chars, at least 1 letter, 1 number, 1 special)
 */
function validatePasswordPolicy(password: string): boolean {
  if (password.length < 8) return false;
  if (!/[A-Za-z]/.test(password)) return false;
  if (!/[0-9]/.test(password)) return false;
  if (!/[^A-Za-z0-9]/.test(password)) return false;
  return true;
}

