 * Returns the updated transaction record with full details.
 *
 * @param props - Request payload including admin authentication, coinWalletId, coinTransactionId, and body
 * @param props.admin - The authenticated admin user (must have type 'admin')
 * @param props.coinWalletId - The UUID of the coin wallet containing the transaction
 * @param props.coinTransactionId - The UUID of the coin transaction to update
 * @param props.body - Payload containing only transaction_reason (optional)
 * @returns The updated IShoppingMallAiBackendCoinTransaction object
 * @throws {Error} If the transaction is not found or admin is unauthorized
 */
export async function put__shoppingMallAiBackend_admin_coinWallets_$coinWalletId_coinTransactions_$coinTransactionId(
  props: {
    admin: AdminPayload;
    coinWalletId: string & tags.Format<'uuid'>;
    coinTransactionId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendCoinTransaction.IUpdate;
  }
): Promise<IShoppingMallAiBackendCoinTransaction> {
  const { admin, coinWalletId, coinTransactionId, body } = props;

  // Authorization: ensure admin is authenticated and of correct type
  if (!admin || admin.type !== 'admin') {
    throw new Error('Unauthorized: Admin credentials required');
  }

  // Find the target transaction (compound key: wallet_id + id)
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_coin_transactions.findFirst({
    where: {
      id: coinTransactionId,
      wallet_id: coinWalletId,
    },
  });
