    id: updated.id,
    wallet_id: updated.wallet_id,
    transaction_type: updated.transaction_type,
    transaction_amount: updated.transaction_amount,
    balance_after_transaction: updated.balance_after_transaction,
    reference_id: updated.reference_id ?? null,
    transaction_reason: updated.transaction_reason ?? null,
    created_at: toISOStringSafe(updated.created_at),
  };
}

