/**
 * Create a new stock entry for a product option (shopping_mall_ai_backend_product_option_stocks).
 *
 * Creates a single new product option stock record, including required fields like stock_count, status, and any business constraints such as unique product_option_id per stock. 
 * All inserts validated for referential integrity and uniqueness. Authorization enforced such that only sellers owning the product may add stock for its options.
 *
 * Failure to find parent option, or duplicate/block violation, returns error. Only the owning seller is permitted; any unauthorized or invalid request is rejected.
 *
 * @param props - Properties object
 * @param props.seller - The authenticated SellerPayload of the calling seller
 * @param props.productOptionId - UUID of the product option to add stock to
 * @param props.body - Request body with all required and optional fields for new stock
 * @returns The created product option stock record including all fields
 * @throws {Error} When parent option is not found, seller does not own the product, or duplicate stock exists for this option
 */
export async function post__shoppingMallAiBackend_seller_productOptions_$productOptionId_productOptionStocks(
  props: {
    seller: SellerPayload;
    productOptionId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductOptionStock.ICreate;
  }
): Promise<IShoppingMallAiBackendProductOptionStock> {
  const { seller, productOptionId, body } = props;

  // 1. Lookup option and verify ownership
  const option = await MyGlobal.prisma.shopping_mall_ai_backend_product_options.findFirst({
    where: { id: productOptionId, deleted_at: null },
    select: { id: true, product_id: true },
  });
  if (!option) throw new Error("Product option not found");
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: { id: option.product_id, deleted_at: null },
    select: { id: true, seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error("Unauthorized: Only the product seller can add stock to this option");
  }

  // 2. Check for uniqueness: one stock per option
  const existingStock = await MyGlobal.prisma.shopping_mall_ai_backend_product_option_stocks.findFirst({
    where: { product_option_id: productOptionId, deleted_at: null },
    select: { id: true },
  });
  if (existingStock) {
    throw new Error("Duplicate: Stock for this option already exists");
  }

  // 3. Insert new stock
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_product_option_stocks.create({
    data: {
      id: v4(),
      product_option_id: productOptionId,
      stock_count: body.stock_count,
      safety_stock: body.safety_stock ?? null,
      inbound_count: body.inbound_count ?? null,
      warehouse_location: body.warehouse_location ?? null,
      status: body.status,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });

  // 4. Return fully typed, date-converted object per API contract
  return {
    id: created.id,
    product_option_id: created.product_option_id,
    stock_count: created.stock_count,
    safety_stock: created.safety_stock,
    inbound_count: created.inbound_count,
    warehouse_location: created.warehouse_location,
    status: created.status,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

