import { IShoppingMallAiBackendCoinWallet } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCoinWallet";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Create a new coin wallet attached to a specified owner (admin, seller, or customer).
 *
 * - Validates that wallet_address is unique across all coin wallets.
 * - Validates that only one wallet exists per (owner, type) pair.
 * - Only admins can use this operation (admin: AdminPayload required).
 * - Mutually exclusive owner fields are enforced: exactly one of wallet_owner_customer_id, wallet_owner_seller_id, or wallet_owner_admin_id must be provided (not more or less).
 * - Both required and optional fields conform to schema, all timestamps are formatted and branded as string & tags.Format<'date-time'>.
 *
 * @param props -
 *   admin: The authenticated admin performing this request.
 *   body: The wallet creation payload as IShoppingMallAiBackendCoinWallet.ICreate
 * @returns IShoppingMallAiBackendCoinWallet - The created wallet with all fields as per the schema.
 * @throws {Error} If input is invalid or uniqueness constraints are violated.
 */
export async function post__shoppingMallAiBackend_admin_coinWallets(
  props: { admin: AdminPayload; body: IShoppingMallAiBackendCoinWallet.ICreate }
): Promise<IShoppingMallAiBackendCoinWallet> {
  const { admin, body } = props;

  // Validate that only ONE owner field is supplied
  const ownerFields = [body.wallet_owner_customer_id, body.wallet_owner_seller_id, body.wallet_owner_admin_id];
  const ownerCount = ownerFields.filter((v) => v !== undefined && v !== null).length;
  if (ownerCount !== 1) {
    throw new Error('Exactly one of wallet_owner_customer_id, wallet_owner_seller_id, or wallet_owner_admin_id must be specified and not null');
  }

  // Validate unique wallet_address
  const addressExists = await MyGlobal.prisma.shopping_mall_ai_backend_coin_wallets.findFirst({
    where: { wallet_address: body.wallet_address },
    select: { id: true }
  });
  if (addressExists) {
    throw new Error('A coin wallet with this wallet_address already exists');
  }

  // Validate unique (owner, wallet_type) combination
  const ownerWhere: Record<string, unknown> = {
    wallet_type: body.wallet_type
  };
  if (body.wallet_owner_customer_id != null) {
    ownerWhere.wallet_owner_customer_id = body.wallet_owner_customer_id;
  }
  if (body.wallet_owner_seller_id != null) {
    ownerWhere.wallet_owner_seller_id = body.wallet_owner_seller_id;
  }
  if (body.wallet_owner_admin_id != null) {
    ownerWhere.wallet_owner_admin_id = body.wallet_owner_admin_id;
  }
  const ownerTypeExists = await MyGlobal.prisma.shopping_mall_ai_backend_coin_wallets.findFirst({
    where: ownerWhere,
    select: { id: true }
  });
  if (ownerTypeExists) {
    throw new Error('A coin wallet with this owner and wallet_type already exists');
  }

  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_coin_wallets.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      wallet_owner_customer_id: body.wallet_owner_customer_id ?? null,
      wallet_owner_seller_id: body.wallet_owner_seller_id ?? null,
      wallet_owner_admin_id: body.wallet_owner_admin_id ?? null,
      wallet_type: body.wallet_type,
      wallet_status: body.wallet_status,
      wallet_address: body.wallet_address,
      wallet_label: body.wallet_label ?? null,
      security_code: body.security_code ?? null,
      created_at: now,
      updated_at: now,
      deleted_at: null
    }
  });

  return {
    id: created.id,
    wallet_owner_customer_id: created.wallet_owner_customer_id,
    wallet_owner_seller_id: created.wallet_owner_seller_id,
    wallet_owner_admin_id: created.wallet_owner_admin_id,
    wallet_type: created.wallet_type,
    wallet_status: created.wallet_status,
    wallet_address: created.wallet_address,
    wallet_label: created.wallet_label,
    security_code: created.security_code,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendProductChannelMap } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductChannelMap";
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Creates a new mapping between a product and a sales channel for a seller.
 *
 * This endpoint ensures the authenticated seller owns the target product, then
 * creates a new mapping to the given channel. Uniqueness of (product_id, channel_id)
 * is enforced at the database level. As the underlying schema does not provide
 * created_at/updated_at fields, this implementation sets these to the current
 * timestamp as a workaround to conform to the API contract.
 *
 * @param props -
 *   @field seller The authenticated seller creating the channel mapping.
 *   @field productId The UUID of the product to map.
 *   @field body The input with channel_id and optional status.
 * @returns The created product-channel mapping object.
 * @throws {Error} If the product does not exist, is not owned by the seller,
 *   is deleted, or if the mapping already exists (unique constraint violation).
 */
export async function post__shoppingMallAiBackend_seller_products_$productId_productChannelMap(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductChannelMap.ICreate;
  }
): Promise<IShoppingMallAiBackendProductChannelMap> {
  const { seller, productId, body } = props;

  // 1. Authorization: owner check
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: productId,
      seller_id: seller.id,
      deleted_at: null,
    },
  });
  if (!product) throw new Error('Product not found or not owned by seller.');

  // 2. Attempt to create the mapping (unique constraint at DB level)
  const now = toISOStringSafe(new Date()); // string & tags.Format<'date-time'>
  let created;
  try {
    created = await MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.create({
      data: {
        id: v4() as string & tags.Format<'uuid'>,
        product_id: productId,
        channel_id: body.channel_id,
        status: body.status ?? 'active',
      },
    });
  } catch (err) {
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2002') {
      throw new Error('Mapping of this product and channel already exists.');
    }
    throw err;
  }

  // 3. Build DTO, simulating audit fields to match IShoppingMallAiBackendProductChannelMap
  return {
    id: created.id,
    product_id: created.product_id,
    channel_id: created.channel_id,
    status: created.status,
    created_at: now, // workaround for schema-DTO mismatch
    updated_at: now,
  };
}

