/**
 * 즐겨찾기 스냅샷 레코드를 ID로 업데이트합니다. (관리자 한정)
 *
 * 이 엔드포인트는 관리자 권한으로 즐겨찾기 스냅샷의 직렬화된 객체 콘텐츠(serialized_object)만 교정 또는 복원할 수 있도록 허용합니다.
 * 생성시각 및 ID 등 불변 필드는 절대 변경할 수 없습니다. 허용되지 않은 필드의 변경 시도는 거부됩니다.
 * 스냅샷이 존재하지 않으면 예외를 반환합니다.
 *
 * @param props - 요청 프로퍼티
 * @param props.admin - 인증된 관리자 페이로드
 * @param props.favoriteSnapshotId - 업데이트할 즐겨찾기 스냅샷의 UUID
 * @param props.body - 수정되는 스냅샷 직렬화 내용 (허용 필드만 입력)
 * @returns 업데이트된 즐겨찾기 스냅샷 레코드
 * @throws {Error} 스냅샷이 존재하지 않거나 업데이트 불가 필드가 포함된 경우
 */
export async function put__shoppingMallAiBackend_admin_favoriteSnapshots_$favoriteSnapshotId(
  props: {
    admin: AdminPayload;
    favoriteSnapshotId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendFavoriteSnapshot.IUpdate;
  }
): Promise<IShoppingMallAiBackendFavoriteSnapshot> {
  const { admin, favoriteSnapshotId, body } = props;

  // 입력 필드 검증: 오직 serialized_object만 허용
  if (Object.keys(body).some(key => key !== 'serialized_object')) {
    throw new Error('Invalid fields in body: only serialized_object may be updated');
  }
  if ('serialized_object' in body && typeof body.serialized_object !== 'string') {
    throw new Error('`serialized_object` must be a string');
  }

  // 기존 스냅샷 존재 여부 확인
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_snapshots.findUnique({
    where: { id: favoriteSnapshotId }
  });
  if (!snapshot) throw new Error('Favorite snapshot not found');

  // 실제 업데이트
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_snapshots.update({
    where: { id: favoriteSnapshotId },
    data: { serialized_object: body.serialized_object },
  });

  return {
    id: updated.id,
    favorite_product_id: updated.favorite_product_id,
    favorite_inquiry_id: updated.favorite_inquiry_id,
    favorite_address_id: updated.favorite_address_id,
    target_type: updated.target_type as "PRODUCT" | "INQUIRY" | "ADDRESS",
    snapshot_object_id: updated.snapshot_object_id,
    serialized_object: updated.serialized_object,
    created_at: toISOStringSafe(updated.created_at)
  };
}

