import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * 업데이트: 관리자가 고객 정보를 수정합니다 (관리자 인증 필요).
 *
 * 본 엔드포인트는 관리자 권한으로 쇼핑몰 고객의 프로필을 전면 수정할 수 있습니다.
 * 입력된 모든 필드는 비즈니스 규칙(이메일 중복, 휴대폰 형식 등)에 따라 검증됩니다.
 * 수정이 성공적으로 이뤄지면 고객 이력 테이블에 스냅샷 기록이 남으며, 변경된 고객 정보를 반환합니다.
 *
 * @param props - 요청 속성
 * @param props.admin - 인증된 관리자 페이로드
 * @param props.body - 고객 정보 전체 업데이트 DTO (IShoppingMallAiBackendCustomer.IUpdate)
 * @returns 변경된 고객 정보를 반환합니다.
 * @throws {Error} 존재하지 않거나 삭제된 고객, 이메일 중복, 전화번호 검증 실패시 에러 발생
 */
export async function put__shoppingMallAiBackend_admin_customers(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendCustomer.IUpdate;
  }
): Promise<IShoppingMallAiBackendCustomer> {
  const { admin, body } = props;

  // 1. 수정 대상 고객 조회 (소프트삭제된 계정 허용 X)
  const customer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: { id: body.id, deleted_at: null },
  });
  if (!customer) throw new Error('해당 고객이 존재하지 않거나 이미 삭제되었습니다');

  // 2. 이메일 중복 체크 (입력된 경우에만, 본인 제외)
  if (body.email && body.email !== customer.email) {
    const overlap = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
      where: {
        email: body.email,
        deleted_at: null,
        id: { not: body.id },
      },
    });
    if (overlap) throw new Error('해당 이메일은 이미 다른 고객에 의해 사용 중입니다');
  }

  // 3. 휴대폰 번호 형식 검증 (국제번호: +821012341234 등 7~15자리 숫자/기호)
  if (body.phone && !/^\+?\d{7,15}$/.test(body.phone)) {
    throw new Error('휴대폰 번호 형식이 올바르지 않습니다.');
  }

  // 4. 실제 업데이트 적용 (입력된 값만 갱신)
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  const updateFields = {
    email: body.email ?? undefined,
    name: body.name ?? undefined,
    nickname: body.nickname ?? undefined,
    phone: body.phone ?? undefined,
    profile_image_uri: body.profile_image_uri ?? undefined,
    status: body.status ?? undefined,
    email_verified: body.email_verified ?? undefined,
    phone_verified: body.phone_verified ?? undefined,
    updated_at: now,
  };

  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_customers.update({
    where: { id: body.id },
    data: updateFields,
  });

  // 5. 변경 스냅샷(이력) 기록: 이전/이후 전체값 JSON 기반
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      customer_id: customer.id,
      event_type: 'update',
      old_value_json: JSON.stringify(customer),
      new_value_json: JSON.stringify({ ...customer, ...updateFields }),
      triggered_by: admin.id,
      meta_json: null,
      occurred_at: now,
      created_at: now,
    },
  });

  // 6. 반환: 응답 모든 날짜 속성 ISO 문자열 변환
  return {
    id: updated.id,
    email: updated.email,
    name: updated.name,
    nickname: updated.nickname,
    phone: updated.phone,
    profile_image_uri: updated.profile_image_uri ?? null,
    status: updated.status,
    email_verified: updated.email_verified,
    phone_verified: updated.phone_verified,
    joined_at: toISOStringSafe(updated.joined_at),
    last_login_at: updated.last_login_at ? toISOStringSafe(updated.last_login_at) : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import { IPageIShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendMileageTransaction";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Paginated, filtered search of mileage transactions for a wallet (admin-only).
 *
 * Retrieves a filtered and paginated collection of all mileage transactions linked to the specified wallet.
 * Supports advanced filtering (transaction_type, amount, date range), sorting, and pagination.
 * Only wallet owners and authorized admins can perform this operation.
 *
 * @param props - The request properties.
 * @param props.admin - Authenticated admin user payload.
 * @param props.mileageWalletId - Target mileage wallet's unique identifier.
 * @param props.body - Search and filter criteria, sort, and pagination instructions.
 * @returns A paginated set of mileage transactions for the requested wallet.
 * @throws {Error} If the wallet does not exist or is deleted.
 */
export async function patch__shoppingMallAiBackend_admin_mileageWallets_$mileageWalletId_mileageTransactions(props: {
  admin: AdminPayload;
  mileageWalletId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendMileageTransaction.IRequest;
}): Promise<IPageIShoppingMallAiBackendMileageTransaction> {
  const { admin, mileageWalletId, body } = props;

  // 1. Validate wallet existence (not deleted)
  const wallet = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findFirst({
    where: { id: mileageWalletId, deleted_at: null }
  });
  if (!wallet) throw new Error('Wallet not found');

  // 2. Build filters
  const queryWhere = {
    wallet_id: mileageWalletId,
    ...(body.transaction_type && { transaction_type: body.transaction_type }),
    ...(body.min_amount !== undefined || body.max_amount !== undefined
      ? {
          mileage_amount: {
            ...(body.min_amount !== undefined && { gte: body.min_amount }),
            ...(body.max_amount !== undefined && { lte: body.max_amount })
          }
        }
      : {}),
    ...(body.created_from !== undefined || body.created_to !== undefined
      ? {
          created_at: {
            ...(body.created_from !== undefined && { gte: body.created_from }),
            ...(body.created_to !== undefined && { lte: body.created_to })
          }
        }
      : {})
  };

  // 3. Pagination
  const page = body.page && body.page > 0 ? body.page : 1;
  const page_size = body.page_size && body.page_size > 0 ? body.page_size : 20;
  const skip = (page - 1) * page_size;
  const take = page_size;

  // 4. Sorting (allow only known fields)
  const validSortFields = new Set(['created_at', 'mileage_amount', 'balance_after_transaction']);
  const sortField = body.sort_by && validSortFields.has(body.sort_by) ? body.sort_by : 'created_at';
  const sortOrder = body.sort_order === 'asc' ? 'asc' : 'desc';

  // 5. Query data and count total concurrently
  const [records, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.findMany({
      where: queryWhere,
      orderBy: { [sortField]: sortOrder },
      skip,
      take
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.count({ where: queryWhere })
  ]);

  // 6. Map results, converting all dates to string & tags.Format<'date-time'>
  return {
    pagination: {
      current: page,
      limit: page_size,
      records: total,
      pages: Math.ceil(total / page_size)
    },
    data: records.map(trx => ({
      id: trx.id,
      wallet_id: trx.wallet_id,
      transaction_type: trx.transaction_type,
      mileage_amount: trx.mileage_amount,
      balance_after_transaction: trx.balance_after_transaction,
      reference_id: trx.reference_id ?? null,
      transaction_reason: trx.transaction_reason ?? null,
      created_at: toISOStringSafe(trx.created_at)
    }))
  };
}

