  body: IShoppingMallAiBackendProductOptionStock.IRequest;
}): Promise<IPageIShoppingMallAiBackendProductOptionStock.ISummary> {
  const { seller, productOptionId, body } = props;

  // 1. Ownership check: the option must belong to a product of this seller
  const optionCheck = await MyGlobal.prisma.shopping_mall_ai_backend_product_options.findFirst({
    where: {
      id: productOptionId,
      deleted_at: null,
      product: {
        seller_id: seller.id,
        deleted_at: null,
      },
    },
  });
  if (!optionCheck) throw new Error('Unauthorized: This option does not belong to your products.');

