  const filter = body?.filter ?? {};
  const where: Record<string, unknown> = {
    product_option_id: productOptionId,
    // Soft deletion handling: only deleted if filter.deleted === true, only active if deleted === false/undefined
    ...(filter.deleted === true
      ? { deleted_at: { not: null } }
      : { deleted_at: null }),
    ...(filter.productOptionStockId && { id: filter.productOptionStockId }),
    ...(filter.status && { status: filter.status }),
