            ...(filter.createdFrom && { gte: filter.createdFrom }),
            ...(filter.createdTo && { lte: filter.createdTo }),
          },
        }
      : {}),
  };

  // 3. Search (simple contains on warehouse_location and status, case-insensitive)
  const search = body?.search ?? '';
  if (search) {
    where.OR = [
      { warehouse_location: { contains: search, mode: 'insensitive' as const } },
      { status: { contains: search, mode: 'insensitive' as const } },
    ];
  }

  // 4. Sorting (default to created_at desc)
  const sortArr = (body?.sort && body.sort.length > 0)
    ? body.sort
    : [{ field: 'created_at', direction: 'desc' as const }];

  // 5. Pagination
  const page = body?.page ?? 1;
  const pageSize = body?.pageSize ?? 20;
  const skip = (page - 1) * pageSize;
  const take = pageSize;

  // 6. Query paginated records and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_option_stocks.findMany({
      where,
      orderBy: sortArr.map(sort => ({ [sort.field]: sort.direction })),
      skip,
      take,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_option_stocks.count({ where }),
  ]);

  // 7. Transform to DTO with ISO datetime fields correctly
  return {
    pagination: {
      current: page,
      limit: pageSize,
      records: total,
      pages: Math.ceil(total / pageSize),
    },
    data: rows.map(row => ({
      id: row.id,
      product_option_id: row.product_option_id,
      stock_count: row.stock_count,
      safety_stock: row.safety_stock ?? null,
