/**
 * Search and paginate seller onboarding event records for a specific seller (admin access only).
 *
 * This endpoint allows an authenticated admin to query onboarding milestone events for a target seller account.
 * Supports filtering by onboarding step code, milestone status, reviewer/admin, time range, and paginates the results.
 * Only accessible to admins; soft-deleted records (deleted_at not null) are excluded. All date fields are normalized to ISO strings.
 *
 * @param props - Request props object
 * @param props.admin - Authenticated admin payload
 * @param props.sellerId - Target seller account UUID
 * @param props.body - Filtering and paging parameters (step_code, step_status, etc)
 * @returns Paginated onboarding milestone records for the given seller
 * @throws {Error} If authentication or DB query fails
 */
export async function patch__shoppingMallAiBackend_admin_sellers_$sellerId_onboardings(props: {
  admin: AdminPayload;
  sellerId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendSellerOnboarding.IRequest;
}): Promise<IPageIShoppingMallAiBackendSellerOnboarding.ISummary> {
  const { admin, sellerId, body } = props;

  // Parse and normalize filter/input parameters
  const {
    step_code,
    step_status,
    approved_by,
    occurred_from,
    occurred_to,
    page = 1,
    limit = 20,
    orderBy = 'occurred_at',
    orderDir = 'desc',
  } = body ?? {};

  // Only allow sorting by these fields
  const allowedOrderFields = [
    'occurred_at','created_at','updated_at','step_code','step_status',
  ];
  const sortField = allowedOrderFields.includes(orderBy ?? '') ? orderBy! : 'occurred_at';
  const sortDir = orderDir === 'asc' ? 'asc' : 'desc';
  const skip = ((page ?? 1) - 1) * (limit ?? 20);
  const take = limit ?? 20;

  // Build WHERE filter inline
  const where = {
    deleted_at: null,
    seller_id: sellerId,
    ...(step_code !== undefined && step_code !== null && { step_code }),
    ...(step_status !== undefined && step_status !== null && { step_status }),
    ...(approved_by !== undefined && approved_by !== null && { approved_by }),
    ...((occurred_from !== undefined && occurred_from !== null) || (occurred_to !== undefined && occurred_to !== null)
      ? {
          occurred_at: {
            ...(occurred_from !== undefined && occurred_from !== null && { gte: occurred_from }),
            ...(occurred_to !== undefined && occurred_to !== null && { lte: occurred_to }),
          },
        }
      : {}),
  };

  // Execute query and count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_seller_onboardings.findMany({
      where,
      orderBy: { [sortField]: sortDir },
      skip,
      take,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_seller_onboardings.count({ where }),
  ]);

  // Map rows (Prisma returns Date objects for dates, must convert)
  const data = rows.map((row) => ({
    id: row.id,
    seller_id: row.seller_id,
    step_code: row.step_code,
    step_status: row.step_status,
    approved_by: row.approved_by ?? null,
    occurred_at: toISOStringSafe(row.occurred_at),
    note: row.note ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  const lastPage = Math.ceil(total / take) || 1;
  return {
    pagination: {
      current: page as number & tags.Type<'int32'>,
      limit: take as number & tags.Type<'int32'>,
      records: total as number & tags.Type<'int32'>,
      pages: lastPage as number & tags.Type<'int32'>,
    },
    data,
  };
}

