/**
 * Paginated, filtered search/index of mileage wallet records (ShoppingMallAiBackendMileageWallets).
 *
 * 검색, 필터, 정렬, 잔액 범위, 페이지네이션 기준으로 마일리지 월렛 목록을 조회합니다. 관리자만 사용 가능합니다.
 * 결제 개인정보 보호상, 모든 검색은 admin 권한 필요하며, 모든 조회는 트레이스/컴플라이언스를 위해 감사 로그로 저장됩니다.
 *
 * @param props - 요청 파라미터
 * @param props.admin - 인증된 관리자 페이로드 (AdminPayload)
 * @param props.body - 검색/필터 요청 객체 (IShoppingMallAiBackendMileageWallet.IRequest)
 * @returns 페이징된 마일리지 월렛 목록 (IPageIShoppingMallAiBackendMileageWallet)
 * @throws {Error} 권한 부족(admin 아님 또는 비활성 admin), DB 오류 발생 시
 */
export async function patch__shoppingMallAiBackend_admin_mileageWallets(props: {
  admin: AdminPayload;
  body: IShoppingMallAiBackendMileageWallet.IRequest;
}): Promise<IPageIShoppingMallAiBackendMileageWallet> {
  const { admin, body } = props;

  // Admin 인증(불필요한 user validation은 불필요; decorator로 검증됨)
  // 세부 필터 빌드
  const where = {
    deleted_at: null,
    ...(body.customer_id !== undefined && body.customer_id !== null && {
      customer_id: body.customer_id,
    }),
    ...(body.wallet_program !== undefined && body.wallet_program !== null && {
      wallet_program: body.wallet_program,
    }),
    ...(body.wallet_status !== undefined && body.wallet_status !== null && {
      wallet_status: body.wallet_status,
    }),
    ...(body.wallet_label !== undefined && body.wallet_label !== null && {
      wallet_label: {
        contains: body.wallet_label,
        mode: "insensitive" as const,
      },
    }),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) ||
      (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined && body.created_at_from !== null && {
              gte: body.created_at_from,
            }),
            ...(body.created_at_to !== undefined && body.created_at_to !== null && {
              lte: body.created_at_to,
            }),
          },
        }
      : {}),
  };

  // 페이지네이션 파라미터/정합성 보정
  const page = Number.isFinite(body.page) && Number(body.page) >= 1 ? Number(body.page) : 1;
  const limit =
    Number.isFinite(body.limit) && Number(body.limit) >= 1 && Number(body.limit) <= 100
      ? Number(body.limit)
      : 25;
  const skip = (page - 1) * limit;

  // 정렬 필드 (created_at asc/desc만 허용)
  const orderBy =
    typeof body.sort === "string" && body.sort.trim() === "created_at asc"
      ? { created_at: "asc" as const }
      : { created_at: "desc" as const };

  // 데이터/카운트 패치
  const [wallets, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findMany({
      where,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.count({
      where,
    }),
  ]);

  // 잔액 기준 추가 필터 시,
  // 1. 각 월렛별 잔액 집계 (transactions에서 wallet_id로 합계)
  // 2. 필터 적용
  let filteredWallets = wallets;
  if (
    (body.balance_min !== undefined && body.balance_min !== null) ||
    (body.balance_max !== undefined && body.balance_max !== null)
  ) {
    // 월렛별 잔액 집계
    const walletIds = wallets.map((w) => w.id);
    if (walletIds.length > 0) {
      const balancesRaw = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.groupBy({
        by: ["wallet_id"],
        where: {
          wallet_id: { in: walletIds },
        },
        _sum: { mileage_amount: true },
      });
      const balances: Record<string, number> = {};
      for (const br of balancesRaw) {
        balances[br.wallet_id] = br._sum.mileage_amount ?? 0;
      }
      filteredWallets = wallets.filter((w) => {
        const balance = balances[w.id] ?? 0;
        if (
          body.balance_min !== undefined &&
          body.balance_min !== null &&
          balance < body.balance_min
        ) {
          return false;
        }
        if (
          body.balance_max !== undefined &&
          body.balance_max !== null &&
          balance > body.balance_max
        ) {
          return false;
        }
        return true;
      });
    } else {
      filteredWallets = [];
    }
  }

  // 최종 변환 및 ISO, UUID branding, null/undefined 일관성 처리
  const data = filteredWallets.map((row) => ({
    id: row.id,
    customer_id: row.customer_id,
    wallet_program: row.wallet_program,
    wallet_status: row.wallet_status,
    wallet_label: row.wallet_label ?? null,
    security_code: row.security_code ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  // 페이지수 재계산 (balance 필터로 일부 제거될 수 있으므로)
  const resultTotal = filteredWallets.length;
  const resultPages = Math.ceil(resultTotal / limit);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: resultTotal,
      pages: resultPages,
    },
    data,
  };
}

