  // 2. 페이징/정렬 값 파싱
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // 3. where 조건 구성
  const where = {
    product_id: productId,
    deleted_at: null,
    ...(body.channel_id !== undefined && body.channel_id !== null && { channel_id: body.channel_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.search ? {
      OR: [
        { status: { contains: body.search, mode: 'insensitive' as const } }
      ],
    } : {}),
  };

  // 4. 정렬 조건(inline)
  const orderBy = body.sort
    ? { [body.sort]: body.direction === 'asc' ? 'asc' : 'desc' }
    : { created_at: 'desc' };

