  const [rows, count] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.findMany({
      where,
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.count({ where }),
  ]);

  // 6. 결과 변환 (날짜 타입 안전 변환)
  const data = rows.map(row => ({
    id: row.id,
    product_id: row.product_id,
    channel_id: row.channel_id,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  // 7. 페이징 결과 조립
  return {
    pagination: {
      current: page,
      limit,
      records: count,
      pages: Math.ceil(count / limit),
    },
