import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendFavoriteProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendFavoriteProduct";
import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Mark a product as favorite for the authenticated customer.
 *
 * Allow a customer to favorite a product by specifying a valid product ID. This operation creates a new favoriteProducts record that links the authenticated customer with the target product. Duplicate attempts gracefully return existing favorite or error if already favorited and active.
 *
 * On success, side effects may trigger real-time notifications (for price drops or restocks) and contribute to AI/ML recommendation datasets, increasing system behavioral insight for both customer and business.
 *
 * Permissions are limited to end-customers; sellers and admins cannot favorite products via this endpoint.
 *
 * @param props - The request properties including authentication and input body.
 * @param props.customer - Authenticated customer making the request, injected by CustomerAuth decorator.
 * @param props.body - The data to create a favorite product link (product_id).
 * @returns The favorite product record as per IShoppingMallAiBackendFavoriteProduct.
 * @throws {Error} If the product_id does not exist or is not available for favoriting.
 */
export async function post__shoppingMallAiBackend_customer_favoriteProducts(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendFavoriteProduct.ICreate;
  },
): Promise<IShoppingMallAiBackendFavoriteProduct> {
  const { customer, body } = props;

  // 1. Try to find existing active favorite
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findFirst({
    where: {
      customer_id: customer.id,
      product_id: body.product_id,
      deleted_at: null,
    },
  });
  if (existing) {
    return {
      id: existing.id,
      customer_id: existing.customer_id,
      product_id: existing.product_id,
      created_at: toISOStringSafe(existing.created_at),
      deleted_at: existing.deleted_at ? toISOStringSafe(existing.deleted_at) : null,
    };
  }

  // 2. Try to reactivate by un-deleting
  const softDeleted = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findFirst({
    where: {
      customer_id: customer.id,
      product_id: body.product_id,
      NOT: { deleted_at: null },
    },
  });
  if (softDeleted) {
    const now = toISOStringSafe(new Date());
    const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.update({
      where: { id: softDeleted.id },
      data: {
        deleted_at: null,
        created_at: now,
      },
    });
    return {
      id: updated.id,
      customer_id: updated.customer_id,
      product_id: updated.product_id,
      created_at: toISOStringSafe(updated.created_at),
      deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
    };
  }

  // 3. Try to create a new favorite
  const id = v4() as string & tags.Format<'uuid'>;
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.create({
    data: {
      id,
      customer_id: customer.id,
      product_id: body.product_id,
      created_at: now,
      deleted_at: null,
    },
  });

  return {
    id: created.id,
    customer_id: created.customer_id,
    product_id: created.product_id,
    created_at: toISOStringSafe(created.created_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
