import { IShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductContent";
import { IPageIShoppingMallAiBackendProductContent } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendProductContent";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Provides a paginated, filterable search of all product content records linked to a single product.
 *
 * Only authorized sellers may perform this action. Filters on content_type, status, description, and supports robust pagination + ordering.
 *
 * @param props - The props for the operation.
 * @param props.seller - The authenticated seller payload (ownership check enforced)
 * @param props.productId - UUID of the product whose contents are being listed
 * @param props.body - Search criteria, filter and paging/sorting options
 * @returns Paginated summary search result for product content records
 * @throws {Error} Not authorized (seller does not own the product), or product not found
 */
export async function patch__shoppingMallAiBackend_seller_products_$productId_productContents(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductContent.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendProductContent.ISummary> {
  const { seller, productId, body } = props;

  // 1. Authorization check: product must belong to seller and not deleted
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: { id: productId, seller_id: seller.id, deleted_at: null },
  });
  if (!product)
    throw new Error('Not authorized: Product does not exist or is not owned by this seller');

  // 2. Build dynamic where condition based on permitted filters
  const where = {
    product_id: productId,
    deleted_at: null,
    ...(body.content_type && { content_type: body.content_type }),
    ...(body.status && { status: body.status }),
    ...(body.content_description && { content_description: { contains: body.content_description, mode: 'insensitive' as const } }),
  };

  // 3. Pagination calculation (default: page=1, limit=20)
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  // 4. Allow only allowed fields for sorting (robust to malicious requests)
  const allowedOrderFields = ['content_order', 'created_at', 'updated_at'];
  const orderByField = body.order_by && allowedOrderFields.includes(body.order_by) ? body.order_by : 'created_at';
  const orderDirection = body.order_direction === 'asc' ? 'asc' : 'desc';

  // 5. Query concurrently for data and total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_contents.findMany({
      where,
      orderBy: { [orderByField]: orderDirection },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_contents.count({ where }),
  ]);

  const data = rows.map(row => ({
    id: row.id,
    product_id: row.product_id,
    content_type: row.content_type,
    content_uri: row.content_uri,
    content_order: row.content_order,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: total === 0 ? 1 : Math.ceil(total / limit),
    },
    data,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
