import { SellerPayload } from "../decorators/payload/SellerPayload"

/**
 * Paginated, filterable search of inquiry snapshot history by inquiry ID.
 *
 * Enables paginated/filtered search of all snapshots of a product inquiry—by inquiry ID—for rollback, discrepancy analysis, or compliance evidence. Only the seller of the product referenced by the inquiry may access these snapshots.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller making the request
 * @param props.productInquiryId - UUID of the product inquiry whose snapshots are being searched
 * @param props.body - Snapshot list search and filter criteria, with sort and pagination control
 * @returns Paginated list with metadata and snapshot records
 * @throws {Error} When the inquiry is not found or the seller does not own the product
 */
export async function patch__shoppingMallAiBackend_seller_productInquiries_$productInquiryId_inquirySnapshots(
  props: {
    seller: SellerPayload;
    productInquiryId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendInquirySnapshot.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendInquirySnapshot> {
  const { seller, productInquiryId, body } = props;

  // Step 1: Authorization - fetch inquiry and verify seller owns related product
  const inquiry = await MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.findUnique({
    where: { id: productInquiryId },
    select: { product_id: true, deleted_at: true },
  });
  if (!inquiry || inquiry.deleted_at !== null) {
    throw new Error('Inquiry not found');
  }
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: inquiry.product_id },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error('Unauthorized: you do not own this product');
  }

  // Step 2: Build filters for inquiry snapshots
  const {
    actor_id,
    status,
    changed_at_from,
    changed_at_to,
    page = 1,
    limit = 20,
    sort_by = 'changed_at',
    sort_direction = 'desc',
  } = body;

  const whereClause = {
    inquiry_id: productInquiryId,
    ...(actor_id !== undefined && { actor_id }),
    ...(status !== undefined && { status }),
    ...((changed_at_from || changed_at_to) ? {
      changed_at: {
        ...(changed_at_from && { gte: changed_at_from }),
        ...(changed_at_to && { lte: changed_at_to }),
      },
    } : {}),
  };

  const [snapshots, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_inquiry_snapshots.findMany({
      where: whereClause,
      orderBy: { [sort_by]: sort_direction },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_inquiry_snapshots.count({
      where: whereClause,
    }),
  ]);

  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: snapshots.map((s) => ({
      id: s.id,
      inquiry_id: s.inquiry_id,
      title: s.title,
      body: s.body,
      public: s.public,
      status: s.status as "waiting" | "answered" | "blocked" | "under_review" | "deleted", // Enum branded string
      actor_id: s.actor_id,
      ai_sentiment_score: s.ai_sentiment_score,
      ai_spam_score: s.ai_spam_score,
      changed_at: toISOStringSafe(s.changed_at),
    })),
  };
}

