import { IShoppingMallAiBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSection";
import { IPageIShoppingMallAiBackendSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSection";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Admin API to retrieve a paginated/filtered list of product sections within a specified channel.
 *
 * Only accessible to authenticated admins. Applies pagination, search, and filtering on curation sections for a specific channel.
 * Excludes soft-deleted sections by default. Results include section metadata suitable for list and UI display. Pagination info is included.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making this request.
 * @param props.channelId - The UUID of the business channel whose sections are listed.
 * @param props.body - The filtering/search and pagination input
 * @returns Paginated summary data (code, name, display_order, visible) per section, with pagination meta
 * @throws {Error} When the channel doesn't exist or has been deleted, or the admin is unauthorized
 */
export async function patch__shoppingMallAiBackend_admin_channels_$channelId_sections(
  props: {
    admin: AdminPayload;
    channelId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendSection.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendSection.ISummary> {
  const { admin, channelId, body } = props;

  // 1. Channel existence and soft-delete check
  const channel = await MyGlobal.prisma.shopping_mall_ai_backend_channels.findFirst({
    where: { id: channelId, deleted_at: null },
    select: { id: true }
  });
  if (!channel) throw new Error('Channel not found or deleted');

  // 2. Pagination handling
  const page = body.page != null && body.page > 0 ? body.page : 1;
  const limit = body.limit != null && body.limit > 0 ? Math.min(body.limit, 100) : 20;
  const skip = (page - 1) * limit;

  // 3. Build WHERE clause (only use schema-verified fields)
  const where = {
    channel_id: channelId,
    deleted_at: null,
    ...(body.code ? { code: body.code } : {}),
    ...(body.name ? { name: { contains: body.name, mode: 'insensitive' as const } } : {}),
    ...(body.display_order !== undefined ? { display_order: body.display_order } : {}),
    ...(body.visible !== undefined ? { visible: body.visible } : {})
  };

  // 4. Get total count for pagination
  const total = await MyGlobal.prisma.shopping_mall_ai_backend_sections.count({ where });

  // 5. Query paged section rows
  const sections = await MyGlobal.prisma.shopping_mall_ai_backend_sections.findMany({
    where,
    orderBy: [
      { display_order: 'asc' },
      { created_at: 'desc' },
    ],
    skip,
    take: limit,
    select: {
      id: true,
      code: true,
      name: true,
      display_order: true,
      visible: true
    }
  });

  // 6. Map rows to ISummary DTOs
  const data = sections.map(section => ({
    id: section.id,
    code: section.code,
    name: section.name,
    display_order: section.display_order,
    visible: section.visible
  }));

  // 7. Compute pagination block
  const pages = total === 0 ? 1 : Math.ceil(total / limit);
  const pagination = {
    current: page as number & tags.Type<'int32'>,
    limit: limit as number & tags.Type<'int32'>,
    records: total as number & tags.Type<'int32'>,
    pages: pages as number & tags.Type<'int32'>
  };

  return {
    pagination,
    data
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendCartItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCartItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * 장바구니에 새로운 아이템을 추가합니다.
 *
 * 이 함수는 고객 인증 후, 주어진 cartId가 실제 고객의 소유인지와 활성 상태임을 확인합니다. 이미 동일한 상품 및 옵션 조합의 미삭제(cart item) 존재시 중복 오류를 반환합니다. 상품/옵션 존재 여부, 수량 비즈니스 규칙을 검증하며, 성공 시 신규 장바구니 아이템 엔터티를 반환합니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 페이로드 (JWT)
 * @param props.cartId - 장바구니 ID (UUID)
 * @param props.body - 추가할 장바구니 아이템 데이터(상품, 수량, 옵션 등)
 * @returns 신규로 추가된 장바구니 아이템 엔터티
 * @throws {Error} 장바구니 소유권/존재 위반 또는 활성 상태 아님
 * @throws {Error} 동일 아이템 중복 추가 시도
 * @throws {Error} 존재하지 않는 상품/옵션 ID 입력
 * @throws {Error} 수량 규칙 위반 등
 */
export async function post__shoppingMallAiBackend_customer_carts_$cartId_cartItems(
  props: {
    customer: CustomerPayload;
    cartId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendCartItem.ICreate;
  }
): Promise<IShoppingMallAiBackendCartItem> {
  const { customer, cartId, body } = props;

  // 1. 장바구니 존재 및 고객 소유/활성 검증
  const cart = await MyGlobal.prisma.shopping_mall_ai_backend_carts.findFirst({
    where: {
      id: cartId,
      customer_id: customer.id,
      deleted_at: null
    }
  });
  if (!cart) throw new Error('장바구니를 찾을 수 없거나 접근 권한이 없습니다.');

  // 2. 중복 키: product_id 및 product_option_id가 동일한 미삭제 아이템 존재시 오류
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_backend_cart_items.findFirst({
    where: {
      cart_id: cartId,
      product_id: body.product_id,
      // 옵션이 지정된 경우, null/undefined 구분 정확히 해야 함:
      ...(body.product_option_id === null || body.product_option_id === undefined
        ? { product_option_id: null }
        : { product_option_id: body.product_option_id }),
      deleted_at: null
    }
  });
  if (duplicate) throw new Error('이미 동일한 상품(및 옵션)의 아이템이 장바구니에 존재합니다.');

  // 3. 상품 존재 및 활성 검증
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: {
      id: body.product_id,
      deleted_at: null
    }
  });
  if (!product) throw new Error('상품이 존재하지 않거나 구매 불가 상태입니다.');

  // 4. 옵션 ID 지정된 경우, 상품 옵션 유효성 검증
  if (body.product_option_id !== null && body.product_option_id !== undefined) {
    const option = await MyGlobal.prisma.shopping_mall_ai_backend_product_options.findFirst({
      where: {
        id: body.product_option_id,
        product_id: body.product_id,
        deleted_at: null
      }
    });
    if (!option) throw new Error('상품 옵션이 존재하지 않거나 상품에 속하지 않습니다.');
  }

  // 5. 수량 비즈니스 규칙
  if (body.quantity < 1) throw new Error('수량은 1 이상이어야 합니다.');

  // 6. 장바구니 아이템 생성
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_cart_items.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      cart_id: cartId,
      product_id: body.product_id,
      product_option_id: body.product_option_id ?? null,
      quantity: body.quantity,
      unit_price: body.unit_price,
      currency_code: body.currency_code,
      note: body.note ?? null,
      created_at: now,
      updated_at: now,
      deleted_at: null
    }
  });

  // 7. 반환 - 모든 날짜 필드를 string & tags.Format<'date-time'>로 가공
  return {
    id: created.id,
    product_id: created.product_id,
    product_option_id: created.product_option_id ?? null,
    quantity: created.quantity,
    unit_price: created.unit_price,
    currency_code: created.currency_code,
    note: created.note ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { ICustomerSignIn } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignIn";
import { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";


/**
 * Authenticate customer (shopping_mall_ai_backend_customers) and issue JWT token.
 *
 * Provides customer login/authentication as defined in the shopping_mall_ai_backend_customers table. Accepts email and password credentials, validates against the password_hash, issues JWT tokens for authenticated API use. The endpoint sets the last_login_at timestamp, updates login event history (customer_histories), and returns tokens in the response. Credentials are checked for validity with business logic enforcing status checks (active, locked, dormant) – with errors returned for unauthorized access. The endpoint is public, uses strong hashing on secret comparison, and enforces unique email for user identity. Related operations include signUp, signOut, and changePassword.
 *
 * @param props - Request properties
 * @param props.body - Customer login credentials (email and password)
 * @returns Returns JWT auth token in setHeaders and customer profile (excluding password_hash)
 * @throws {Error} When email or password is invalid, status is not active, email not verified, or credential is incorrect
 */
export async function post__auth_customer_login(
  props: { body: ICustomerSignIn.Request }
): Promise<ICustomerSignIn.Response> {
  const { email, password } = props.body;

  const customer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: { email }
  });

  if (!customer) throw new Error("Invalid email or password");
  if (customer.status !== "active") throw new Error("Account status is not active");
  if (!customer.email_verified) throw new Error("Email verification required");

  // Browser-compatible password verification using Web Crypto API (SHA-256 hash + constant time compare)
  const enc = new TextEncoder();
  const passwordData = enc.encode(password);
  const hashBuffer = await crypto.subtle.digest("SHA-256", passwordData);
  const computedHash = Array.from(new Uint8Array(hashBuffer)).map(b => b.toString(16).padStart(2, "0")).join("");
  if (computedHash !== customer.password_hash) throw new Error("Invalid email or password");

  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());

  await MyGlobal.prisma.shopping_mall_ai_backend_customers.update({
    where: { id: customer.id },
    data: {
      last_login_at: now,
      updated_at: now,
    }
  });

  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      customer_id: customer.id,
      event_type: "login",
      old_value_json: null,
      new_value_json: null,
      triggered_by: "customer",
      meta_json: null,
      occurred_at: now,
      created_at: now,
    }
  });

  // JWT token generation (Web Crypto API based implementation)
  const header = {
    alg: "HS256",
    typ: "JWT",
  };
  const payload = {
    sub: customer.id,
    email: customer.email,
    iat: Math.floor(Date.now() / 1000),
  };
  function base64url(source: string) {
    return btoa(source).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  }
  const encHeader = base64url(JSON.stringify(header));
  const encPayload = base64url(JSON.stringify(payload));
  const signingInput = `${encHeader}.${encPayload}`;

  // Dummy static secret for demo—replace with secure env secret in production!
  const secret = enc.encode("shoppingmall-secret-key");
  const signatureBuffer = await crypto.subtle.importKey('raw', secret, { name: 'HMAC', hash: 'SHA-256' }, false, ['sign'])
    .then(key => crypto.subtle.sign('HMAC', key, new TextEncoder().encode(signingInput)));
  const signature = base64url(String.fromCharCode(...new Uint8Array(signatureBuffer)));
  const token = `${encHeader}.${encPayload}.${signature}`;

  // Compose customer DTO per IShoppingMallAiBackendCustomer
  const responseCustomer = {
    id: customer.id,
    email: customer.email,
    name: customer.name,
    nickname: customer.nickname,
    phone: customer.phone,
    profile_image_uri: customer.profile_image_uri ?? null,
    status: customer.status,
    email_verified: customer.email_verified,
    phone_verified: customer.phone_verified,
    joined_at: toISOStringSafe(customer.joined_at),
    last_login_at: now,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: now,
    deleted_at: customer.deleted_at ? toISOStringSafe(customer.deleted_at) : null,
  };

  return {
    customer: responseCustomer,
    setHeaders: { Authorization: token }
  };
}

