 * @returns 알림 데이터 목록과 페이징 메타
 * @throws {Error} 고객이 소유한 즐겨찾기가 하나도 없는 경우(빈 목록 반환)
 */
export async function patch__shoppingMallAiBackend_customer_favoriteNotifications(
  props: { customer: CustomerPayload; body: IShoppingMallAiBackendFavoriteNotification.IRequest; }
): Promise<IPageIShoppingMallAiBackendFavoriteNotification> {
  const { customer, body } = props;

  // 페이징 값 유효성 체킹
  const page = body.page ?? 1;
  const limit = Math.min(body.limit ?? 20, 100);
  const skip = (page - 1) * limit;

  // 1. 각 즐겨찾기 타입별 ID 목록 (본인 소유만)
  const [productIds, inquiryIds, addressIds] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findMany({
      where: { customer_id: customer.id, deleted_at: null },
      select: { id: true },
    }).then(rows => rows.map(r => r.id)),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findMany({
      where: { customer_id: customer.id, deleted_at: null },
      select: { id: true },
    }).then(rows => rows.map(r => r.id)),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findMany({
      where: { customer_id: customer.id, deleted_at: null },
      select: { id: true },
    }).then(rows => rows.map(r => r.id)),
  ]);

  // 2. 소유권 WHERE 절 구성
  const ownershipClauses = [] as { [key: string]: any }[];
  if (productIds.length > 0) ownershipClauses.push({ favorite_product_id: { in: productIds } });
  if (inquiryIds.length > 0) ownershipClauses.push({ favorite_inquiry_id: { in: inquiryIds } });
  if (addressIds.length > 0) ownershipClauses.push({ favorite_address_id: { in: addressIds } });
  if (ownershipClauses.length === 0) {
    // 즐겨찾기 없음 → 빈 결과
    return {
      pagination: { current: page, limit, records: 0 as number & tags.Type<"int32">, pages: 0 as number & tags.Type<"int32"> },
      data: [],
    };
  }

  // 3. 필터/검색 where절 구축
  const where = {
    deleted_at: null,
    OR: ownershipClauses,
    ...(body.notification_type ? { notification_type: body.notification_type } : {}),
    ...(body.notification_channel ? { notification_channel: body.notification_channel } : {}),
    ...(body.read !== undefined ? { read: body.read } : {}),
    ...(body.favorite_product_id ? { favorite_product_id: body.favorite_product_id } : {}),
    ...(body.favorite_inquiry_id ? { favorite_inquiry_id: body.favorite_inquiry_id } : {}),
    ...(body.favorite_address_id ? { favorite_address_id: body.favorite_address_id } : {}),
    ...((body.created_at_from || body.created_at_to) ? {
      created_at: {
        ...(body.created_at_from ? { gte: body.created_at_from } : {}),
        ...(body.created_at_to ? { lte: body.created_at_to } : {}),
      },
    } : {}),
  };

  // 4. 데이터 조회 & total count
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_notifications.count({ where }),
  ]);

  // 5. 응답 변환 및 날짜 처리
  return {
    pagination: {
      current: page as number & tags.Type<"int32">,
      limit: limit as number & tags.Type<"int32">,
      records: total as number & tags.Type<"int32">,
      pages: Math.ceil(total / limit) as number & tags.Type<"int32">,
    },
    data: rows.map(row => ({
      id: row.id,
      favorite_product_id: row.favorite_product_id ?? null,
      favorite_inquiry_id: row.favorite_inquiry_id ?? null,
      favorite_address_id: row.favorite_address_id ?? null,
      notification_type: row.notification_type,
      notification_channel: row.notification_channel,
      read: row.read,
      delivery_metadata: row.delivery_metadata ?? null,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

