 * @param props - Function properties containing:
 *   seller: SellerPayload - Authenticated seller performing this query (ownership enforced).
 *   productId: string & tags.Format<'uuid'> - The parent product whose options are being queried.
 *   body: IShoppingMallAiBackendProductOption.IRequest - Search, filter, sort, and pagination controls.
 *
 * @returns {Promise<IPageIShoppingMallAiBackendProductOption.ISummary>}
 *  Paginated and summarized list of product options for the requested product.
 *
 * @throws {Error} When the product is not owned by the authenticated seller.
 */
export async function patch__shoppingMallAiBackend_seller_products_$productId_productOptions(props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductOption.IRequest;
}): Promise<IPageIShoppingMallAiBackendProductOption.ISummary> {
    const { seller, productId, body } = props;

    // 1. Ownership check: ensure the seller owns the product
    const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
        where: {
            id: productId,
            seller_id: seller.id,
            deleted_at: null,
        }
    });
    if (!product) {
        throw new Error('Forbidden: You do not own this product.');
    }

    // 2. Filter construction from the request
    const filter = body.filter ?? {};
    const where = {
        product_id: productId,
        ...(filter.optionId && { id: filter.optionId }),
        ...(filter.sku && { sku: { contains: filter.sku, mode: 'insensitive' as const } }),
        ...(filter.option_name && { option_name: { contains: filter.option_name, mode: 'insensitive' as const } }),
        ...(filter.status && { status: filter.status }),
        ...((filter.createdFrom || filter.createdTo)
            ? {
                created_at: {
                    ...(filter.createdFrom && { gte: filter.createdFrom }),
                    ...(filter.createdTo && { lte: filter.createdTo })
                }
            }
            : {}),
        ...(filter.deleted === true
            ? { deleted_at: { not: null } }
            : filter.deleted === false
                ? { deleted_at: null }
                : {})
    };
    // 3. Advanced search (applies OR to sku and option_name)
    if (body.search) {
        where.OR = [
            { sku: { contains: body.search, mode: 'insensitive' as const } },
            { option_name: { contains: body.search, mode: 'insensitive' as const } },
        ];
    }

    // 4. Sorting
    const allowedSortFields = ['created_at', 'updated_at', 'option_name', 'sku', 'status', 'deleted_at'];
    const orderBy = (body.sort && Array.isArray(body.sort) && body.sort.length > 0)
        ? body.sort.filter(s => allowedSortFields.includes(s.field)).map(s => ({ [s.field]: s.direction }))
        : [{ created_at: 'desc' }];

    // 5. Pagination
    const page = body.page && body.page > 0 ? body.page : 1;
    const pageSize = body.pageSize && body.pageSize > 0 && body.pageSize <= 500 ? body.pageSize : 20;
    const skip = (page - 1) * pageSize;
    const take = pageSize;

    // 6. Query options table and total count in parallel
    const [rows, total] = await Promise.all([
        MyGlobal.prisma.shopping_mall_ai_backend_product_options.findMany({
            where,
            orderBy,
            skip,
            take
        }),
        MyGlobal.prisma.shopping_mall_ai_backend_product_options.count({ where })
    ]);

    // 7. Transform output to DTO, enforcing ISO8601 string date/time fields
    const data = rows.map(option => ({
        id: option.id,
        product_id: option.product_id,
        sku: option.sku,
        option_name: option.option_name,
        option_values: option.option_values ?? null,
        extra_price: option.extra_price ?? null,
        main_image_uri: option.main_image_uri ?? null,
        status: option.status,
        created_at: toISOStringSafe(option.created_at),
        updated_at: toISOStringSafe(option.updated_at),
        deleted_at: option.deleted_at ? toISOStringSafe(option.deleted_at) : null,
    }));

    // 8. Build pagination metadata
    const pages = Math.ceil(total / pageSize);
    const pagination = {
        current: page,
        limit: pageSize,
        records: total,
        pages,
    };

    return { pagination, data };
}

