/**
 * Updates an existing customer's profile in shopping_mall_ai_backend_customers.
 *
 * This endpoint allows an authenticated customer to modify their own profile information. The update requires that the caller's CustomerPayload.id matches the target customer's id in the request body. Fields such as email/nickname are enforced as unique, and only non-soft-deleted customers may be updated. Every update is recorded in the customer_histories table for compliance and rollback audit. All datetime fields are returned as branded ISO strings (no native Date).
 *
 * @param props - Request parameters
 * @param props.customer - Authenticated customer JWT payload
 * @param props.body - Customer profile update input
 * @returns The updated customer object after modifications
 * @throws {Error} If trying to update a soft-deleted or non-existent customer, forbidden update of another customer's profile, or duplicate email/nickname
 */
export async function put__shoppingMallAiBackend_customer_customers(
  props: { customer: CustomerPayload; body: IShoppingMallAiBackendCustomer.IUpdate }
): Promise<IShoppingMallAiBackendCustomer> {
  const { customer, body } = props;
  // Only allow updating self
  if (customer.id !== body.id) throw new Error("Forbidden: cannot update another customer profile");

  // Find the existing customer (not soft-deleted)
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: { id: body.id, deleted_at: null },
  });
  if (!existing) throw new Error("Customer not found or has been deleted");

  // If email is being changed, check for uniqueness (excluding self and deleted)
  if (body.email && body.email !== existing.email) {
    const dupe = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
      where: { email: body.email, id: { not: body.id }, deleted_at: null },
    });
    if (dupe) throw new Error("Email is already in use");
  }
  // If nickname is being changed, check for uniqueness
  if (body.nickname && body.nickname !== existing.nickname) {
    const dupe = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
      where: { nickname: body.nickname, id: { not: body.id }, deleted_at: null },
    });
    if (dupe) throw new Error("Nickname is already in use");
  }

  // Update fields
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_customers.update({
    where: { id: body.id },
    data: {
      email: body.email ?? undefined,
      name: body.name ?? undefined,
      nickname: body.nickname ?? undefined,
      phone: body.phone ?? undefined,
      profile_image_uri: body.profile_image_uri ?? undefined,
      status: body.status ?? undefined,
      email_verified: body.email_verified ?? undefined,
      phone_verified: body.phone_verified ?? undefined,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  // Write snapshot to customer_histories
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      customer_id: updated.id,
      event_type: "updated",
      old_value_json: JSON.stringify(existing),
      new_value_json: JSON.stringify(updated),
      triggered_by: customer.id,
      meta_json: null,
      occurred_at: toISOStringSafe(new Date()),
      created_at: toISOStringSafe(new Date()),
    },
  });

  // Return fully formatted IShoppingMallAiBackendCustomer
  return {
    id: updated.id,
    email: updated.email,
    name: updated.name,
    nickname: updated.nickname,
    phone: updated.phone,
    profile_image_uri: updated.profile_image_uri ?? null,
    status: updated.status,
    email_verified: updated.email_verified,
    phone_verified: updated.phone_verified,
    joined_at: toISOStringSafe(updated.joined_at),
    last_login_at: updated.last_login_at ? toISOStringSafe(updated.last_login_at) : null,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

