/**
 * Hash a password with a salt using PBKDF2-SHA256 using browser Web Crypto API.
 * Returns lowercase hex string.
 */
async function pbkdf2Sha256(
  password: string,
  salt: Uint8Array,
  iterations: number,
  keyLength: number
): Promise<string> {
  const enc = new TextEncoder();
  const key = await window.crypto.subtle.importKey(
    'raw',
    enc.encode(password),
    'PBKDF2',
    false,
    ['deriveBits']
  );
  const derived = await window.crypto.subtle.deriveBits({
    name: 'PBKDF2',
    salt,
    iterations,
    hash: 'SHA-256'
  }, key, keyLength * 8);
  return Array.from(new Uint8Array(derived))
    .map(b => b.toString(16).padStart(2, '0'))
    .join('');
}

