export async function patch__shoppingMallAiBackend_customer_favoriteSnapshots(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendFavoriteSnapshot.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendFavoriteSnapshot> {
  const { customer, body } = props;

  // 본인 계정의 snapshot 조회만 허용
  if (body.customer_id !== undefined && body.customer_id !== null && body.customer_id !== customer.id) {
    throw new Error("Forbidden: Only your own favorite snapshot records may be accessed.");
  }
  const effectiveCustomerId = customer.id;

  // 페이징 파라미터 정규화
  const safePage = body.page && body.page >= 1 ? body.page : 1;
  const safeLimit = body.limit && body.limit >= 1 ? Math.min(body.limit, 100) : 20;
  const skip = (safePage - 1) * safeLimit;

  // WHERE 필터 구성 (직접적으로 favorite_..._id만 가지는 경우 사용)
  const where: Record<string, unknown> = {
    ...(body.favorite_product_id !== undefined && body.favorite_product_id !== null && { favorite_product_id: body.favorite_product_id }),
    ...(body.favorite_inquiry_id !== undefined && body.favorite_inquiry_id !== null && { favorite_inquiry_id: body.favorite_inquiry_id }),
    ...(body.favorite_address_id !== undefined && body.favorite_address_id !== null && { favorite_address_id: body.favorite_address_id }),
    ...(body.target_type !== undefined && { target_type: body.target_type }),
    // 생성일 범위
    ...((body.created_at_from !== undefined || body.created_at_to !== undefined)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined && { gte: body.created_at_from }),
            ...(body.created_at_to !== undefined && { lte: body.created_at_to }),
          },
        }
      : {}),
  };

