  // favorite_product_ids...
  const [myProductIds, myInquiryIds, myAddressIds] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findMany({
      where: { customer_id: effectiveCustomerId, deleted_at: null },
      select: { id: true },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findMany({
      where: { customer_id: effectiveCustomerId, deleted_at: null },
      select: { id: true },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findMany({
      where: { customer_id: effectiveCustomerId, deleted_at: null },
      select: { id: true },
    }),
  ]);

  // 각 ID 배열 생성
  const ownedFavoriteProductIds = myProductIds.map(item => item.id);
  const ownedFavoriteInquiryIds = myInquiryIds.map(item => item.id);
  const ownedFavoriteAddressIds = myAddressIds.map(item => item.id);

  // 소유권 제한 적용
  Object.assign(where, {
    OR: [
      { favorite_product_id: { in: ownedFavoriteProductIds.length > 0 ? ownedFavoriteProductIds : ["-"] } },
      { favorite_inquiry_id: { in: ownedFavoriteInquiryIds.length > 0 ? ownedFavoriteInquiryIds : ["-"] } },
      { favorite_address_id: { in: ownedFavoriteAddressIds.length > 0 ? ownedFavoriteAddressIds : ["-"] } },
    ],
  });

  const [rows, totalRecords] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_snapshots.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: safeLimit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_snapshots.count({ where }),
  ]);

  return {
    pagination: {
      current: safePage,
      limit: safeLimit,
      records: totalRecords,
      pages: Math.ceil(totalRecords / safeLimit),
    },
    data: rows.map(row => ({
      id: row.id,
      favorite_product_id: row.favorite_product_id ?? null,
      favorite_inquiry_id: row.favorite_inquiry_id ?? null,
      favorite_address_id: row.favorite_address_id ?? null,
      target_type: row.target_type as "PRODUCT" | "INQUIRY" | "ADDRESS",
      snapshot_object_id: row.snapshot_object_id,
      serialized_object: row.serialized_object,
      created_at: toISOStringSafe(row.created_at),
    })),
  };
}

