 * Ensures only the owning authenticated customer can access the snapshot.
 * Throws if not found, soft-deleted, or customer does not own it.
 * Properly converts all date values and IDs for type safety.
 *
 * @param props - Request properties.
 * @param props.customer - The authenticated customer.
 * @param props.favoriteSnapshotId - UUID of the favorite snapshot.
 * @returns The favorite snapshot record as per business contract.
 * @throws {Error} If not found, soft-deleted, or unauthorized.
 */
export async function get__shoppingMallAiBackend_customer_favoriteSnapshots_$favoriteSnapshotId(
  props: { customer: CustomerPayload; favoriteSnapshotId: string & tags.Format<'uuid'> }
): Promise<IShoppingMallAiBackendFavoriteSnapshot> {
  const { customer, favoriteSnapshotId } = props;
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_snapshots.findUnique({
    where: { id: favoriteSnapshotId }
  });
  if (!snapshot)
    throw new Error("Favorite snapshot not found");
  let favorite: { customer_id: string; deleted_at?: Date | null } | null = null;
  if (snapshot.favorite_product_id) {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findUnique({ where: { id: snapshot.favorite_product_id } });
  } else if (snapshot.favorite_inquiry_id) {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findUnique({ where: { id: snapshot.favorite_inquiry_id } });
  } else if (snapshot.favorite_address_id) {
    favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findUnique({ where: { id: snapshot.favorite_address_id } });
  } else {
    throw new Error("No referenced favorite found for this snapshot");
  }
  if (!favorite || !favorite.customer_id)
    throw new Error("Referenced favorite does not exist");
  if (favorite.deleted_at)
    throw new Error("Favorite has been deleted");
  if (favorite.customer_id !== customer.id)
    throw new Error("Forbidden: You do not own this favorite snapshot");
  return {
    id: snapshot.id,
    favorite_product_id: snapshot.favorite_product_id ?? undefined,
    favorite_inquiry_id: snapshot.favorite_inquiry_id ?? undefined,
    favorite_address_id: snapshot.favorite_address_id ?? undefined,
