import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Updates a favorite address record (unfavorite or restore).
 *
 * This endpoint allows an authenticated customer to soft-unfavorite or restore a favorite address by updating the deleted_at field.
 * Only the owner may perform this update. Throws if record doesn't exist, isn't owned by customer, is already in the desired state, or for any invalid state change.
 *
 * @param props.customer - Authenticated customer session payload
 * @param props.favoriteAddressId - The UUID of the favorite address record to update
 * @param props.body - The update payload (IShoppingMallAiBackendFavoriteAddress.IUpdate)
 * @returns The updated favorite address record
 * @throws {Error} If favorite address not found, ownership is invalid, or operation is redundant/invalid
 */
export async function put__shoppingMallAiBackend_customer_favoriteAddresses_$favoriteAddressId(
  props: {
    customer: CustomerPayload;
    favoriteAddressId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendFavoriteAddress.IUpdate;
  }
): Promise<IShoppingMallAiBackendFavoriteAddress> {
  const { customer, favoriteAddressId, body } = props;

  const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findUnique({
    where: { id: favoriteAddressId },
  });
  if (!favorite) throw new Error("Favorite address not found");
  if (favorite.customer_id !== customer.id) throw new Error("Unauthorized: not owner");

  const requestUnfavorite = body.deleted_at != null;
  const currentlyUnfavorited = favorite.deleted_at != null;

  if (requestUnfavorite) {
    if (currentlyUnfavorited) throw new Error("Already unfavorited");
    const now = toISOStringSafe(new Date());
    const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.update({
      where: { id: favoriteAddressId },
      data: { deleted_at: now },
    });
    return {
      id: updated.id,
      customer_id: updated.customer_id,
      address_id: updated.address_id,
      created_at: toISOStringSafe(updated.created_at),
      deleted_at: toISOStringSafe(updated.deleted_at!),
    };
  } else {
    if (!currentlyUnfavorited) throw new Error("Favorite address is already active");
    const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.update({
      where: { id: favoriteAddressId },
      data: { deleted_at: null },
    });
    return {
      id: updated.id,
      customer_id: updated.customer_id,
      address_id: updated.address_id,
      created_at: toISOStringSafe(updated.created_at),
      deleted_at: null,
    };
  }
}

