 * @param props.admin - Authenticated admin making the request
 * @param props.productId - UUID of the product to map.
 * @param props.body - Mapping details: product_id, category_id, primary flag.
 * @returns The newly created product-category mapping record
 * @throws {Error} If mapping already exists, a primary already exists, or product/category are missing
 */
export async function post__shoppingMallAiBackend_admin_products_$productId_productCategoryMap(
  props: {
    admin: AdminPayload;
    productId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendProductCategoryMap.ICreate;
  }
): Promise<IShoppingMallAiBackendProductCategoryMap> {
  const { admin, productId, body } = props;

