 *
 * Register a new customer point wallet in the shopping mall AI backend. This API requires customer association and starting balance data in the request body. The endpoint maps to the shopping_mall_ai_backend_points table and enforces privilege, field validation, and business rules. Upon successful creation, a full wallet DTO is returned. Attempting to create a duplicate wallet for the same customer will fail. Admin authorization and compliance logging are enforced. Only admins can use this operation.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user (authorization required)
 * @param props.body - Data for wallet creation (customer_id: uuid, balance: number)
 * @returns The newly created point wallet
 * @throws {Error} If the referenced customer does not exist or is deleted
 * @throws {Error} If a point wallet already exists for this customer
 */
export async function post__shoppingMallAiBackend_admin_points(
  props: { admin: AdminPayload; body: IShoppingMallAiBackendPoint.ICreate }
): Promise<IShoppingMallAiBackendPoint> {
  const { admin, body } = props;

  // 1. Ensure referenced customer exists and is active (not deleted)
  const customer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: { id: body.customer_id, deleted_at: null },
    select: { id: true }
  });
  if (!customer) {
    throw new Error("Referenced customer does not exist or is deleted");
  }

  // 2. Ensure uniqueness (one wallet per customer by business rule)
  const walletExists = await MyGlobal.prisma.shopping_mall_ai_backend_points.findFirst({
    where: { customer_id: body.customer_id },
    select: { id: true }
  });
  if (walletExists) {
    throw new Error("A point wallet already exists for this customer");
  }

  // 3. Generate id and update time
  const pointId: string & tags.Format<'uuid'> = v4() as string & tags.Format<'uuid'>;
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());

  // 4. Create the wallet
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_points.create({
    data: {
      id: pointId,
      customer_id: body.customer_id,
      balance: body.balance,
      updated_at: now,
    }
  });

  // 5. Return the standardized response
  return {
    id: created.id,
    customer_id: created.customer_id,
    balance: created.balance,
    updated_at: created.updated_at
  };
}

