 *
 * @param props - Request parameters
 *   - seller: The authenticated seller (owner of the product)
 *   - productInquiryId: ID of the product inquiry (UUID)
 *   - inquirySnapshotId: ID of the inquiry snapshot (UUID)
 * @returns Immutable snapshot state, strictly typed and branded.
 * @throws {Error} If not found, deleted, or unauthorized.
 */
export async function get__shoppingMallAiBackend_seller_productInquiries_$productInquiryId_inquirySnapshots_$inquirySnapshotId(
  props: {
    seller: SellerPayload;
    productInquiryId: string & tags.Format<'uuid'>;
    inquirySnapshotId: string & tags.Format<'uuid'>;
  }
): Promise<IShoppingMallAiBackendInquirySnapshot> {
  const { seller, productInquiryId, inquirySnapshotId } = props;

  // 1. Fetch the inquiry snapshot for the correct inquiry
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_inquiry_snapshots.findFirst({
    where: { id: inquirySnapshotId, inquiry_id: productInquiryId }
