  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: { id: inquiry.product_id, seller_id: seller.id }
  });
  if (!product) throw new Error('Forbidden: Seller does not own this product inquiry');

  // 4. Map status to allowed enum (defensive against data errors)
  const allowedStatuses = ["waiting", "answered", "blocked", "under_review", "deleted"] as const;
  const status = allowedStatuses.includes(snapshot.status as typeof allowedStatuses[number])
    ? snapshot.status as typeof allowedStatuses[number]
    : "waiting";

  // 5. Return the correctly formatted DTO
  return {
    id: snapshot.id,
    inquiry_id: snapshot.inquiry_id,
    title: snapshot.title,
    body: snapshot.body,
    public: snapshot.public,
    status,
    actor_id: snapshot.actor_id,
    ai_sentiment_score: snapshot.ai_sentiment_score ?? null,
    ai_spam_score: snapshot.ai_spam_score ?? null,
    changed_at: toISOStringSafe(snapshot.changed_at),
  };
}

