 * Soft-deletes a single transaction record—marking the 'deleted_at' field, not physically removing it—in the mileage_transactions table for a specific wallet/transaction pair. Ensures compliance by preserving audit and rollback evidence. Unavailable or already deleted records trigger explicit error responses, and all deletions are logged for evidence.
 *
 * @param props - Request properties
 * @param props.customer - Authenticated customer making the request (CustomerPayload)
 * @param props.mileageWalletId - UUID of the mileage wallet
 * @param props.mileageTransactionId - UUID of the mileage transaction to delete
 * @returns void
 * @throws {Error} When the wallet is not found or not owned by the customer
 * @throws {Error} When the transaction does not exist or is already deleted
 */
export async function delete__shoppingMallAiBackend_customer_mileageWallets_$mileageWalletId_mileageTransactions_$mileageTransactionId(
  props: {
    customer: CustomerPayload;
    mileageWalletId: string & tags.Format<'uuid'>;
    mileageTransactionId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { customer, mileageWalletId, mileageTransactionId } = props;

  // 1. Fetch and verify wallet belongs to customer
  const wallet = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findFirst({
    where: {
      id: mileageWalletId,
      customer_id: customer.id,
      deleted_at: null,
    },
  });
  if (!wallet) {
    throw new Error("Mileage wallet not found or not owned by customer");
  }

  // 2. Fetch and verify transaction exists and is active (not deleted)
  const tx = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.findFirst({
    where: {
      id: mileageTransactionId,
      wallet_id: mileageWalletId,
      deleted_at: null,
