  }

  // 3. Soft-delete transaction by updating deleted_at
  await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.update({
    where: { id: mileageTransactionId },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });
}

