  const ownedProducts = await MyGlobal.prisma.shopping_mall_ai_backend_products.findMany({
    where: { seller_id: seller.id, deleted_at: null },
    select: { id: true }
  });
  const ownedProductIds = ownedProducts.map(p => p.id);
  if (ownedProductIds.length === 0) {
    return {
      pagination: {
        current: body.page,
        limit: body.limit,
        records: 0,
        pages: 0,
      },
      data: [],
    };
  }

  // 2. 리뷰 where절 조립 (검색 필터)
  const reviewWhere = {
    product_id: { in: ownedProductIds },
    ...(body.product_id !== undefined && body.product_id !== null && { product_id: body.product_id }),
    ...(body.customer_id !== undefined && body.customer_id !== null && { customer_id: body.customer_id }),
