            ...(body.rating_to !== undefined && body.rating_to !== null ? { lte: body.rating_to } : {}),
          },
        }
      : {}),
    ...((body.created_at_from !== undefined && body.created_at_from !== null) || (body.created_at_to !== undefined && body.created_at_to !== null)
      ? {
          created_at: {
            ...(body.created_at_from !== undefined && body.created_at_from !== null ? { gte: body.created_at_from } : {}),
            ...(body.created_at_to !== undefined && body.created_at_to !== null ? { lte: body.created_at_to } : {}),
          },
        }
      : {}),
    ...(body.search
      ? {
          OR: [
            { title: { contains: body.search, mode: 'insensitive' as const } },
            { body: { contains: body.search, mode: 'insensitive' as const } },
          ],
        }
      : {}),
    deleted_at: null,
  };

  // 3. 전체 레코드 수 계산
  const total = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.count({
    where: reviewWhere,
  });

  // 4. 정렬 조건
  const orderBy = body.sort_by
    ? { [body.sort_by]: body.sort_direction === 'asc' ? 'asc' : 'desc' }
    : { created_at: 'desc' };

  // 5. 페이징(페이지 단위 데이터 조회)
  const reviews = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findMany({
    where: reviewWhere,
    orderBy,
    skip: (body.page - 1) * body.limit,
    take: body.limit,
  });

  const pages = total === 0 ? 0 : Math.ceil(total / body.limit);

  // 6. DTO 변환 및 ISO date branding 적용
  return {
    pagination: {
      current: total === 0 ? 1 : body.page,
      limit: body.limit,
      records: total,
      pages: pages,
    },
    data: reviews.map((r) => ({
      id: r.id,
      customer_id: r.customer_id,
      product_id: r.product_id,
      order_item_id: r.order_item_id,
      title: r.title ?? null,
      rating: r.rating,
      status: r.status,
      created_at: toISOStringSafe(r.created_at),
      deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null,
    })),
  };
}

