 * @throws {Error} When credentials are invalid, account is not active, or soft-deleted
 */
export async function post__auth_admin_login(
  props: { body: IAdminAuth.SignIn }
): Promise<IAdminAuth.JwtWithProfile> {
  const { email, password } = props.body;
  // Strictly find active, not-deleted admin
