/**
 * Advanced, filterable, paginated search for product inquiries for authenticated customers.
 *
 * Returns a paginated, filtered, and sorted list of product inquiries belonging to the authenticated customer only. The customer can apply filters such as product ID, inquiry status, AI sentiment/spam score, creation date ranges, and perform full-text search on inquiry title/body. Results are paginated and only permitted fields are allowed for sorting. This function ensures access control by restricting queries to inquiries of the authenticated customer.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.body - Filter, sorting, and pagination instructions following IShoppingMallAiBackendProductInquiry.IRequest
 * @returns Paginated product inquiries with metadata summarizing pagination and filtered/sorted result set
 * @throws {Error} If access is attempted to product inquiries not belonging to the customer, or for any unexpected query failures
 */
export async function patch__shoppingMallAiBackend_customer_productInquiries(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiBackendProductInquiry.IRequest;
}): Promise<IPageIShoppingMallAiBackendProductInquiry> {
  const { customer, body } = props;
  const page = typeof body.page === 'number' && body.page >= 1 ? body.page : 1;
  const page_size = typeof body.page_size === 'number' && body.page_size >= 1 && body.page_size <= 100 ? body.page_size : 20;
  const allowedSorts = ["created_at", "ai_sentiment_score", "ai_spam_score", "status"] as const;
  const sort_by = allowedSorts.includes(body.sort_by as (typeof allowedSorts)[number]) ? body.sort_by : "created_at";
  const sort_order = body.sort_order === 'asc' ? 'asc' : 'desc';

  const where = {
    customer_id: customer.id,
    deleted_at: null,
    ...(body.product_id !== undefined && body.product_id !== null && { product_id: body.product_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.public !== undefined && body.public !== null && { public: body.public }),
    ...(typeof body.min_ai_sentiment_score === 'number' && { ai_sentiment_score: { gte: body.min_ai_sentiment_score } }),
    ...(typeof body.max_ai_sentiment_score === 'number' && { ai_sentiment_score: { lte: body.max_ai_sentiment_score } }),
    ...((body.created_from !== undefined && body.created_from !== null) || (body.created_to !== undefined && body.created_to !== null)
      ? {
          created_at: {
            ...(body.created_from !== undefined && body.created_from !== null && { gte: body.created_from }),
            ...(body.created_to !== undefined && body.created_to !== null && { lte: body.created_to })
          }
        }
      : {}),
    ...(body.search !== undefined && body.search !== null && body.search.length > 0 && {
      OR: [
        { title: { contains: body.search, mode: 'insensitive' as const } },
        { body: { contains: body.search, mode: 'insensitive' as const } }
      ]
    })
  };

  const [rows, count] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.findMany({
      where,
      orderBy: { [sort_by]: sort_order },
      skip: (page - 1) * page_size,
      take: page_size
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.count({ where })
  ]);

  return {
    pagination: {
      current: page,
      limit: page_size,
      records: count,
      pages: Math.ceil(count / page_size)
    },
    data: rows.map(r => ({
      id: r.id,
      customer_id: r.customer_id,
      product_id: r.product_id,
      title: r.title,
      body: r.body,
      public: r.public,
      status: r.status,
      answer_id: r.answer_id ?? null,
      ai_sentiment_score: r.ai_sentiment_score ?? null,
      ai_spam_score: r.ai_spam_score ?? null,
      created_at: toISOStringSafe(r.created_at),
      updated_at: toISOStringSafe(r.updated_at),
      deleted_at: r.deleted_at ? toISOStringSafe(r.deleted_at) : null
