/**
 * Search all snapshots of a product review.
 *
 * Enables full search and retrieval of all historical snapshots for a specific product review. Each snapshot provides the business content, rating, status, actor, and metadata as it was at the time. Access is controlled—customers see their review snapshots, sellers access snapshots for owned product reviews, admins have unrestricted visibility.
 *
 * Supports detailed audit, reverse chronological ordering, and bulk export. Used in legal disputes, recovery, and compliance reporting. Errors are returned for invalid IDs, insufficient permission, or out-of-bounds filters.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer making the request
 * @param props.productReviewId - UUID of the parent product review
 * @param props.body - Advanced filter criteria for review snapshots
 * @returns Paginated list of review snapshot resources matching query filters
 * @throws {Error} When the review does not exist or does not belong to the authenticated customer
 */
export async function patch__shoppingMallAiBackend_customer_productReviews_$productReviewId_reviewSnapshots(props: {
  customer: CustomerPayload;
  productReviewId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendReviewSnapshot.IRequest;
}): Promise<IPageIShoppingMallAiBackendReviewSnapshot> {
  const { customer, productReviewId, body } = props;

  // Strict ownership & soft delete check
  const review = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findFirst({
    where: { id: productReviewId, deleted_at: null },
    select: { customer_id: true },
  });
  if (!review || review.customer_id !== customer.id) {
    throw new Error('Access denied');
  }

  // Pagination setup (max 100)
  const page = typeof body.page === 'number' && body.page > 0 ? body.page : 1;
  const limit = typeof body.limit === 'number' && body.limit > 0 ? Math.min(body.limit, 100) : 20;
  const skip = (page - 1) * limit;

  // Filter construction - handle undefined/null properly for required fields
  const where = {
    review_id: productReviewId,
    ...(body.actor_id !== undefined && body.actor_id !== null && { actor_id: body.actor_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.rating !== undefined && body.rating !== null && { rating: body.rating }),
    ...((body.changed_at_from !== undefined && body.changed_at_from !== null) ||
      (body.changed_at_to !== undefined && body.changed_at_to !== null)
      ? {
          changed_at: {
            ...(body.changed_at_from !== undefined && body.changed_at_from !== null && { gte: body.changed_at_from }),
            ...(body.changed_at_to !== undefined && body.changed_at_to !== null && { lte: body.changed_at_to }),
          },
        }
      : {}),
  };

  // Sorting (only allowed fields)
  const allowedSortFields = ["changed_at", "status", "rating"];
  const sortField = allowedSortFields.includes(body.sort_by ?? "") ? body.sort_by! : "changed_at";
  const sortOrder = body.sort_direction === "asc" ? "asc" : "desc";

  // Count for pagination
  const total = await MyGlobal.prisma.shopping_mall_ai_backend_review_snapshots.count({ where });

  // Query actual review snapshots
  const results = await MyGlobal.prisma.shopping_mall_ai_backend_review_snapshots.findMany({
    where,
    orderBy: {
      [sortField]: sortOrder,
    },
    skip,
    take: limit,
  });

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: results.map((item) => ({
      id: item.id,
      review_id: item.review_id,
      body: item.body,
      rating: item.rating,
      status: item.status,
      actor_id: item.actor_id,
      ai_sentiment_score: item.ai_sentiment_score ?? null,
      ai_spam_score: item.ai_spam_score ?? null,
      changed_at: toISOStringSafe(item.changed_at),
    })),
  };
}

