/**
 * 상품 리뷰 고급 검색 (고객 본인 소유 리뷰만 페이징/정렬/필터)
 *
 * 이 엔드포인트는 로그인한 고객의 상품 리뷰를 다양한 필터와 전체 텍스트 검색, 페이징/정렬 조건 하에 조회합니다.
 * 검색 조건: 상품, 평점 구간, 상태, 작성일 구간, 키워드 등. 반드시 본인(customer)만 접근 가능합니다.
 *
 * 보안 모델: 고객은 자신의 리뷰만 접근/검색 가능. 다른 고객의 리뷰 접근 시도 시 무조건 차단됩니다.
 *
 * @param props - 요청 프로퍼티
 *   @param props.customer - 인증된 고객 페이로드 (CustomerPayload)
 *   @param props.body - 검색/필터 요구 파라미터 (IShoppingMallAiBackendProductReview.IRequest)
 * @returns { pagination, data } (IPageIShoppingMallAiBackendProductReview.ISummary)
 * @throws {Error}   - 인증 실패/권한 위반시
 */
export async function patch__shoppingMallAiBackend_customer_productReviews(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendProductReview.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendProductReview.ISummary> {
  const { customer, body } = props;

  // Always restrict to current customer
  const where = {
    customer_id: customer.id,
    ...(body.product_id !== undefined && body.product_id !== null && { product_id: body.product_id }),
    ...(body.order_item_id !== undefined && body.order_item_id !== null && { order_item_id: body.order_item_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    // Rating range (gte/lte)
    ...((body.rating_from !== undefined && body.rating_from !== null) && { rating: { gte: body.rating_from } }),
    ...((body.rating_to !== undefined && body.rating_to !== null) && {
      rating: {
        ...((body.rating_from !== undefined && body.rating_from !== null) ? { gte: body.rating_from } : {}),
        lte: body.rating_to
      }
    }),
    // Created_at range (gte/lte)
    ...((body.created_at_from !== undefined && body.created_at_from !== null) && {
      created_at: { gte: body.created_at_from }
    }),
    ...((body.created_at_to !== undefined && body.created_at_to !== null) && {
      created_at: {
        ...((body.created_at_from !== undefined && body.created_at_from !== null) ? { gte: body.created_at_from } : {}),
        lte: body.created_at_to
      }
    }),
    // Free-text search (OR, both title/body)
    ...(typeof body.search === "string" && body.search.trim().length > 0 && {
      OR: [
        { title: { contains: body.search, mode: "insensitive" as const } },
        { body: { contains: body.search, mode: "insensitive" as const } }
      ]
    })
  };

  const orderBy = body.sort_by
    ? { [body.sort_by]: body.sort_direction === "asc" ? "asc" : "desc" }
    : { created_at: "desc" };
  const skip = (body.page - 1) * body.limit;
  const take = body.limit;

  // Query database in parallel for pagination
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findMany({
      where,
      orderBy,
      skip,
      take,
      select: {
        id: true,
        customer_id: true,
        product_id: true,
        order_item_id: true,
        title: true,
        rating: true,
        status: true,
        created_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.count({ where })
  ]);

  // Convert output to API structure with strict type safety
  const data = rows.map(row => ({
    id: row.id,
    customer_id: row.customer_id,
    product_id: row.product_id,
    order_item_id: row.order_item_id,
    title: row.title,
    rating: row.rating,
    status: row.status as "normal"|"blocked"|"deleted",
    created_at: toISOStringSafe(row.created_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
  }));

  const pages = Math.max(1, Math.ceil(total / take));
  return {
    pagination: {
      current: body.page,
      limit: take,
      records: total,
      pages,
    },
    data
  };
}

