/**
 * Submit a new appeal (objection) to a moderation event.
 *
 * This endpoint allows an authenticated customer to submit a formal objection to a moderation event (such as block/edit) related to their content/activity. The appeal will always be attributed to the authenticated customer. No two appeals by the same customer for the same event are allowed (duplicates are rejected).
 *
 * @param props - Request parameter object
 * @param props.customer - Authenticated customer submitting the appeal (CustomerPayload)
 * @param props.body - Appeal creation data (IShoppingMallAiBackendAppeal.ICreate)
 * @returns Newly created appeal record as IShoppingMallAiBackendAppeal
 * @throws {Error} When a duplicate appeal is detected, or on database/logic error
 */
export async function post__shoppingMallAiBackend_customer_appeals(
  props: { customer: CustomerPayload; body: IShoppingMallAiBackendAppeal.ICreate }
): Promise<IShoppingMallAiBackendAppeal> {
  const { customer, body } = props;
  const appellant_id: string & tags.Format<'uuid'> = customer.id;
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  // Check for existing (not deleted) appeal by this customer to this event
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.findFirst({
    where: {
      moderation_event_id: body.moderation_event_id,
      appellant_id,
      deleted_at: null,
    },
  });
  if (duplicate) {
    throw new Error('You have already submitted an appeal to this moderation event.');
  }
  // Create a new appeal
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_appeals.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      moderation_event_id: body.moderation_event_id,
      appellant_id,
      status: body.status,
      decision_comment: body.decision_comment ?? null,
      created_at: now,
      updated_at: now,
    }
  });
  // Return DTO-compliant response
  return {
    id: created.id,
    moderation_event_id: created.moderation_event_id,
    appellant_id: created.appellant_id,
    status: created.status,
    decision_comment: created.decision_comment ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendProductReview";
import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Allows a customer to submit a new product review after completing a purchase, referencing the related product and order item.
 *
 * Full user identity, purchase validation, and AI moderation are enforced.
 * Fields include title (optional), body, rating, and required product/order reference.
 * Stores AI sentiment/spam results, and all compliance/audit data.
 *
 * If duplicate review is attempted, policy violation or abusive content, the operation rejects creation and delivers descriptive error (max one review per product per order allowed).
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer (CustomerPayload, required)
 * @param props.body - Details for creating the product review (product_id, order_item_id, title?, body, rating, status, ai fields)
 * @returns The created product review as IShoppingMallAiBackendProductReview
 * @throws {Error} If a duplicate review exists for this (customer, product, order item)
 * @throws {Error} If provided order item does not belong to the customer or does not match product
 */
export async function post__shoppingMallAiBackend_customer_productReviews(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendProductReview.ICreate;
  }
): Promise<IShoppingMallAiBackendProductReview> {
  const { customer, body } = props;
  // 1. Enforce singularity for review per (customer, product, order item)
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.findFirst({
    where: {
      customer_id: customer.id,
      product_id: body.product_id,
      order_item_id: body.order_item_id,
      deleted_at: null,
    },
  });
  if (existing) {
    throw new Error("Duplicate review for this product and order item is not allowed.");
  }
  // 2. Validate order_item existence and parent order ownership
  const orderItem = await MyGlobal.prisma.shopping_mall_ai_backend_order_items.findUnique({
    where: { id: body.order_item_id },
  });
  if (!orderItem) {
    throw new Error("Order item does not exist.");
  }
  if (orderItem.product_id !== body.product_id) {
    throw new Error("Order item does not match the specified product.");
  }
  const order = await MyGlobal.prisma.shopping_mall_ai_backend_orders.findUnique({
    where: { id: orderItem.order_id },
  });
  if (!order || order.customer_id !== customer.id) {
    throw new Error("Order does not belong to the authenticated customer.");
  }
  // 3. Prepare created_at/updated_at timestamps (as ISO string)
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  // 4. Create review record
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_product_reviews.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      customer_id: customer.id,
      product_id: body.product_id,
      order_item_id: body.order_item_id,
      title: body.title ?? null,
      body: body.body,
      rating: body.rating,
      status: body.status,
      ai_sentiment_score: body.ai_sentiment_score ?? null,
      ai_spam_score: body.ai_spam_score ?? null,
      created_at: now,
      updated_at: now,
      deleted_at: null,
    },
  });
  // 5. Map all fields to result DTO
  return {
    id: created.id,
    customer_id: created.customer_id,
    product_id: created.product_id,
    order_item_id: created.order_item_id,
    title: created.title,
    body: created.body,
    rating: created.rating,
    status: created.status as "normal" | "blocked" | "deleted",
    ai_sentiment_score: created.ai_sentiment_score ?? null,
    ai_spam_score: created.ai_spam_score ?? null,
    created_at: toISOStringSafe(created.created_at),
    updated_at: toISOStringSafe(created.updated_at),
    deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null,
  };
}

