/**
 * Removes a mapping between a product and a specific channel (soft delete) as the product's seller.
 *
 * Only the seller who owns the product may perform this action. Performs soft-delete by
 * setting deleted_at field to the current time (ISO8601-formatted string). If the mapping is already deleted
 * or does not exist, throws an error to preserve idempotence and avoid race conditions.
 *
 * @param props - Request properties
 * @param props.seller - The authenticated seller making the request
 * @param props.productId - UUID of the product whose channel mapping will be removed
 * @param props.productChannelMapId - UUID of the product-channel mapping to delete
 * @returns void
 * @throws {Error} If the mapping does not exist or has already been deleted
 * @throws {Error} If the caller does not own the product
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId_productChannelMap_$productChannelMapId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productChannelMapId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { seller, productId, productChannelMapId } = props;

  // 1. Lookup: mapping for this product in this channel, not deleted
  const mapping = await MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.findFirst({
    where: {
      id: productChannelMapId,
      product_id: productId,
      deleted_at: null,
    },
  });
  if (!mapping) {
    throw new Error("Mapping not found or already deleted");
  }

  // 2. Authorization: Only the seller who owns the product can soft-delete mapping
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findFirst({
    where: { id: productId },
    select: { seller_id: true },
  });
  if (!product || product.seller_id !== seller.id) {
    throw new Error("Forbidden: Only the product's owner can remove this mapping");
  }

  // 3. Soft delete: set deleted_at to now (ISO8601 string)
  await MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.update({
    where: { id: mapping.id },
    data: {
      deleted_at: toISOStringSafe(new Date()),
    },
  });

  return;
}

