 *
 * @param props - Request properties (body: ICustomerSignUp.Request)
 * @returns Registration response with JWT and customer profile per API spec
 * @throws {Error} When email or nickname is already registered, or there is a hashing/JWT error
 */
export async function post__auth_customer_register(props: { body: ICustomerSignUp.Request }): Promise<ICustomerSignUp.Response> {
  const { body } = props;

  // Validate uniqueness for email and nickname (both unique)
  const duplicate = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: {
      OR: [
        { email: body.email },
        { nickname: body.nickname }
      ]
    }
  });
  if (duplicate) {
    if (duplicate.email === body.email) throw new Error("Email already registered");
    throw new Error("Nickname already registered");
  }

  // Password hashing (PBKDF2-SHA256, browser-only)
  const salt = window.crypto.getRandomValues(new Uint8Array(16));
  const password_hash = await pbkdf2Sha256(body.password, salt, 150000, 32);

  // Prepare timestamps and IDs (always as string & tags.Format<'date-time'>, string & tags.Format<'uuid'>)
  const now = toISOStringSafe(new Date());
  const customer_id = v4() as string & tags.Format<'uuid'>;
  const history_id = v4() as string & tags.Format<'uuid'>;

  // Create the customer (all unprovided optional fields are set as null)
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_customers.create({
    data: {
      id: customer_id,
      email: body.email,
      password_hash,
      name: body.name,
      nickname: body.nickname,
      phone: body.phone,
      status: "active",
      email_verified: false,
      phone_verified: false,
      joined_at: now,
      created_at: now,
      updated_at: now,
      last_login_at: null,
      profile_image_uri: null,
      deleted_at: null
    }
  });

  // Write the audit event in customer histories
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: history_id,
      customer_id: customer_id,
      event_type: "created",
      old_value_json: null,
      new_value_json: JSON.stringify({ ...created, password_hash: undefined }),
      triggered_by: "user",
      meta_json: null,
      occurred_at: now,
      created_at: now
    }
  });

  // Issue a JWT for auth (browser-native, not Node.js crypto)
  const Authorization = await signJwt({ id: customer_id, email: body.email });

  // Respond with full customer profile (no password_hash)
  return {
    customer: {
      id: created.id as string & tags.Format<'uuid'>,
      email: created.email,
      name: created.name,
      nickname: created.nickname,
      phone: created.phone,
      status: created.status,
      email_verified: created.email_verified,
      phone_verified: created.phone_verified,
      profile_image_uri: created.profile_image_uri,
      joined_at: toISOStringSafe(created.joined_at),
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      last_login_at: created.last_login_at ? toISOStringSafe(created.last_login_at) : null,
      deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
    },
    setHeaders: {
      Authorization
    }
  };
}

/**
 * Hash a password with a salt using PBKDF2-SHA256 using browser Web Crypto API.
 * Returns lowercase hex string.
 */
async function pbkdf2Sha256(password: string, salt: Uint8Array, iterations: number, keyLength: number): Promise<string> {
  const enc = new TextEncoder();
  const key = await window.crypto.subtle.importKey(
    "raw",
    enc.encode(password),
    "PBKDF2",
    false,
    ["deriveBits"]
  );
  const derived = await window.crypto.subtle.deriveBits({
    name: "PBKDF2",
    salt,
    iterations,
    hash: "SHA-256"
  }, key, keyLength * 8);
  return Array.from(new Uint8Array(derived)).map(b => b.toString(16).padStart(2, "0")).join("");
}

/**
 * Minimal browser-safe JWT issuing function (placeholder).
 * To be replaced for production-worthy JWT.
 */
async function signJwt(payload: { id: string; email: string }): Promise<string> {
  // Use browser-friendly base64url encoding (not Node.js crypto)
  const header = { alg: "HS256", typ: "JWT" };
  const now = Math.floor(Date.now() / 1000);
  const body = { ...payload, iat: now, exp: now + 60 * 60 * 24 * 7 };
  const encode = (obj: object) => btoa(JSON.stringify(obj)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  return encode(header) + "." + encode(body) + ".";
}

