/**
 * Soft-delete a product snapshot for a product (shopping_mall_ai_backend_product_snapshots).
 *
 * Soft-delete a product snapshot record. The snapshot is preserved for evidence
 * but excluded from standard queries. Deleted_at is set per policy, and all actions
 * are tracked in admin/seller audit logs. Only admins or product owners can perform this operation.
 * Returns 404 if not present, 403 if permissions are insufficient.
 *
 * @param props - Request properties
 * @param props.seller - Authenticated seller (must own the product)
 * @param props.productId - UUID of the product to which the snapshot belongs
 * @param props.productSnapshotId - UUID of the snapshot to soft-delete
 * @returns void
 * @throws {Error} 404 If the snapshot or product does not exist
 * @throws {Error} 403 If the seller does not own the product
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId_productSnapshots_$productSnapshotId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productSnapshotId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { seller, productId, productSnapshotId } = props;

  // 1. Find snapshot not already deleted and attached to product
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_product_snapshots.findFirst({
    where: {
      id: productSnapshotId,
      product_id: productId,
      deleted_at: null,
    },
  });
  if (!snapshot) {
    throw new Error("Product snapshot not found");
  }

  // 2. Check seller owns the product
  const product = await MyGlobal.prisma.shopping_mall_ai_backend_products.findUnique({
    where: { id: productId },
    select: { seller_id: true },
  });
  if (!product) {
    throw new Error("Product not found");
  }
  if (product.seller_id !== seller.id) {
    throw new Error("Forbidden: You do not have permission to delete this snapshot");
  }

  // 3. Soft-delete the snapshot by setting deleted_at
  await MyGlobal.prisma.shopping_mall_ai_backend_product_snapshots.update({
    where: { id: productSnapshotId },
    data: { deleted_at: toISOStringSafe(new Date()) },
  });
}

