      select: { id: true, current_status: true },
    });
    if (orders.some(order => order.current_status === 'locked' || order.current_status === 'reconciled')) {
      throw new Error('Cannot delete: Coupon usage is attached to a locked or reconciled order.');
    }
  }

  // Soft-delete by setting deleted_at
  const now = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_coupon_usages.update({
    where: { id: couponUsageId },
    data: { deleted_at: now },
  });

  // Log auditing event
  await MyGlobal.prisma.shopping_mall_ai_backend_compliance_events.create({
    data: {
      id: v4(),
      event_type: 'coupon_usage.soft_delete',
      actor_id: admin.id,
      actor_type: 'admin',
      target_type: 'coupon_usage',
      target_id: couponUsageId,
      event_payload: null,
      created_at: now,
    },
  });
}

