    where: { id: productId, seller_id: seller.id, deleted_at: null },
  });
  if (!product) throw new Error("Forbidden: Product not found or not owned by seller");

  // 2. 페이지네이션 파라미터
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;

  // 3. where 조건
  const where = {
    product_id: productId,
    deleted_at: null,
    ...(body.channel_id !== undefined && body.channel_id !== null && { channel_id: body.channel_id }),
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.search
      ? {
          OR: [
            { status: { contains: body.search, mode: "insensitive" as const } },
          ],
        }
      : {}),
  };

  // 4. 정렬 조건
  const orderBy = body.sort
    ? { [body.sort]: body.direction === 'asc' ? 'asc' : 'desc' }
    : { created_at: 'desc' };

  // 5. 데이터 가져오기 (동시 fetch)
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.findMany({
      where,
      orderBy,
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_channel_map.count({ where }),
  ]);

  // 6. 결과 변환: 날짜 필드 ISO string 변환
  const data = rows.map(row => ({
    id: row.id,
    product_id: row.product_id,
    channel_id: row.channel_id,
    status: row.status,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  // 7. 페이징 결과 반환
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

