 * @param props.seller - Authenticated seller (must own the product)
 * @param props.productId - UUID of the product (parent of the snapshot)
 * @param props.productSnapshotId - UUID of the snapshot to soft-delete
 * @returns void
 * @throws {Error} When the snapshot is not found or already deleted (404)
 * @throws {Error} When the seller is not authorized (not product owner) (403)
 */
export async function delete__shoppingMallAiBackend_seller_products_$productId_productSnapshots_$productSnapshotId(
  props: {
    seller: SellerPayload;
    productId: string & tags.Format<'uuid'>;
    productSnapshotId: string & tags.Format<'uuid'>;
  }
): Promise<void> {
  const { seller, productId, productSnapshotId } = props;
  // 1. Find soft-deletable snapshot
  const snapshot = await MyGlobal.prisma.shopping_mall_ai_backend_product_snapshots.findFirst({
    where: {
      id: productSnapshotId,
      product_id: productId,
      deleted_at: null,
