import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { ICustomerSignUp } from "@ORGANIZATION/PROJECT-api/lib/structures/ICustomerSignUp";
import { IShoppingMallAiBackendCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendCustomer";


/**
 * Register a new customer (shopping_mall_ai_backend_customers) and issue JWT token.
 *
 * This API endpoint enables customer self-registration using only browser-compatible and functional code.
 * - Validates uniqueness of email and nickname.
 * - Hashes password with browser-native PBKDF2-SHA256 (never uses native Date in any declaration, only branded strings).
 * - Logs audit event in shopping_mall_ai_backend_customer_histories for compliance.
 * - Issues browser-compatible (non-production, placeholder) JWT for immediate session.
 *
 * @param props - Object with { body: ICustomerSignUp.Request }
 * @returns Promise<ICustomerSignUp.Response> with customer and JWT header per API spec
 * @throws {Error} If email/nickname already exist, hashing fails, or other validation error
 */
export async function post__auth_customer_register(props: { body: ICustomerSignUp.Request }): Promise<ICustomerSignUp.Response> {
  const { body } = props;

  // Duplicate detection
  const existing = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: {
      OR: [ { email: body.email }, { nickname: body.nickname } ]
    }
  });
  if (existing) {
    if (existing.email === body.email) throw new Error("Email already exists");
    throw new Error("Nickname already exists");
  }

  // Hash the password securely (browser-safe PBKDF2-SHA256)
  const salt = window.crypto.getRandomValues(new Uint8Array(16));
  const password_hash = await pbkdf2Sha256(body.password, salt, 150000, 32);

  // All branded values for ID/timestamps
  const customer_id = typia.assertGuard<string & tags.Format<'uuid'>>(v4());
  const history_id = typia.assertGuard<string & tags.Format<'uuid'>>(v4());
  const now = toISOStringSafe(new Date());

  // Create customer per schema
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_customers.create({
    data: {
      id: customer_id,
      email: body.email,
      password_hash,
      name: body.name,
      nickname: body.nickname,
      phone: body.phone,
      status: "active",
      email_verified: false,
      phone_verified: false,
      joined_at: now,
      created_at: now,
      updated_at: now,
      last_login_at: null,
      profile_image_uri: null,
      deleted_at: null
    }
  });

  // Audit logging
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: history_id,
      customer_id,
      event_type: "created",
      old_value_json: null,
      new_value_json: JSON.stringify({ ...created, password_hash: undefined }),
      triggered_by: "user",
      meta_json: null,
      occurred_at: now,
      created_at: now
    }
  });

  // Issue JWT (browser demo only)
  const Authorization = await signJwt({ id: customer_id, email: body.email });

  // Build API response, only API-specified fields
  return {
    customer: {
      id: created.id,
      email: created.email,
      name: created.name,
      nickname: created.nickname,
      phone: created.phone,
      profile_image_uri: created.profile_image_uri,
      status: created.status,
      email_verified: created.email_verified,
      phone_verified: created.phone_verified,
      joined_at: toISOStringSafe(created.joined_at),
      last_login_at: created.last_login_at ? toISOStringSafe(created.last_login_at) : null,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
    },
    setHeaders: { Authorization }
  };
}

/**
 * Hashes a password using PBKDF2-SHA256 in browser (returns lowercase hex string).
 */
async function pbkdf2Sha256(password: string, salt: Uint8Array, iterations: number, keyLength: number): Promise<string> {
  const enc = new TextEncoder();
  const key = await window.crypto.subtle.importKey(
    "raw", enc.encode(password), "PBKDF2", false, ["deriveBits"]
  );
  const derived = await window.crypto.subtle.deriveBits(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    key,
    keyLength * 8
  );
  return Array.from(new Uint8Array(derived)).map(b => b.toString(16).padStart(2, "0")).join("");
}

/**
 * Minimal, browser-only JWT issue (not secure!) for demonstration.
 */
async function signJwt(payload: { id: string; email: string }): Promise<string> {
  const header = { alg: "HS256", typ: "JWT" };
  const now = Math.floor(Date.now() / 1000);
  const body = { ...payload, iat: now, exp: now + 60 * 60 * 24 * 7 };
  const encode = (obj: object) => btoa(JSON.stringify(obj)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
  return `${encode(header)}.${encode(body)}.`;
}

