  const allowedSortFields = ['changed_at', 'status'] as const;
  const sort_by = allowedSortFields.includes(body.sort_by) && body.sort_by ? body.sort_by : 'changed_at';
  const sort_direction = body.sort_direction === 'asc' ? 'asc' : 'desc';
