import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSystemSetting";
import { IPageIShoppingMallAiBackendSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallAiBackendSystemSetting";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Retrieve a paginated, filterable list of system configuration settings as an admin.
 *
 * Retrieves a paginated and filterable list of system settings entries from
 * shopping_mall_ai_backend_system_settings. Only active (deleted_at == null) settings are included.
 * Supports pagination, conf_key/description filters, and free-text search (conf_key/description, case-insensitive).
 * Only authenticated admins may access; audit compliance is required.
 *
 * @param props - Request properties
 * @param props.admin - Authenticated admin user
 * @param props.body - Filtering, search, and pagination parameters for settings retrieval
 * @returns Paginated summary list with metadata
 * @throws {Error} If unauthorized or parameters invalid
 */
export async function patch__shoppingMallAiBackend_admin_systemSettings(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendSystemSetting.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendSystemSetting.ISummary> {
  const { admin, body } = props;

  // --- Authorization is handled by controller/decorator, included for completeness ---
  if (!admin || admin.type !== "admin") {
    throw new Error("Unauthorized: only admins may access system settings");
  }

  // --- Pagination logic ---
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const limit = typeof body.limit === "number" && body.limit > 0 && body.limit <= 100 ? body.limit : 20;

  // --- Build where condition ---
  const where = {
    deleted_at: null,
    ...(body.conf_key && { conf_key: body.conf_key }),
    ...(body.description && {
      description: {
        contains: body.description,
        mode: "insensitive" as const,
      },
    }),
    ...(
      body.search
        ? {
            OR: [
              {
                conf_key: {
                  contains: body.search,
                  mode: "insensitive" as const,
                },
              },
              {
                description: {
                  contains: body.search,
                  mode: "insensitive" as const,
                },
              },
            ],
          }
        : {}
    ),
  };

  // --- Fetch paginated result and total count in parallel ---
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_system_settings.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { created_at: "desc" },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_system_settings.count({ where }),
  ]);

  // --- Map each row to ISummary DTO: handle UUID/date branding correctly ---
  const data = rows.map((row) => ({
    id: row.id,
    conf_key: row.conf_key,
    conf_value: row.conf_value,
    description: row.description ?? null,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  // --- Pagination metadata ---
  const pagination = {
    current: page,
    limit,
    records: total,
    pages: Math.ceil(total / limit),
  };

  return {
    pagination,
    data,
  };
}

