/**
 * Retrieve details of a specific system setting by UUID for admin audit or review.
 *
 * Fetch a specific system configuration setting by its unique UUID identifier. This operation is for administrative scenarios—detailed audit trails, compliance reviews, and system-level troubleshooting.
 *
 * The operation validates the presence of the record (not hard-deleted), returning its key (conf_key), value (conf_value), optional description, creation and update timestamps, and soft-delete status. If the setting is soft-deleted (deleted_at not null), include explicit status in the response to signal logical deletion. Access is restricted to users with admin privileges; attempts by unauthorized users are rejected with an appropriate error message and code for audit log.
 *
 * Error outcomes include record not found, permission denied, or invalid ID format.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin user making the request (validated by AdminAuth)
 * @param props.systemSettingId - UUID identifier of the target system setting
 * @returns Detailed information of the selected system setting, including audit fields and deletion status
 * @throws {Error} If the system setting is not found, or access is denied
 */
export async function get__shoppingMallAiBackend_admin_systemSettings_$systemSettingId(props: { admin: AdminPayload; systemSettingId: string & tags.Format<'uuid'> }): Promise<IShoppingMallAiBackendSystemSetting> {
  const { admin, systemSettingId } = props;

  const setting = await MyGlobal.prisma.shopping_mall_ai_backend_system_settings.findUnique({
    where: { id: systemSettingId },
    select: {
      id: true,
      conf_key: true,
      conf_value: true,
      description: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  if (!setting) {
    throw new Error('System setting not found');
  }
  return {
    id: setting.id,
    conf_key: setting.conf_key,
    conf_value: setting.conf_value,
    description: setting.description ?? null,
    created_at: toISOStringSafe(setting.created_at),
    updated_at: toISOStringSafe(setting.updated_at),
    deleted_at: setting.deleted_at ? toISOStringSafe(setting.deleted_at) : null,
  };
}

import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
