import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendSystemSetting } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendSystemSetting";
import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Create a new system configuration setting (admin only).
 *
 * Insert a new system setting as an admin. All fields must be supplied according to business rules (conf_key must be unique, conf_value meaningful, description optional but recommended for audit/compliance, timestamps are system-generated). This operation is audited, and all creations are recorded for later traceability.
 *
 * Rejects duplicate keys, empty/invalid values, or unauthorized users. On success, returns the created setting entry.
 *
 * @param props - The request properties
 * @param props.admin - The authenticated admin user payload
 * @param props.body - System setting creation details: conf_key, conf_value, and optional description
 * @returns The newly created system setting entry, with all audit fields populated
 * @throws {Error} If the conf_key is not unique or any unexpected database error occurs
 */
export async function post__shoppingMallAiBackend_admin_systemSettings(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendSystemSetting.ICreate;
  }
): Promise<IShoppingMallAiBackendSystemSetting> {
  const { admin, body } = props;

  // Generate current timestamp and new UUID for the record
  const now: string & tags.Format<'date-time'> = toISOStringSafe(new Date());
  const id: string & tags.Format<'uuid'> = v4() as string & tags.Format<'uuid'>;

  try {
    // Insert into database with all required fields
    const created = await MyGlobal.prisma.shopping_mall_ai_backend_system_settings.create({
      data: {
        id,
        conf_key: body.conf_key,
        conf_value: body.conf_value,
        description: body.description ?? null,
        created_at: now,
        updated_at: now
      },
    });

    // Transform all date fields to proper ISO string branding
    return {
      id: created.id as string & tags.Format<'uuid'>,
      conf_key: created.conf_key,
      conf_value: created.conf_value,
      description: created.description ?? null,
      created_at: toISOStringSafe(created.created_at),
      updated_at: toISOStringSafe(created.updated_at),
      deleted_at: created.deleted_at ? toISOStringSafe(created.deleted_at) : null
    };
  } catch (err) {
    // Unique constraint violation on conf_key (Prisma error code P2002)
    if (err instanceof Prisma.PrismaClientKnownRequestError && err.code === 'P2002') {
      throw new Error('System setting creation failed: conf_key must be unique.');
    }
    throw err;
  }
}

import { MyGlobal } from "../MyGlobal";
