import { MyGlobal } from "../MyGlobal";
import typia, { tags } from "typia";
import { Prisma } from "@prisma/client";
import { v4 } from "uuid";
import { toISOStringSafe } from "../util/toISOStringSafe"
import { IShoppingMallAiBackendMileageTransaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAiBackendMileageTransaction";
import { CustomerPayload } from "../decorators/payload/CustomerPayload"

/**
 * Records a new mileage transaction for the specified wallet.
 *
 * 이 엔드포인트는 주어진 마일리지 지갑에 대해 새로운 마일리지 트랜잭션을 생성합니다. 
 * 요청자는 반드시 해당 지갑의 소유자(고객)여야 하며, 트랜잭션 타입 및 사용 가능한 금액 등 비즈니스 규칙이 모든 검증을 통과해야 합니다.
 * 트랜잭션 생성 시 직전 트랜잭션의 잔고를 기준으로 신규 balance_after_transaction 값을 계산합니다.
 *
 * @param props - 요청 속성
 *   - props.customer: 인증된 고객 정보 (CustomerPayload)
 *   - props.mileageWalletId: 트랜잭션을 추가할 마일리지 지갑의 UUID
 *   - props.body: 트랜잭션 생성 데이터 (타입, 금액, 사유, 참조 등)
 * @returns 생성된 마일리지 트랜잭션 객체
 * @throws {Error} 지갑이 존재하지 않거나 소유자가 아닌 경우, 입력 값 유효성 위반, 잔액 부족 등
 */
export async function post__shoppingMallAiBackend_customer_mileageWallets_$mileageWalletId_mileageTransactions(
  props: {
    customer: CustomerPayload;
    mileageWalletId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendMileageTransaction.ICreate;
  }
): Promise<IShoppingMallAiBackendMileageTransaction> {
  const { customer, mileageWalletId, body } = props;

  // 1. 마일리지 지갑 존재 여부 및 소유자 검증
  const wallet = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_wallets.findFirst({
    where: {
      id: mileageWalletId,
      customer_id: customer.id,
      deleted_at: null,
    },
  });
  if (!wallet) {
    throw new Error('해당 마일리지 지갑이 존재하지 않거나 고객의 소유가 아닙니다.');
  }

  // 2. body.wallet_id가 path param과 일치하는지 검증
  if (body.wallet_id !== mileageWalletId) {
    throw new Error('지갑 ID가 요청 주소와 일치하지 않습니다.');
  }

  // 3. 트랜잭션 타입, 금액 부호 등 비즈니스 유효성 검사
  const allowedTypes = ['accumulate', 'redeem', 'expire', 'correction', 'grant'];
  if (!allowedTypes.includes(body.transaction_type)) {
    throw new Error('지원하지 않는 트랜잭션 타입입니다.');
  }
  if (
    ['redeem', 'expire', 'correction'].includes(body.transaction_type)
      ? body.mileage_amount > 0
      : body.mileage_amount < 0
  ) {
    throw new Error('해당 트랜잭션 타입에 올바르지 않은 금액 부호입니다.');
  }

  // 4. 최근 트랜잭션의 잔고 추출 → 신규 트랜잭션 후 잔고 계산
  const lastTx = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.findFirst({
    where: { wallet_id: mileageWalletId },
    orderBy: { created_at: 'desc' },
  });
  const prevBalance = lastTx ? lastTx.balance_after_transaction : 0;
  const newBalance = prevBalance + body.mileage_amount;
  if (newBalance < 0) {
    throw new Error('트랜잭션 후 잔고가 0 미만이 될 수 없습니다.');
  }

  // 5. 트랜잭션 생성
  const now = toISOStringSafe(new Date());
  const created = await MyGlobal.prisma.shopping_mall_ai_backend_mileage_transactions.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      wallet_id: mileageWalletId,
      transaction_type: body.transaction_type,
      mileage_amount: body.mileage_amount,
      balance_after_transaction: newBalance,
      reference_id: body.reference_id ?? null,
      transaction_reason: body.transaction_reason ?? null,
      created_at: now,
    },
  });

  // 6. 결과 Response 반환
  return {
    id: created.id,
    wallet_id: created.wallet_id,
    transaction_type: created.transaction_type,
    mileage_amount: created.mileage_amount,
    balance_after_transaction: created.balance_after_transaction,
    reference_id: created.reference_id,
    transaction_reason: created.transaction_reason,
    created_at: now,
  };
}

import { MyGlobal } from "../MyGlobal";
