      ? { created_at: {
          ...(body.created_from !== undefined && body.created_from !== null && { gte: body.created_from }),
          ...(body.created_to !== undefined && body.created_to !== null && { lte: body.created_to }),
        }}
      : {}),
    ...(body.search && body.search.length > 0 && {
      OR: [
        { title: { contains: body.search, mode: "insensitive" as const } },
        { body: { contains: body.search, mode: "insensitive" as const } },
      ],
    }),
  };
  const page = typeof body.page === "number" && body.page > 0 ? body.page : 1;
  const page_size = typeof body.page_size === "number" && body.page_size > 0 && body.page_size <= 100 ? body.page_size : 20;
  const allowedSort = ["created_at", "ai_sentiment_score", "ai_spam_score", "status"] as const;
  const sort_by = allowedSort.includes(body.sort_by as (typeof allowedSort)[number]) ? body.sort_by : "created_at";
  const sort_order = body.sort_order === "asc" ? "asc" : "desc";
  const [rows, count] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.findMany({
      where,
      orderBy: { [sort_by]: sort_order },
      skip: (page - 1) * page_size,
      take: page_size,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.count({ where }),
  ]);
  return {
    pagination: {
      current: page,
      limit: page_size,
      records: count,
      pages: Math.ceil(count / page_size),
    },
    data: rows.map((row) => ({
      id: row.id,
      customer_id: row.customer_id,
      product_id: row.product_id,
      title: row.title,
      body: row.body,
      public: row.public,
      status: row.status,
      answer_id: row.answer_id ?? null,
      ai_sentiment_score: row.ai_sentiment_score ?? null,
