 * @param props.productInquiryId - Unique UUID of the inquiry to fetch snapshots for
 * @param props.body - Filtering, sorting, and paging options per request
 * @returns Paginated list of inquiry snapshot objects for the specified inquiry
 * @throws {Error} If the inquiry does not exist or does not belong to the customer
 */
export async function patch__shoppingMallAiBackend_customer_productInquiries_$productInquiryId_inquirySnapshots(props: {
  customer: CustomerPayload;
  productInquiryId: string & tags.Format<'uuid'>;
  body: IShoppingMallAiBackendInquirySnapshot.IRequest;
}): Promise<IPageIShoppingMallAiBackendInquirySnapshot> {
  const { customer, productInquiryId, body } = props;

  // Step 1: Authorization - restrict to inquiry owner
  const inquiry = await MyGlobal.prisma.shopping_mall_ai_backend_product_inquiries.findFirst({
    where: {
      id: productInquiryId,
      customer_id: customer.id,
      deleted_at: null
    },
    select: { id: true }
  });
  if (!inquiry) throw new Error("Inquiry not found or you do not own this inquiry");

  // Step 2: Pagination 
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

