      ? {
          changed_at: {
            ...(body.changed_at_from !== undefined && body.changed_at_from !== null && { gte: body.changed_at_from }),
            ...(body.changed_at_to !== undefined && body.changed_at_to !== null && { lte: body.changed_at_to })
          }
        } : {})
  };

  // Step 4: Sorting
  const orderBy =
    body.sort_by === "status"
      ? { status: body.sort_direction === "asc" ? "asc" : "desc" }
      : { changed_at: body.sort_direction === "asc" ? "asc" : "desc" };

  // Step 5: Query data and count
  const [snapshots, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_inquiry_snapshots.findMany({ where, orderBy, skip, take: limit }),
    MyGlobal.prisma.shopping_mall_ai_backend_inquiry_snapshots.count({ where })
  ]);

  // Step 6: Map and format data
  const data = snapshots.map((row): IShoppingMallAiBackendInquirySnapshot => ({
    id: row.id,
    inquiry_id: row.inquiry_id,
    title: row.title,
    body: row.body,
    public: row.public,
    status: row.status,
    actor_id: row.actor_id,
    ai_sentiment_score: row.ai_sentiment_score ?? null,
    ai_spam_score: row.ai_spam_score ?? null,
    changed_at: toISOStringSafe(row.changed_at)
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.ceil(total / limit)
    },
