      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: snapshots.map((s) => ({
      id: s.id,
      inquiry_id: s.inquiry_id,
      title: s.title,
      body: s.body,
      public: s.public,
      status: s.status as "waiting" | "answered" | "blocked" | "under_review" | "deleted", // Enum branded string
      actor_id: s.actor_id,
