/**
 * 검색 및 필터링 조건에 따라 인증된 고객의 즐겨찾기 상품 목록을 페이징 형태로 조회합니다.
 *
 * 본 엔드포인트는 현재 로그인한 고객이 직접 추가한 즐겨찾기 상품들을 필터링, 검색어, 날짜 범위, 페이지네이션 등 다양한 조건과 함께 제공합니다.
 *
 * 오직 인증된 고객 본인만 자신의 즐겨찾기 상품 목록을 조회할 수 있으며, 판매자/관리자는 접근할 수 없습니다.
 *
 * 각 데이터는 생성일, 삭제여부와 연결된 상품 정보(추가 정보는 필요시 확장)와 함께 반환됩니다. 본 데이터는 AI 추천, 고객 알림 등에서 활용될 수 있습니다.
 *
 * @param props - 요청 파라미터 객체
 * @param props.customer - 인증된 고객 정보 (CustomerPayload)
 * @param props.body - 즐겨찾기 상품 목록 검색/필터/페이지네이션 요청 DTO
 * @returns 즐겨찾기 상품 페이징 목록 및 페이징 정보
 * @throws {Error} 인증되지 않은 접근 또는 비정상 파라미터, 서버 오류 발생 시 예외
 */
export async function patch__shoppingMallAiBackend_customer_favoriteProducts(
  props: {
    customer: CustomerPayload;
    body: IShoppingMallAiBackendFavoriteProduct.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendFavoriteProduct> {
  const { customer, body } = props;

  // Pagination 기본값 및 상한값
  const MIN_PAGE = 1;
  const DEFAULT_LIMIT = 20;
  const MAX_LIMIT = 50;
  const page = typeof body.page === "number" && body.page > 0 ? body.page : MIN_PAGE;
  const limit = typeof body.limit === "number" && body.limit > 0 && body.limit <= MAX_LIMIT ? body.limit : DEFAULT_LIMIT;
  const offset = (page - 1) * limit;

  // 검색어 필터: 상품명
  const productWhere = (body.query && body.query.length > 0)
    ? {
        product: {
          name: {
            contains: body.query,
            mode: "insensitive" as const,
          },
        },
      }
    : {};

  // 날짜 필터: created_at 범위 조건
  let createdAtFilter: { gte?: string; lte?: string } = {};
  if (body.from_date !== undefined && body.from_date !== null) {
    createdAtFilter.gte = body.from_date;
  }
  if (body.to_date !== undefined && body.to_date !== null) {
    createdAtFilter.lte = body.to_date;
  }

  // 기본 where 조건 (고객 본인만, 미삭제)
  const where = {
    customer_id: customer.id,
    deleted_at: null,
    ...(body.product_id !== undefined && body.product_id !== null
      ? { product_id: body.product_id }
      : {}),
    // created_at 필터는 값이 있을때만 적용
    ...((createdAtFilter.gte || createdAtFilter.lte)
      ? { created_at: createdAtFilter }
      : {}),
    ...productWhere,
  };

  // 병렬 조회 (데이터 & 전체 개수)
  const [rows, totalRecords] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.findMany({
      where,
      include: { product: true },
      orderBy: { created_at: "desc" },
      skip: offset,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_products.count({ where }),
  ]);

  // 반환 데이터 변환 (Date → ISO string, 타입 맞춤)
  const data = rows.map((row) => ({
    id: row.id,
    customer_id: row.customer_id,
    product_id: row.product_id,
    created_at: toISOStringSafe(row.created_at),
    deleted_at: row.deleted_at ? toISOStringSafe(row.deleted_at) : null,
    // 필요한 경우 product 정보 확장 가능
  }));

  // 페이지네이션 정보 생성
  const pagination = {
    current: page,
    limit,
    records: totalRecords,
    pages: Math.ceil(totalRecords / limit),
  };

  return {
    pagination,
    data,
  } satisfies IPageIShoppingMallAiBackendFavoriteProduct;
}

