export async function get__shoppingMallAiBackend_customer_favoriteProducts_$favoriteProductId(props: {
  customer: CustomerPayload;
  favoriteProductId: string & tags.Format<'uuid'>;
}): Promise<IShoppingMallAiBackendFavoriteProduct> {
