 *
 * 이 엔드포인트는 인증된 고객이 자신의 즐겨찾기 문의 항목만을 업데이트 또는 해제(소프트 삭제)할 수 있습니다.
 * 이미 삭제된 항목을 다시 삭제하거나 소유권이 없는 항목 접근 시 오류를 발생합니다.
 *
 * @param props - 요청 속성
 * @param props.customer - 인증된 고객 페이로드
 * @param props.favoriteInquiryId - 수정 또는 삭제할 즐겨찾기 문의 UUID
 * @param props.body - 즐겨찾기 문의 상태(삭제 시 deleted_at 포함)
 * @returns 업데이트된 즐겨찾기 문의 객체 (API DTO)
 * @throws {Error} 즐겨찾기 문의를 찾을 수 없거나, 소유권이 없거나, 이미 요청된 상태와 동일한 경우
 */
export async function put__shoppingMallAiBackend_customer_favoriteInquiries_$favoriteInquiryId(
  props: {
    customer: CustomerPayload;
    favoriteInquiryId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendFavoriteInquiry.IUpdate;
  }
): Promise<IShoppingMallAiBackendFavoriteInquiry> {
  const { customer, favoriteInquiryId, body } = props;

  // 1. 즐겨찾기 문의 항목 조회
  const found = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.findUnique({
    where: { id: favoriteInquiryId }
  });
  if (!found) throw new Error('즐겨찾기 문의를 찾을 수 없습니다.');

  // 2. 소유권 검사
  if (found.customer_id !== customer.id) {
    throw new Error('권한이 없습니다. 자신의 즐겨찾기 문의만 수정할 수 있습니다.');
  }

  // 3. 논리적 상태 검사 및 이미 요청된 상태면 오류
  const isUnfavoriting = body.deleted_at !== undefined && body.deleted_at !== null;
  if (isUnfavoriting && found.deleted_at !== null) {
    throw new Error('이미 즐겨찾기가 해제된 항목입니다.');
  }
  if (!isUnfavoriting && found.deleted_at === null) {
    throw new Error('이미 즐겨찾기로 등록된 상태입니다.');
  }

  // 4. 업데이트 (deleted_at만 변경, undefined면 필드 적용하지 않음)
  const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_inquiries.update({
    where: { id: favoriteInquiryId },
    data: { deleted_at: body.deleted_at ?? undefined },
  });

  // 5. 결과 반환(날짜는 ISO8601 문자열로 변환)
  return {
    id: updated.id as string & tags.Format<'uuid'>,
    customer_id: updated.customer_id as string & tags.Format<'uuid'>,
    inquiry_id: updated.inquiry_id as string & tags.Format<'uuid'>,
    created_at: toISOStringSafe(updated.created_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

