 *
 * This also unsubscribes the user from AI-driven notifications about the inquiry thread.
 *
 * @param props - Request properties
 * @param props.customer - The authenticated customer performing the unfavorite
 * @param props.favoriteInquiryId - The UUID of the favorite inquiry
 * @returns void
 * @throws {Error} If the favorite inquiry does not exist
 * @throws {Error} If the customer does not own this favorite inquiry
 */
export async function delete__shoppingMallAiBackend_customer_favoriteInquiries_$favoriteInquiryId(
  props: {
