 * @param props.body - Filtering and paging parameters (address_id, created_at range, deleted filter, page, limit)
 * @returns Paginated favorite address list (with metadata for display/UIs)
 * @throws {Error} If any database operation fails or invalid parameter is received
 */
export async function patch__shoppingMallAiBackend_customer_favoriteAddresses(props: {
  customer: CustomerPayload;
  body: IShoppingMallAiBackendFavoriteAddress.IRequest;
}): Promise<IPageIShoppingMallAiBackendFavoriteAddress> {
  const { customer, body } = props;

  // Pagination with defaults (page>=1, limit>=1, <=100)
  const page = typeof body.page === "number" && body.page >= 1 ? body.page : 1;
  const limit = typeof body.limit === "number" && body.limit >= 1 && body.limit <= 100 ? body.limit : 20;

  // Build created_at filter properly with gte/lte
  let createdAtFilter: { gte?: string; lte?: string } | undefined = undefined;
  if (body.created_at_from) {
    createdAtFilter = { ...(createdAtFilter ?? {}), gte: body.created_at_from };
  }
  if (body.created_at_to) {
    createdAtFilter = { ...(createdAtFilter ?? {}), lte: body.created_at_to };
  }

  // Compose where clause
  const where = {
    customer_id: customer.id,
    ...(body.address_id && { address_id: body.address_id }),
    ...(createdAtFilter && { created_at: createdAtFilter }),
    // Only exclude soft-deleted records unless deleted===true
    ...(body.deleted === true ? {} : { deleted_at: null }),
  };

  // Query paginated results and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip: (page - 1) * limit,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.count({ where })
  ]);

  // Map and convert Date fields for type compatibility
  return {
    pagination: {
      current: page,
      limit,
      records: total,
      pages: Math.max(1, Math.ceil(total / limit)),
    },
    data: rows.map(row => ({
      id: row.id,
      customer_id: row.customer_id,
      address_id: row.address_id,
      created_at: toISOStringSafe(row.created_at),
