 * This endpoint allows an authenticated customer to soft-unfavorite or restore a favorite address by updating the deleted_at field.
 * Only the owner may perform this update. Throws if record doesn't exist, isn't owned by customer, is already in the desired state, or for any invalid state change.
 *
 * @param props.customer - Authenticated customer session payload
 * @param props.favoriteAddressId - The UUID of the favorite address record to update
 * @param props.body - The update payload (IShoppingMallAiBackendFavoriteAddress.IUpdate)
 * @returns The updated favorite address record
 * @throws {Error} If favorite address not found, ownership is invalid, or operation is redundant/invalid
 */
export async function put__shoppingMallAiBackend_customer_favoriteAddresses_$favoriteAddressId(
  props: {
    customer: CustomerPayload;
    favoriteAddressId: string & tags.Format<'uuid'>;
    body: IShoppingMallAiBackendFavoriteAddress.IUpdate;
  }
): Promise<IShoppingMallAiBackendFavoriteAddress> {
