  const favorite = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.findUnique({
    where: { id: favoriteAddressId },
  });
  if (!favorite) throw new Error("Favorite address not found");
  if (favorite.customer_id !== customer.id) throw new Error("Unauthorized: not owner");

  const requestUnfavorite = body.deleted_at != null;
  const currentlyUnfavorited = favorite.deleted_at != null;

