      customer_id: updated.customer_id,
      address_id: updated.address_id,
      created_at: toISOStringSafe(updated.created_at),
      deleted_at: toISOStringSafe(updated.deleted_at!),
    };
  } else {
    if (!currentlyUnfavorited) throw new Error("Favorite address is already active");
    const updated = await MyGlobal.prisma.shopping_mall_ai_backend_favorite_addresses.update({
      where: { id: favoriteAddressId },
      data: { deleted_at: null },
    });
    return {
      id: updated.id,
      customer_id: updated.customer_id,
      address_id: updated.address_id,
      created_at: toISOStringSafe(updated.created_at),
