import { AdminPayload } from "../decorators/payload/AdminPayload"

/**
 * Perform a complex filtered search and paged listing retrieval of articles from shopping_mall_ai_backend_articles for admin users.
 *
 * Supports advanced filtering by status, category, keyword, author, and date ranges. Full pagination and sorting are provided. Returns summary-level article data for admin/CMS listing views, ensuring only non-deleted (active) articles are returned. Authorization is strictly enforced by the AdminPayload contract.
 *
 * @param props - Request details
 * @param props.admin - The authenticated admin making the request
 * @param props.body - Advanced article search, filter, and pagination criteria
 * @returns Paginated summary listing of articles
 * @throws {Error} On database or business logic errors
 */
export async function patch__shoppingMallAiBackend_admin_articles(
  props: {
    admin: AdminPayload;
    body: IShoppingMallAiBackendArticle.IRequest;
  }
): Promise<IPageIShoppingMallAiBackendArticle.ISummary> {
  const { admin, body } = props;
  // Pagination defaults (min page=1)
  const page: number & tags.Type<'int32'> = (body.page && body.page > 0 ? body.page : 1) as number & tags.Type<'int32'>;
  const limit: number & tags.Type<'int32'> = (body.limit && body.limit > 0 ? body.limit : 20) as number & tags.Type<'int32'>;
  const skip = (page - 1) * limit;

  // Build flexible where clause
  const where = {
    deleted_at: null,
    ...(body.status !== undefined && body.status !== null && { status: body.status }),
    ...(body.category_id !== undefined && body.category_id !== null && { category_id: body.category_id }),
    ...(body.author_type !== undefined && body.author_type !== null && { author_type: body.author_type }),
    ...(body.author_id !== undefined && body.author_id !== null && { author_id: body.author_id }),
    ...(body.created_from !== undefined && body.created_from !== null && { created_at: { gte: body.created_from } }),
    ...(body.created_to !== undefined && body.created_to !== null && { created_at: { lte: body.created_to } }),
    ...(body.updated_from !== undefined && body.updated_from !== null && { updated_at: { gte: body.updated_from } }),
    ...(body.updated_to !== undefined && body.updated_to !== null && { updated_at: { lte: body.updated_to } }),
    ...((body.keyword !== undefined && body.keyword !== null && body.keyword.length > 0)
      ? {
          OR: [
            { title: { contains: body.keyword, mode: "insensitive" as const } },
            { summary: { contains: body.keyword, mode: "insensitive" as const } },
            { body: { contains: body.keyword, mode: "insensitive" as const } }
          ]
        }
      : {}),
  };

  // Define allowed sort fields
  const allowedSortFields = ["created_at", "view_count", "comment_count"];
  const sort_by = allowedSortFields.includes(body.sort_by ?? "") ? body.sort_by! : "created_at";
  const sort_dir = body.sort_dir === "asc" ? "asc" : "desc";

  // Query articles (paged) and total count in parallel
  const [rows, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_ai_backend_articles.findMany({
      where,
      skip,
      take: limit,
      orderBy: { [sort_by]: sort_dir },
    }),
    MyGlobal.prisma.shopping_mall_ai_backend_articles.count({ where }),
  ]);

  // Map DB rows to DTO summary format, enforce correct output types
  const data = rows.map(row => ({
    id: row.id,
    title: row.title,
    summary: row.summary ?? null,
    category_id: row.category_id,
    author_type: row.author_type,
    author_id: row.author_id,
    status: row.status,
    view_count: row.view_count as number & tags.Type<'int32'>,
    comment_count: row.comment_count as number & tags.Type<'int32'>,
    created_at: toISOStringSafe(row.created_at),
    updated_at: toISOStringSafe(row.updated_at),
  }));

  return {
    pagination: {
      current: page,
      limit,
      records: total as number & tags.Type<'int32'>,
      pages: Math.ceil(total / limit) as number & tags.Type<'int32'>,
    },
    data,
  };
}

