/**
 * Change password for an authenticated customer account (shopping_mall_ai_backend_customers).
 *
 * This API enables secure, policy-compliant password change for authenticated customers. It verifies the provided current password against the stored hash, checks the new password against strength requirements, updates the customer's password hash upon success, and records a full audit trail in customer_histories. Enforces browser-only security best practices (Web Crypto API).
 *
 * @param props - Contains authenticated CustomerPayload as 'customer' and the request body (currentPassword, newPassword) as 'body'.
 * @returns Response indicating success/failure and detail message for UI feedback.
 * @throws {Error} When systemic validation or DB failure occurs.
 */
export async function put__auth_customer_password(props: {
  customer: CustomerPayload;
  body: ICustomerChangePassword.Request;
}): Promise<ICustomerChangePassword.Response> {
  const { customer, body } = props;

  // Step 1: Fetch the customer by id, must be active and not deleted
  const dbCustomer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: {
      id: customer.id,
      status: "active",
      deleted_at: null,
    },
  });
  if (!dbCustomer)
    return { success: false, message: "Customer not found or inactive/deleted." };

  // Step 2: Verify current password (Web Crypto API; SHA-256; base64-encoded string matching)
  // We assume password_hash is base64(SHA-256(password))
  async function hashPassword(pw: string): Promise<string> {
    const enc = new TextEncoder();
    const data = enc.encode(pw);
    const hashBuf = await (globalThis.crypto || (globalThis as any).webcrypto).subtle.digest(
      "SHA-256",
      data
    );
    return Buffer.from(new Uint8Array(hashBuf)).toString("base64");
  }
  // For Node compat (testing): `crypto.subtle` may not be available; adapt if so.

  const isPasswordValid =
    (await hashPassword(body.currentPassword)) === dbCustomer.password_hash;
  if (!isPasswordValid)
    return { success: false, message: "Current password is incorrect." };

  // Step 3: Check new password policy (min 8 chars, at least letter & number)
  const passwordPolicy = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{8,}$/;
  if (!passwordPolicy.test(body.newPassword)) {
    return {
      success: false,
      message:
        "New password does not meet security requirements (min 8 chars, at least 1 letter and 1 number).",
    };
  }

  // Step 4: Hash new password
  const newPasswordHash = await hashPassword(body.newPassword);

  // Step 5: Update user password_hash and updated_at (no intermediate variables)
  const updatedAt = toISOStringSafe(new Date());
  await MyGlobal.prisma.shopping_mall_ai_backend_customers.update({
    where: { id: customer.id },
    data: {
      password_hash: newPasswordHash,
      updated_at: updatedAt,
    },
  });

  // Step 6: Record password change in customer_histories
  const now = updatedAt; // Use same ISO string for audit
  await MyGlobal.prisma.shopping_mall_ai_backend_customer_histories.create({
    data: {
      id: v4() as string & tags.Format<'uuid'>,
      customer_id: customer.id,
      event_type: "password_changed",
      old_value_json: JSON.stringify({ password_hash: "****" }),
      new_value_json: null,
      triggered_by: "customer",
      meta_json: null,
      occurred_at: now,
      created_at: now,
    },
  });

  // Step 7: Return success
  return {
    success: true,
    message: "Password updated successfully.",
  };
}

