/**
 * Change password for authenticated admin (shopping_mall_ai_backend_admins, password_hash).
 *
 * Allows an authenticated admin to securely change their login password, by providing current password and desired new password. Uses the 'password_hash' field in shopping_mall_ai_backend_admins to validate the old password and securely store the new hashed password. All events are compliance-audited. This operation is critical for RBAC maintenance and user security, ensuring only the correct admin can change their credentials. Integrates with the core authentication cycle: signUp, signIn, signOut, and validateToken for compliant access control.
 *
 * @param props - Request properties
 * @param props.admin - The authenticated admin making the request
 * @param props.body - Request payload containing currentPassword and newPassword
 * @returns Result object with success boolean and message string
 * @throws {Error} When admin does not exist, is deleted, or when the current password is wrong
 */
export async function put__auth_admin_password(
  props: {
    admin: AdminPayload;
    body: IAdminAuth.ChangePassword;
  }
): Promise<IAdminAuth.ChangePasswordResult> {
  const { admin, body } = props;
  // 1. Find admin record (active only, soft-delete safe)
  const dbAdmin = await MyGlobal.prisma.shopping_mall_ai_backend_admins.findFirst({
    where: {
      id: admin.id,
      deleted_at: null,
      status: "active",
    },
  });
  if (!dbAdmin) {
    throw new Error("Admin not found or inactive");
  }

  // 2. Validate current password (compare hash with existing)
  const currentHash = await browserCompatiblePasswordHash(body.currentPassword);
  if (currentHash !== dbAdmin.password_hash) {
    return {
      success: false,
      message: "Current password is incorrect.",
    };
  }

  // 3. Hash new password (browser-compatible)
  const newPasswordHash = await browserCompatiblePasswordHash(body.newPassword);

  // 4. Update DB (password_hash+updated_at)
  await MyGlobal.prisma.shopping_mall_ai_backend_admins.update({
    where: { id: admin.id },
    data: {
      password_hash: newPasswordHash,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    success: true,
    message: "Password changed successfully.",
  };
}

/**
 * Hashes a plaintext password using Web Crypto API's subtle.digest (SHA-256) in a browser-compatible manner.
 * Note: For enterprise, salt+key derivation/PBKDF2 is required. For basic demo, this is a one-shot hash.
 * @param password - The password to hash
 * @returns hex-encoded SHA-256 digest string
 */
async function browserCompatiblePasswordHash(password: string): Promise<string> {
  // Use TextEncoder to encode the password string
  const encoder = new TextEncoder();
  const passwordBytes = encoder.encode(password);
  // Browser-compatible SHA-256 digest
  const digestBuffer = await (window.crypto || self.crypto).subtle.digest("SHA-256", passwordBytes);
  // Convert buffer to hex string
  return Array.from(new Uint8Array(digestBuffer))
    .map(b => b.toString(16).padStart(2, "0"))
    .join("");
}

