import { MyGlobal } from "../../MyGlobal";
import { jwtAuthorize } from "./jwtAuthorize";
import { CustomerPayload } from "../../decorators/payload/CustomerPayload";

/**
 * Authenticate and authorize customer JWT tokens and session.
 * Validates token, checks type, and ensures account is not deleted.
 * Throws ForbiddenException if status is not valid.
 */
export async function customerAuthorize(request: {
  headers: {
    authorization?: string;
  };
}): Promise<CustomerPayload> {
  const payload: CustomerPayload = jwtAuthorize({ request }) as CustomerPayload;

  if (payload.type !== "customer") {
    throw new ForbiddenException(`You're not ${payload.type}`);
  }

  // Find customer with validation on deleted_at and status (must be 'active')
  const customer = await MyGlobal.prisma.shopping_mall_ai_backend_customers.findFirst({
    where: {
      id: payload.id,
      deleted_at: null,
      status: "active",
    },
  });

  if (customer === null) {
    throw new ForbiddenException("You're not enrolled or your account is inactive/deleted");
  }

  return payload;
}

